-- =====================================================================
--  June  —  the words, moved behind the paywall
--
--  WHAT THIS DOES
--  Creates `book_nights` if it is not there yet, and puts 28 nights of
--  A Heart That Follows the Lord into it. The table carries the same rule as
--  story_texts: Postgres hands a row to a subscriber, or to anyone for a
--  story marked free, and to nobody else.
--
--  HOW TO RUN IT
--    Supabase  ->  SQL Editor  ->  New query  ->  paste  ->  Ctrl+A  ->  Run
--
--  Safe to run more than once: it updates rather than duplicating.
--  Run the three book files in any order.
-- =====================================================================

create table if not exists public.book_nights (
  id         text primary key,   -- the catalog id, e.g. 'b6-w1-n1'
  book       int,
  night      text,               -- "Week 1 · Night 1"
  title      text,
  reference  text,
  beats      jsonb not null,     -- the whole night: pictures, words, moments
  is_free    boolean not null default false,
  updated_at timestamptz not null default now()
);

alter table public.book_nights enable row level security;

-- The same rule story_texts already uses. Editing the website's JavaScript
-- gets a reader precisely nothing, because the words never leave the database.
drop policy if exists "read book night" on public.book_nights;
create policy "read book night"
  on public.book_nights for select
  to authenticated
  using (is_free or public.lst_is_subscriber());

-- ---------------------------------------------------------------------
--  A Heart That Follows the Lord
-- ---------------------------------------------------------------------
insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b6-w1-n1', 6, 'Week 1 · Night 1', 'Ruth Stays with Naomi', 'Ruth 1', '[{"type": "cover", "img": "images/book/jun-01-0.jpg", "alt": "Cover illustration for “Ruth Stays with Naomi”"}, {"type": "story", "img": "images/book/jun-01-1.jpg", "alt": "Illustration: Naomi lived far from home with her husband and two sons.", "text": ["Naomi lived far from home with her husband and two sons. Sadly, her husband died. Then both of her sons died too. Naomi felt very sad and alone.", "Naomi’s daughter-in-law Ruth loved her very much. Naomi said, “You should go back to your family.” But Ruth said something beautiful: “Where you go, I will go. Your people will be my people. Your God will be my God.”"]}, {"type": "story", "img": "images/book/jun-01-2.jpg", "alt": "Illustration: Ruth chose to stay with Naomi even though it was hard.", "text": ["Ruth chose to stay with Naomi even though it was hard. They traveled together to a new land called Bethlehem. Ruth took care of Naomi because she loved her.", "Ruth was loyal and kind. She didn’t leave Naomi when things got hard. Her love was stronger than her troubles."]}, {"type": "moment", "img": "images/book/jun-01-3.jpg", "alt": "Illustration: Put your arm around someone next to you, or give yourself a hug.", "text": ["Put your arm around someone next to you, or give yourself a hug. That’s what Ruth did for Naomi — she stayed close when Naomi needed her most. Real love means staying with people even when things are hard. Close your eyes and think of someone you love. Can you picture yourself staying with them and helping them?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["YOU can be loyal like Ruth! When your friend is sad, stay with them. When your sibling needs help, don’t leave. When things get hard, don’t give up on people you love. Ruth didn’t run away when Naomi was sad — she stayed and helped. You can do the same thing! Who needs you to be a loyal friend this week?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jun-01-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What did Ruth say to Naomi? Why did Ruth stay with her?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jun-01-5.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b6-w1-n2', 6, 'Week 1 · Night 2', 'Ruth Works in the Field', 'Ruth 2', '[{"type": "cover", "img": "images/book/jun-02-0.jpg", "alt": "Cover illustration for “Ruth Works in the Field”"}, {"type": "story", "img": "images/book/jun-02-1.jpg", "alt": "Illustration: Ruth and Naomi needed food.", "text": ["Ruth and Naomi needed food. Ruth said, “I will go work in the fields.” She went to pick up leftover grain that the workers dropped.", "Ruth worked in a field that belonged to a kind man named Boaz. Boaz saw Ruth working hard. He told his workers, “Be extra kind to Ruth. Leave extra grain for her to find.”"]}, {"type": "story", "img": "images/book/jun-02-2.jpg", "alt": "Illustration: At the end of the day, Ruth had lots of grain!", "text": ["At the end of the day, Ruth had lots of grain! She hurried home to show Naomi. Ruth worked hard all day to take care of Naomi. p013_sceneB Ruth was humble and worked hard. Boaz was kind and generous. They both pleased Heavenly Father with their choices."]}, {"type": "moment", "img": "images/book/jun-02-3.jpg", "alt": "Illustration: Pretend you’re picking things up from the ground — bend down, pick up, put in a basket.", "text": ["Pretend you’re picking things up from the ground — bend down, pick up, put in a basket. Do it a few times. That’s hard work! Ruth did that ALL day to get food for Naomi. Your arms would get tired! But Ruth kept working because she loved Naomi. Think about how it feels when you work hard to help someone you love."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["YOU can work hard to help people too! When you clean up your toys, you’re helping your family. When you help set the table, you’re being useful. When you do your chores without complaining, you’re being like Ruth! Hard work shows love. Ruth could have complained or been lazy, but she worked happily to help Naomi. What’s one job you can do this week to help your family?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jun-02-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["How did Ruth get food? What did Boaz do to help her?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jun-02-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b6-w1-n3', 6, 'Week 1 · Night 3', 'Boaz Marries Ruth', 'Ruth 3–4', '[{"type": "cover", "img": "images/book/jun-03-0.jpg", "alt": "Cover illustration for “Boaz Marries Ruth”"}, {"type": "story", "img": "images/book/jun-03-1.jpg", "alt": "Illustration: Boaz thought Ruth was wonderful.", "text": ["Boaz thought Ruth was wonderful. Ruth was kind, hard-working, and loyal. Boaz wanted to take care of Ruth and Naomi.", "Boaz asked Ruth to marry him. Ruth said yes! They had a beautiful wedding. Now Ruth had a loving husband who would take care of her and Naomi."]}, {"type": "story", "img": "images/book/jun-03-2.jpg", "alt": "Illustration: Later, Ruth and Boaz had a baby boy named Obed.", "text": ["Later, Ruth and Boaz had a baby boy named Obed. Naomi was so happy to hold the baby! Ruth’s hard work and kindness led to great blessings.", "Ruth’s story shows that when we’re faithful and kind, Heavenly Father blesses us. Ruth went from being sad and alone to having a family and being happy!"]}, {"type": "moment", "img": "images/book/jun-03-3.jpg", "alt": "Illustration: Smile really big and hug yourself tight.", "text": ["Smile really big and hug yourself tight. That’s how happy endings feel! Ruth started out sad — her husband died, she had no food, everything was hard. But she stayed faithful and kind, and look what happened! She got a loving husband, a baby, and Naomi was taken care of. When you do what’s right, even when it’s hard, Heavenly Father gives you blessings."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Sometimes things are hard for a while. Maybe you’re sad, or scared, or something isn’t going well. But if you keep being kind and working hard like Ruth, good things will come! Heavenly Father sees everything you do. He sees when you’re kind, when you work hard, when you’re loyal. And He WILL bless you for it, just like He blessed Ruth! What’s something hard you’re going through? Can you keep being faithful like Ruth?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jun-03-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What blessings did Ruth receive for being faithful and kind?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jun-03-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b6-w1-n4', 6, 'Week 1 · Night 4', 'Hannah Prays for a Baby', '1 Samuel 1', '[{"type": "cover", "img": "images/book/jun-04-0.jpg", "alt": "Cover illustration for “Hannah Prays for a Baby”"}, {"type": "story", "img": "images/book/jun-04-1.jpg", "alt": "Illustration: Hannah wanted a baby very much.", "text": ["Hannah wanted a baby very much. But she didn’t have any children. This made her so sad that she cried and cried.", "Hannah went to the temple to pray. She prayed with all her heart: “Heavenly Father, please give me a son. If You do, I’ll let him serve You all his life.”"]}, {"type": "story", "img": "images/book/jun-04-2.jpg", "alt": "Illustration: Heavenly Father heard Hannah’s prayer.", "text": ["Heavenly Father heard Hannah’s prayer. He gave her a baby boy! Hannah named him Samuel. She was SO happy!", "Hannah kept her promise. When Samuel was old enough, she took him to the temple to serve Heavenly Father. Hannah’s prayers were answered because she had faith."]}, {"type": "moment", "img": "images/book/jun-04-3.jpg", "alt": "Illustration: Put your hands together like you’re praying.", "text": ["Put your hands together like you’re praying. Now close your eyes and imagine praying about something you REALLY want. That’s what Hannah did! She prayed with all her heart. When you pray like that — really meaning it, really trusting Heavenly Father — He hears you. Open your eyes. Did you feel how powerful prayer can be?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When you want something really badly, YOU can pray like Hannah! Tell Heavenly Father what you need. Pray with all your heart. Then trust that He will answer in the best way. Sometimes He says yes right away. Sometimes He makes you wait. Sometimes He says yes in a different way than you expected. But He ALWAYS hears you! What’s something you can pray about with all your heart this week?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jun-04-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What did Hannah pray for? Did Heavenly Father answer her prayer?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jun-04-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b6-w1-n5', 6, 'Week 1 · Night 5', 'Samuel Goes to the Temple', '1 Samuel 2', '[{"type": "cover", "img": "images/book/jun-05-0.jpg", "alt": "Cover illustration for “Samuel Goes to the Temple”"}, {"type": "story", "img": "images/book/jun-05-1.jpg", "alt": "Illustration: When Samuel was still a little boy, Hannah kept her promise.", "text": ["When Samuel was still a little boy, Hannah kept her promise. She brought Samuel to the temple. An old priest named Eli lived there.", "Hannah said, “This is the son I prayed for. Now I’m giving him back to Heavenly Father to serve Him.” Samuel would live at the temple and help Eli."]}, {"type": "story", "img": "images/book/jun-05-2.jpg", "alt": "Illustration: Every year, Hannah came to visit Samuel.", "text": ["Every year, Hannah came to visit Samuel. She brought him a new coat that she made. Samuel grew bigger and stronger each year.", "Samuel was obedient and helpful. He learned to serve Heavenly Father from a young age. Hannah’s gift to God was her precious son."]}, {"type": "moment", "img": "images/book/jun-05-3.jpg", "alt": "Illustration: Imagine your mommy has to leave you somewhere for a long time.", "text": ["Imagine your mommy has to leave you somewhere for a long time. You’d miss her SO much! That’s what happened to Samuel. But he was brave. He knew he was doing something important for Heavenly Father. Give yourself a brave squeeze on your shoulders. That’s what it feels like to do something hard because it’s right."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Sometimes Heavenly Father asks us to do hard things. Maybe go to a new school. Maybe share something special. Maybe be brave when you’re scared. Samuel was just a little boy when he went to live at the temple — probably younger than you! But he was brave and obedient. YOU can be brave too when Heavenly Father asks you to do hard things. What’s something hard Heavenly Father might want you to do?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jun-05-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["Why did Hannah take Samuel to the temple? Was Samuel obedient?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jun-05-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b6-w1-n6', 6, 'Week 1 · Night 6', 'The Lord Calls Samuel', '1 Samuel 3', '[{"type": "cover", "img": "images/book/jun-06-0.jpg", "alt": "Cover illustration for “The Lord Calls Samuel”"}, {"type": "story", "img": "images/book/jun-06-1.jpg", "alt": "Illustration: One night, Samuel was sleeping at the temple.", "text": ["One night, Samuel was sleeping at the temple. Suddenly he heard someone call his name: “Samuel! Samuel!” He ran to Eli and said, “Here I am!”", "But Eli said, “I didn’t call you. Go back to bed.” Samuel went back to bed. Again he heard, “Samuel!” He ran to Eli again, but Eli said, “I didn’t call you.”"]}, {"type": "story", "img": "images/book/jun-06-2.jpg", "alt": "Illustration: This happened THREE times!", "text": ["This happened THREE times! Finally Eli understood: it was Heavenly Father calling Samuel! Eli said, “Next time, say: ‘Speak, Lord, for I am listening.’”", "When Samuel heard the voice again, he said, “Speak, Lord, for I am listening.” Heavenly Father gave Samuel an important message. Samuel became a great prophet!"]}, {"type": "moment", "img": "images/book/jun-06-3.jpg", "alt": "Illustration: Be very, very quiet.", "text": ["Be very, very quiet. Put your finger to your lips. Shhhh. Now listen really carefully. Can you hear tiny sounds? That’s how Samuel had to listen to hear Heavenly Father’s voice. It wasn’t loud like thunder. It was quiet and gentle. Heavenly Father speaks to you too, but you have to be still and quiet to hear Him."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Heavenly Father speaks to YOU through the Holy Ghost! It’s like a quiet feeling in your heart that tells you what’s right. But you have to be quiet and listen, just like Samuel. When you pray, don’t just talk — be quiet and listen too. When you’re trying to make a choice, listen to that feeling inside. That’s Heavenly Father talking to you! When have you felt the Holy Ghost helping you know what to do?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jun-06-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["Who was calling Samuel’s name? What did Samuel say when he listened?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jun-06-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b6-w1-n7', 6, 'Week 1 · Night 7', 'God’s Power and the Ark', '1 Samuel 4–7', '[{"type": "cover", "img": "images/book/jun-07-0.jpg", "alt": "Cover illustration for “God’s Power and the Ark”"}, {"type": "story", "img": "images/book/jun-07-1.jpg", "alt": "Illustration: Israel had a special golden box called the Ark of the Covenant.", "text": ["Israel had a special golden box called the Ark of the Covenant. It held the Ten Commandments. The Ark showed that Heavenly Father was with His people.", "Israel’s enemies captured the Ark in battle! They took it to their city. But wherever they put the Ark, bad things happened. Their false god statue fell down and broke!"]}, {"type": "story", "img": "images/book/jun-07-2.jpg", "alt": "Illustration: The enemies got scared.", "text": ["The enemies got scared. They said, “This God is too powerful! We need to send the Ark back!” They put it on a cart and sent it back to Israel.", "The Israelites were SO happy to have the Ark back! They learned that Heavenly Father is more powerful than anything. When they followed Him, He protected them."]}, {"type": "moment", "img": "images/book/jun-07-3.jpg", "alt": "Illustration: Stand up and make yourself as big and strong as you can — stretch your arms wide, stand on your tiptoes, make…", "text": ["Stand up and make yourself as big and strong as you can — stretch your arms wide, stand on your tiptoes, make a strong face! That’s how POWERFUL Heavenly Father is — even MORE powerful than that! Nothing is stronger than God. Not enemies, not false gods, not anything! When you trust in Heavenly Father, you have the STRONGEST helper ever!"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When you’re scared of something, remember: Heavenly Father is more powerful than ANYTHING! More powerful than bullies. More powerful than the dark. More powerful than anything that scares you. The enemies learned that the hard way when they tried to keep the Ark! You can pray to Heavenly Father when you’re scared, and His power will protect you. What’s something you’re scared of? Can you ask Heavenly Father to help you with His power?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jun-07-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What was special about the Ark? What did it teach the enemies?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jun-07-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b6-w2-n1', 6, 'Week 2 · Night 1', 'Israel Wants a King', '1 Samuel 8', '[{"type": "cover", "img": "images/book/jun-08-0.jpg", "alt": "Cover illustration for “Israel Wants a King”"}, {"type": "story", "img": "images/book/jun-08-1.jpg", "alt": "Illustration: The prophet Samuel was getting old.", "text": ["The prophet Samuel was getting old. He had been Israel’s leader for a long time. The people came to Samuel and said, “We want a king like all the other nations have!”", "Samuel felt sad. He prayed to Heavenly Father. God said, “The people aren’t rejecting you, Samuel. They’re rejecting ME as their king.”"]}, {"type": "story", "img": "images/book/jun-08-2.jpg", "alt": "Illustration: Samuel warned the people: “A king will take your sons for his army.", "text": ["Samuel warned the people: “A king will take your sons for his army. He’ll take your daughters to work for him. He’ll take your best fields and animals.” But the people said, “We still want a king!”", "Sometimes we want things just because others have them. But Heavenly Father knows what’s best for us. The Israelites learned this the hard way."]}, {"type": "moment", "img": "images/book/jun-08-3.jpg", "alt": "Illustration: Stand up tall like you’re a king with a crown.", "text": ["Stand up tall like you’re a king with a crown. Now bow down low. The Israelites wanted a human king they could see, but they already HAD the best King ever — Heavenly Father! Sometimes we want what others have and forget to be grateful for what Heavenly Father has already given us. Close your eyes and think of three blessings you already have."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Do you ever want something just because your friend has it? A toy, a treat, or something special? The Israelites did that! They wanted a king because everyone else had one. But wanting things just because others have them isn’t always wise. Instead, YOU can: be grateful for what you have, trust Heavenly Father’s plan, and remember that He knows what’s best. What’s something you’re grateful for that you already have?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jun-08-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["Why did Israel want a king? Was this what Heavenly Father wanted?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jun-08-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b6-w2-n2', 6, 'Week 2 · Night 2', 'Saul Looks for Donkeys', '1 Samuel 9', '[{"type": "cover", "img": "images/book/jun-09-0.jpg", "alt": "Cover illustration for “Saul Looks for Donkeys”"}, {"type": "story", "img": "images/book/jun-09-1.jpg", "alt": "Illustration: There was a young man named Saul.", "text": ["There was a young man named Saul. He was tall and handsome. One day, his father’s donkeys ran away. Saul and his servant went to look for them everywhere.", "After searching for days, they couldn’t find the donkeys. Saul said, “Let’s go home. My father will worry about us!” But his servant said, “There’s a prophet in this town. Maybe he can help us.”"]}, {"type": "story", "img": "images/book/jun-09-2.jpg", "alt": "Illustration: They went to find the prophet Samuel.", "text": ["They went to find the prophet Samuel. But Samuel already knew Saul was coming! Heavenly Father had told Samuel, “Tomorrow I’ll send you the man who will be Israel’s king.”", "Saul was just looking for donkeys, but Heavenly Father had a much bigger plan! Sometimes when we’re doing simple things, God is preparing us for something great."]}, {"type": "moment", "img": "images/book/jun-09-3.jpg", "alt": "Illustration: Pretend you’re looking for something lost — look left, look right, look behind you.", "text": ["Pretend you’re looking for something lost — look left, look right, look behind you. That’s what Saul was doing! He was just trying to find donkeys, doing a regular job for his father. But Heavenly Father was watching and had a special plan. When YOU do your regular jobs — like cleaning your room or helping your family — Heavenly Father sees you! He might be preparing you for something special too!"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When you’re doing everyday things like chores, homework, or helping your family, remember: Heavenly Father is watching! Saul was doing a simple job — looking for lost animals. But that job led him to Samuel, and then to becoming king! YOU never know when doing a good job on small things will lead to big blessings. So do your best, even in little tasks! What’s a small job you can do well this week?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jun-09-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What was Saul looking for? Who did he find instead?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jun-09-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b6-w2-n3', 6, 'Week 2 · Night 3', 'Saul is Anointed King', '1 Samuel 10', '[{"type": "cover", "img": "images/book/jun-10-0.jpg", "alt": "Cover illustration for “Saul is Anointed King”"}, {"type": "story", "img": "images/book/jun-10-1.jpg", "alt": "Illustration: Samuel took a special bottle of oil.", "text": ["Samuel took a special bottle of oil. He poured it on Saul’s head. This meant Saul was chosen to be king! Samuel said, “Heavenly Father has anointed you to be the leader of His people.”", "Later, Samuel gathered all of Israel together. He said, “Heavenly Father has chosen your king!” They drew lots, and Saul was chosen. But where was Saul? He was hiding!"]}, {"type": "story", "img": "images/book/jun-10-2.jpg", "alt": "Illustration: They found Saul hiding among the baggage.", "text": ["They found Saul hiding among the baggage. When he stood up, he was taller than everyone else! The people shouted, “Long live the king!”", "Saul started out humble and obedient. But being humble is important, even when you become important! God chose Saul because his heart was right at the beginning."]}, {"type": "moment", "img": "images/book/jun-10-3.jpg", "alt": "Illustration: Stand up as tall as you can — stretch way up!", "text": ["Stand up as tall as you can — stretch way up! Saul was SO tall, taller than everyone! But even though he was tall and chosen to be king, he felt scared and hid. Put your hands over your face like you’re hiding. Sometimes when we’re asked to do big things, we feel scared. But Heavenly Father will help you, just like He helped Saul! Take your hands away — be brave!"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Sometimes YOU might be asked to do something that feels too big or scary! Maybe speak in Primary, make a new friend, or try something new. You might want to hide like Saul did! But when Heavenly Father asks you to do something, He will help you be brave enough. You don’t have to be perfect or feel ready — just be willing! What’s something that feels scary that you can ask Heavenly Father to help you with?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jun-10-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["How did Samuel show Saul was chosen? Why was Saul hiding?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jun-10-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b6-w2-n4', 6, 'Week 2 · Night 4', 'Saul Doesn’t Wait', '1 Samuel 13', '[{"type": "cover", "img": "images/book/jun-11-0.jpg", "alt": "Cover illustration for “Saul Doesn’t Wait”"}, {"type": "story", "img": "images/book/jun-11-1.jpg", "alt": "Illustration: Israel’s enemies were coming to attack!", "text": ["Israel’s enemies were coming to attack! King Saul and his soldiers were scared. Samuel told Saul, “Wait seven days. I’ll come and make an offering to Heavenly Father for you.”", "Saul waited. Day one, day two, day three... His soldiers started to leave because they were afraid! On day seven, Samuel still hadn’t come. Saul got impatient."]}, {"type": "story", "img": "images/book/jun-11-2.jpg", "alt": "Illustration: Saul said, “I can’t wait anymore!” He made the offering himself, even though only priests were supposed to do…", "text": ["Saul said, “I can’t wait anymore!” He made the offering himself, even though only priests were supposed to do that. Right after he finished, Samuel arrived!", "Samuel said, “You disobeyed! Because you didn’t wait and didn’t obey, you won’t be king forever. Heavenly Father will find someone else.” Saul’s impatience cost him everything."]}, {"type": "moment", "img": "images/book/jun-11-3.jpg", "alt": "Illustration: Let’s practice waiting!", "text": ["Let’s practice waiting! Close your eyes and count slowly: 1... 2... 3... 4... 5. That was only five seconds! Saul had to wait SEVEN DAYS! But he couldn’t wait. Tap your foot like you’re impatient — tap, tap, tap. That’s how Saul felt. Waiting is HARD! But sometimes Heavenly Father asks us to wait, and we need to obey even when it’s hard."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Do you ever have to wait for something and it feels SO hard? Maybe waiting for your birthday, waiting for dinner, or waiting for Mommy to be ready? Saul couldn’t wait for Samuel, and it got him in BIG trouble! YOU can practice patience by: waiting your turn, not interrupting when others are talking, waiting without complaining, and trusting that good things come to those who wait. What’s something you need to be patient about?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jun-11-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What was Saul supposed to wait for? What happened when he didn’t wait?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jun-11-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b6-w2-n5', 6, 'Week 2 · Night 5', 'Obey is Better Than Sacrifice', '1 Samuel 15', '[{"type": "cover", "img": "images/book/jun-12-0.jpg", "alt": "Cover illustration for “Obey is Better Than Sacrifice”"}, {"type": "story", "img": "images/book/jun-12-1.jpg", "alt": "Illustration: Heavenly Father told King Saul through Samuel: “Fight the Amalekites and destroy everything.” This was a test…", "text": ["Heavenly Father told King Saul through Samuel: “Fight the Amalekites and destroy everything.” This was a test to see if Saul would obey completely.", "Saul fought the battle. But he didn’t obey all the way! He kept the best animals and treasures. He thought, “I’ll sacrifice these to God. That will make up for not obeying.”"]}, {"type": "story", "img": "images/book/jun-12-2.jpg", "alt": "Illustration: Samuel came and heard the animals.", "text": ["Samuel came and heard the animals. “What’s this noise?” he asked. Saul said, “I kept them to sacrifice to God!” Samuel said something important: “To OBEY is better than sacrifice!”", "Saul tried to make excuses. But Heavenly Father doesn’t want excuses — He wants obedience! Because Saul disobeyed again, God chose a new king. Obedience matters more than anything!"]}, {"type": "moment", "img": "images/book/jun-12-3.jpg", "alt": "Illustration: Let’s try this: a grown-up will gently ask you to do something.", "text": ["Let’s try this: a grown-up will gently ask you to do something. When they say “Touch your nose,” you touch your nose. Good! Now imagine they said “Touch your nose” but you touched your ears instead and said “It’s close enough!” That’s what Saul did! Put your finger on your ear. Does that feel like obeying? No! Real obedience means doing EXACTLY what you’re asked, not almost.", "feelingA"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Sometimes YOU might want to obey only partway. Maybe Mommy says “clean your whole room” but you only make your bed. Or Daddy says “no treats before dinner” but you sneak one. That’s like Saul! Partial obedience isn’t obedience. Heavenly Father wants us to obey completely, not make excuses or do it our own way. When someone asks you to do something, do ALL of it, not just the easy parts! Can you think of a time you obeyed only partway?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jun-12-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What did God tell Saul to do? Did Saul obey all the way?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jun-12-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b6-w2-n6', 6, 'Week 2 · Night 6', 'God Chooses David', '1 Samuel 16:1–13', '[{"type": "cover", "img": "images/book/jun-13-0.jpg", "alt": "Cover illustration for “God Chooses David”"}, {"type": "story", "img": "images/book/jun-13-1.jpg", "alt": "Illustration: Heavenly Father told Samuel, “Go to Jesse’s house.", "text": ["Heavenly Father told Samuel, “Go to Jesse’s house. I’ve chosen one of his sons to be the next king.” Samuel went. Jesse had EIGHT sons!", "Jesse’s oldest son came first. He was tall and handsome! Samuel thought, “This must be the one!” But God said, “No. People look at the outside, but I look at the HEART.”"]}, {"type": "story", "img": "images/book/jun-13-2.jpg", "alt": "Illustration: Seven sons came.", "text": ["Seven sons came. They were all strong and impressive. But God said no to each one! Samuel asked, “Are these all your sons?” Jesse said, “Well, there’s David. He’s the youngest, watching the sheep.”", "They brought David in. He was just a young shepherd boy! But God said, “This is the one!” Samuel anointed David. God chose David not for how he looked, but for his good heart!"]}, {"type": "moment", "img": "images/book/jun-13-3.jpg", "alt": "Illustration: Look in a pretend mirror.", "text": ["Look in a pretend mirror. What do you see on the OUTSIDE? Your face, your hair, your clothes. Now put your hand over your heart. THAT’S what Heavenly Father sees! He looks at what’s INSIDE — if you’re kind, honest, faithful, and loving. You can’t see a heart in a mirror, but Heavenly Father can see your heart all the time! Make your heart happy by being kind!"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Sometimes people might judge you by how you look, how tall you are, or what clothes you wear. But Heavenly Father doesn’t care about that! HE looks at your heart. Is your heart kind? Is it honest? Is it faithful? YOU can have a good heart like David by: being kind to everyone, telling the truth, helping others, and loving Heavenly Father. It doesn’t matter if you’re the smallest or the youngest — if you have a good heart, you’re special to God! What’s one way you can make your heart better?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jun-13-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["Why didn’t God choose the older, bigger brothers? What did God see in David?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jun-13-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b6-w2-n7', 6, 'Week 2 · Night 7', 'David Plays Music for Saul', '1 Samuel 16:14–23', '[{"type": "cover", "img": "images/book/jun-14-0.jpg", "alt": "Cover illustration for “David Plays Music for Saul”"}, {"type": "story", "img": "images/book/jun-14-1.jpg", "alt": "Illustration: After Saul disobeyed, an evil spirit troubled him.", "text": ["After Saul disobeyed, an evil spirit troubled him. He felt sad and angry all the time. His servants said, “Let’s find someone to play music for you. Music might help!”", "Someone said, “Jesse’s son David plays the harp beautifully. He’s brave, speaks well, and the Lord is with him.” So they sent for David."]}, {"type": "story", "img": "images/book/jun-14-2.jpg", "alt": "Illustration: Whenever the evil spirit troubled Saul, David would play his harp.", "text": ["Whenever the evil spirit troubled Saul, David would play his harp. The beautiful music calmed Saul down and made him feel better. The evil spirit would leave!", "David used his talent to help someone who was hurting. Music from a pure heart has special power! When we use our gifts to help others, we’re serving Heavenly Father."]}, {"type": "moment", "img": "images/book/jun-14-3.jpg", "alt": "Illustration: Hum a soft, pretty tune.", "text": ["Hum a soft, pretty tune. Feel how peaceful that is? Now make angry sounds — “GRRRR!” Feel how different that is? King Saul felt angry and troubled. But when David played beautiful music, Saul felt peaceful again. Music can change how we feel! When you’re upset, try singing a Primary song. When you’re scared, hum your favorite hymn. Music is a gift from Heavenly Father!"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["YOU have special talents and gifts too! Maybe you can sing, draw, tell jokes, give hugs, or help others. Whatever your talent is, you can use it to help people like David did! David didn’t just play music for himself — he used it to help King Saul feel better. When you use your gifts to help others, you’re being like Jesus! What’s a talent you have? How can you use it to help someone this week?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jun-14-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What was David’s talent? How did he use it to help Saul?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jun-14-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b6-w3-n1', 6, 'Week 3 · Night 1', 'David and Goliath', '1 Samuel 17', '[{"type": "cover", "img": "images/book/jun-15-0.jpg", "alt": "Cover illustration for “David and Goliath”"}, {"type": "story", "img": "images/book/jun-15-1.jpg", "alt": "Illustration: Israel’s enemies had a HUGE giant soldier named Goliath.", "text": ["Israel’s enemies had a HUGE giant soldier named Goliath. He was over nine feet tall! Every day he yelled, “Send me a fighter!” All of Israel’s soldiers were too scared.", "A young shepherd boy named David came to bring food to his brothers. He heard Goliath shouting mean things. David said, “I’ll fight him! Heavenly Father will help me!”"]}, {"type": "story", "img": "images/book/jun-15-2.jpg", "alt": "Illustration: David didn’t wear heavy armor.", "text": ["David didn’t wear heavy armor. He just had his sling and five smooth stones. He told Goliath, “You have a sword, but I come in the name of the Lord!”", "David swung his sling and a stone flew through the air. THUD! It hit Goliath right on the forehead. The giant fell down! David won because Heavenly Father was with him!"]}, {"type": "moment", "img": "images/book/jun-15-3.jpg", "alt": "Illustration: Stand up tall like a giant — be as big as you can!", "text": ["Stand up tall like a giant — be as big as you can! Now shrink down small like little David. Sometimes problems feel like GIANTS to us! But with Heavenly Father, we can be brave like David. Now pretend to swing a sling and let go! Even small kids can do big things when Heavenly Father helps them. You’re strong with God on your side!"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["YOU might face “giants” in your life too! Maybe a giant fear of the dark, a giant problem at school, or a giant feeling of being scared. But you don’t have to fight your giants alone! Heavenly Father will help you, just like He helped David. You can pray for courage, remember God is with you, and be brave even when you’re small. The battle is the Lord’s — He fights for YOU! What’s a “giant” in your life you can ask God to help you with?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jun-15-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["Why was David brave? Who helped David beat Goliath?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jun-15-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b6-w3-n2', 6, 'Week 3 · Night 2', 'David and Jonathan Are Best Friends', '1 Samuel 18', '[{"type": "cover", "img": "images/book/jun-16-0.jpg", "alt": "Cover illustration for “David and Jonathan Are Best Friends”"}, {"type": "story", "img": "images/book/jun-16-1.jpg", "alt": "Illustration: King Saul’s son Jonathan saw how brave David was.", "text": ["King Saul’s son Jonathan saw how brave David was. They became best friends right away! Jonathan loved David like a brother.", "Jonathan gave David his special royal robe. He gave him his sword and his bow. That was a HUGE gift — Jonathan was the prince!"]}, {"type": "story", "img": "images/book/jun-16-2.jpg", "alt": "Illustration: Even though Jonathan should have been the next king, he didn’t get jealous of David.", "text": ["Even though Jonathan should have been the next king, he didn’t get jealous of David. He helped David and supported him. That’s what real friends do!", "God blessed David in everything he did. He won battles. Everyone loved him. But Jonathan was happy for his friend, not jealous. Real friends are happy when good things happen to each other!"]}, {"type": "moment", "img": "images/book/jun-16-3.jpg", "alt": "Illustration: Stretch your arms out wide for a big hug.", "text": ["Stretch your arms out wide for a big hug. Now give yourself a big squeeze! That’s how Jonathan and David loved each other — like brothers! Now think of your best friend or your sibling. Send them a big invisible hug right now. Real friends share, help each other, and are happy when good things happen to their friend. That’s a treasure!"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["YOU can be a friend like Jonathan! When your sibling or friend does something good, be HAPPY for them, not jealous! When you have something special, SHARE it with people you love. When your friend is sad, HELP them feel better. A true friend is one of God’s greatest gifts! You can be that kind of friend by sharing your toys, being happy when others succeed, helping when someone is hurt, and never being mean. Who is your friend? How can you be a better friend this week?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jun-16-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What did Jonathan give David? How can YOU be a good friend?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jun-16-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b6-w3-n3', 6, 'Week 3 · Night 3', 'Saul Gets Jealous of David', '1 Samuel 18:6–16', '[{"type": "cover", "img": "images/book/jun-17-0.jpg", "alt": "Cover illustration for “Saul Gets Jealous of David”"}, {"type": "story", "img": "images/book/jun-17-1.jpg", "alt": "Illustration: The people loved David!", "text": ["The people loved David! They sang a song: “Saul has won thousands, but David has won TENS of thousands!” Hearing this made King Saul angry.", "Saul felt jealous. He thought, “Why do people love David more than me?” His heart grew bitter. Jealousy can make people do terrible things!"]}, {"type": "story", "img": "images/book/jun-17-2.jpg", "alt": "Illustration: Saul got so jealous, he tried to hurt David.", "text": ["Saul got so jealous, he tried to hurt David. He threw a spear at him! But David ducked away. Twice the spear missed!", "David didn’t fight back. He kept being kind, even when Saul was mean. Jealousy hurts everyone. We must keep it OUT of our hearts!"]}, {"type": "moment", "img": "images/book/jun-17-3.jpg", "alt": "Illustration: Make a big GRUMPY face.", "text": ["Make a big GRUMPY face. Cross your arms. That’s how jealous feels — yucky and grumpy! Now make a HAPPY face and clap for someone else. That feels better, right? When your friend gets something good, choose to be HAPPY for them, not jealous. Push that jealousy feeling away! Smile big and clap! That’s how to keep your heart happy."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Jealousy is when we feel mad because someone else has something good. Maybe your sibling got a new toy and you’re jealous. Maybe your friend got praised and you wanted the praise. Saul let jealousy fill his heart and it made him do terrible things! Don’t let jealousy in YOUR heart! Instead: be HAPPY for others, be grateful for what you have, and remember Heavenly Father loves YOU. When you feel jealous, take a deep breath and say “I’m happy for them!” Have you ever felt jealous?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jun-17-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["Why did Saul get jealous? What can you do when you feel jealous?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jun-17-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b6-w3-n4', 6, 'Week 3 · Night 4', 'David Forgives Saul in the Cave', '1 Samuel 24', '[{"type": "cover", "img": "images/book/jun-18-0.jpg", "alt": "Cover illustration for “David Forgives Saul in the Cave”"}, {"type": "story", "img": "images/book/jun-18-1.jpg", "alt": "Illustration: King Saul was still angry.", "text": ["King Saul was still angry. He chased David with his soldiers! David and his men hid in a big dark cave. Then something amazing happened.", "King Saul came RIGHT into the same cave! He didn’t see David in the dark. David’s men whispered, “Now you can hurt him! He’ll never know!”"]}, {"type": "story", "img": "images/book/jun-18-2.jpg", "alt": "Illustration: But David said, “No!", "text": ["But David said, “No! He is the king. I won’t hurt him.” David quietly snuck up and cut just a tiny piece off Saul’s robe.", "When Saul left the cave, David called out, “King Saul! See? I could have hurt you, but I didn’t!” Saul cried and said, “You are kinder than I am!” David chose kindness over revenge."]}, {"type": "moment", "img": "images/book/jun-18-3.jpg", "alt": "Illustration: Hold out your hands like you’re holding something fragile.", "text": ["Hold out your hands like you’re holding something fragile. That’s what David did — he held back when he could have hurt Saul. Now imagine someone is being mean to you. What’s harder — getting them back, or being kind? Being kind is HARDER! But it’s better. Put your hands on your heart. That’s where kindness lives. Choose kindness, even when it’s hard!"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When someone is mean to you, what should YOU do? It’s so tempting to be mean BACK! But David showed us a better way — be KIND, even to people who aren’t kind to you. When someone hurts your feelings: don’t hit back, don’t say mean things back, pray for them, and be kind anyway. That’s what Jesus teaches us! It’s HARD, but it’s right. When you choose kindness, you’re being like David and like Jesus! Has someone been mean to you? How can you be kind back?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jun-18-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What could David have done to Saul? What did he do instead? Why?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jun-18-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b6-w3-n5', 6, 'Week 3 · Night 5', 'Wise Abigail Stops Trouble', '1 Samuel 25', '[{"type": "cover", "img": "images/book/jun-19-0.jpg", "alt": "Cover illustration for “Wise Abigail Stops Trouble”"}, {"type": "story", "img": "images/book/jun-19-1.jpg", "alt": "Illustration: There was a rich, mean man named Nabal.", "text": ["There was a rich, mean man named Nabal. David and his men had been kind to Nabal’s workers. So David asked Nabal politely for some food.", "But Nabal said meanly, “Who is David? I won’t give him anything!” David got SO angry. He gathered his men to fight Nabal!"]}, {"type": "story", "img": "images/book/jun-19-2.jpg", "alt": "Illustration: Nabal’s wife Abigail was wise and kind.", "text": ["Nabal’s wife Abigail was wise and kind. When she heard, she quickly packed lots of food. She rode out to meet David herself!", "Abigail bowed down and said, “Please forgive my husband. Don’t do something you’ll regret!” David thanked God for sending wise Abigail. Her kind words stopped a big fight!"]}, {"type": "moment", "img": "images/book/jun-19-3.jpg", "alt": "Illustration: Take a deep breath in...", "text": ["Take a deep breath in... and let it out slowly. That’s what we do when we feel angry. Abigail used WISE, KIND words to stop trouble. Now make a peaceful face — eyes soft, lips smiling gently. That’s the face of a peacemaker! When people are angry, soft kind words can fix things faster than mean words."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When people are mad, YOU can be a peacemaker like Abigail! Use kind words. Say “I’m sorry” if you can. Help fix what’s broken. Sometimes a peaceful word stops a big fight! Wise Abigail used her brain AND her heart. You can too! When your sibling is mad, when your friend is upset, when someone is angry — try kind words first. They work like magic! Heavenly Father loves peacemakers. How can you be a peacemaker at home this week?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jun-19-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["How did Abigail stop the fight? Can YOU be a peacemaker?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jun-19-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b6-w3-n6', 6, 'Week 3 · Night 6', 'David Becomes King', '2 Samuel 5', '[{"type": "cover", "img": "images/book/jun-20-0.jpg", "alt": "Cover illustration for “David Becomes King”"}, {"type": "story", "img": "images/book/jun-20-1.jpg", "alt": "Illustration: King Saul finally died in a battle.", "text": ["King Saul finally died in a battle. The Israelites came together. They said to David, “We want YOU to be our king!”", "David was 30 years old when he became king. He ruled for 40 years! He was a king after Heavenly Father’s own heart."]}, {"type": "story", "img": "images/book/jun-20-2.jpg", "alt": "Illustration: David captured the city of Jerusalem.", "text": ["David captured the city of Jerusalem. He made it his special city! It became known as the City of David. It was beautiful and holy.", "David didn’t become king by being mean or pushy. He waited patiently for Heavenly Father’s time. When you’re patient and faithful, blessings come!"]}, {"type": "moment", "img": "images/book/jun-20-3.jpg", "alt": "Illustration: Pretend you’re putting a crown on your head — slowly, carefully.", "text": ["Pretend you’re putting a crown on your head — slowly, carefully. Now sit up straight like a king or queen! David waited a LONG time to become king. He could have grabbed the throne by force, but he didn’t. He waited for Heavenly Father’s perfect time. Patience is a powerful thing! Take a deep breath — being patient feels peaceful."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Sometimes YOU have to wait for good things. Maybe you want a turn on the swing. Maybe you want to grow up bigger. Maybe you want something special. Don’t grab or push or rush! David waited many years to be king. He trusted Heavenly Father’s timing. When you wait patiently and faithfully, Heavenly Father blesses you in the perfect time! What’s something you’re waiting for? Can you be patient like David?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jun-20-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["How old was David when he became king? Why is being patient important?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jun-20-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b6-w3-n7', 6, 'Week 3 · Night 7', 'David Dances Before the Lord', '2 Samuel 6', '[{"type": "cover", "img": "images/book/jun-21-0.jpg", "alt": "Cover illustration for “David Dances Before the Lord”"}, {"type": "story", "img": "images/book/jun-21-1.jpg", "alt": "Illustration: The Ark of the Covenant was Heavenly Father’s special holy box.", "text": ["The Ark of the Covenant was Heavenly Father’s special holy box. David wanted to bring it to Jerusalem! He was SO happy and excited!", "As the Ark came into the city, David couldn’t stop being happy! He danced and danced with all his might! He praised Heavenly Father!"]}, {"type": "story", "img": "images/book/jun-21-2.jpg", "alt": "Illustration: David’s wife saw him dancing.", "text": ["David’s wife saw him dancing. She thought he looked silly for a king. She said, “Why are you dancing like that?” But David said, “I’m dancing for the Lord!”", "David didn’t care what others thought. He just wanted to show Heavenly Father how much he loved Him! When we love God, we can be joyful and praise Him too!"]}, {"type": "moment", "img": "images/book/jun-21-3.jpg", "alt": "Illustration: Stand up and DANCE!", "text": ["Stand up and DANCE! Wiggle, spin, jump, clap! Do a silly happy dance! That’s how David danced for Heavenly Father! He didn’t care if he looked silly — he just wanted to praise God! Now sing “I Am a Child of God” or hum your favorite Primary song. When we praise Heavenly Father with our whole hearts, it makes Him smile!"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["How do YOU show Heavenly Father you love Him? You don’t have to dance like David (but you can!). You can sing songs to Him, say “I love you, Heavenly Father” in your prayers, smile when you think of Him, be happy in church, and share your joy with others! Don’t be shy about loving God! David didn’t care if people thought he looked silly — he just praised God. Will you praise Heavenly Father with joy this week? How?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jun-21-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["Why was David dancing? How can YOU show Heavenly Father you love Him?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jun-21-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b6-w4-n1', 6, 'Week 4 · Night 1', 'David Makes a Big Mistake', '2 Samuel 11', '[{"type": "cover", "img": "images/book/jun-22-0.jpg", "alt": "Cover illustration for “David Makes a Big Mistake”"}, {"type": "story", "img": "images/book/jun-22-1.jpg", "alt": "Illustration: King David was a good king who loved Heavenly Father.", "text": ["King David was a good king who loved Heavenly Father. But one day, he made a very big mistake. He saw something that wasn’t his and wanted it.", "Instead of looking away, David kept thinking about it. He made bad choice after bad choice. He even did something that hurt other people very badly."]}, {"type": "story", "img": "images/book/jun-22-2.jpg", "alt": "Illustration: David tried to hide what he did.", "text": ["David tried to hide what he did. He thought no one would know. But Heavenly Father sees everything we do, even when no one else is watching!", "David made very bad choices. But this story isn’t over yet. Tomorrow we’ll learn what David did to make things right with Heavenly Father."]}, {"type": "moment", "img": "images/book/jun-22-3.jpg", "alt": "Illustration: Put your hands over your eyes like you’re hiding.", "text": ["Put your hands over your eyes like you’re hiding. Can you still see Heavenly Father? Can He still see you? Yes! Heavenly Father can ALWAYS see us, even when we hide. David tried to hide his bad choices, but Heavenly Father knew. Take your hands off your eyes. Heavenly Father loves you whether you’re being good or making mistakes — but He wants you to make GOOD choices."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Sometimes we want things that aren’t ours, or we want to do things we shouldn’t. When that happens, we need to look away and choose good! David didn’t look away from his bad thoughts, and one bad choice led to another. YOU can stop bad choices early by looking away from things that aren’t good, telling Mommy or Daddy when you’re tempted, praying for help, and remembering Heavenly Father is watching. What’s something you can do when bad thoughts come into your head?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jun-22-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["Did David make good choices or bad choices? Can Heavenly Father see everything we do?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jun-22-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b6-w4-n2', 6, 'Week 4 · Night 2', 'David Says Sorry', '2 Samuel 12', '[{"type": "cover", "img": "images/book/jun-23-0.jpg", "alt": "Cover illustration for “David Says Sorry”"}, {"type": "story", "img": "images/book/jun-23-1.jpg", "alt": "Illustration: Heavenly Father sent the prophet Nathan to talk to King David.", "text": ["Heavenly Father sent the prophet Nathan to talk to King David. Nathan told David a sad story about a rich man who took a poor man’s only sheep.", "David got SO angry! He said, “That rich man should be punished!” Then Nathan looked at David and said, “YOU are that man! You took what wasn’t yours.”"]}, {"type": "story", "img": "images/book/jun-23-2.jpg", "alt": "Illustration: David’s heart broke.", "text": ["David’s heart broke. He realized what he had done was very wrong. He cried and said, “I have sinned against Heavenly Father!” He was truly, deeply sorry.", "David repented. That means he said sorry, asked for forgiveness, and tried hard not to do it again. Heavenly Father loves us when we repent — He always wants us back!"]}, {"type": "moment", "img": "images/book/jun-23-3.jpg", "alt": "Illustration: Put your hands together and bow your head.", "text": ["Put your hands together and bow your head. Imagine telling Heavenly Father, “I’m sorry.” Real sorry comes from your heart, not just your mouth. David felt SO sad about his bad choices that he cried real tears. When you do something wrong, you might feel that sad feeling too. That’s good! It means your heart knows the difference between right and wrong. Now lift your head — when we say sorry, Heavenly Father forgives us!"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Everyone makes mistakes — even kings, even moms and dads, even YOU! When you do something wrong, what should you do? REPENT! That means: 1) Say “I’m sorry” to Heavenly Father, 2) Say “I’m sorry” to anyone you hurt, 3) Try to fix what you broke if you can, and 4) Try not to do it again. When you repent, Heavenly Father forgives you! He doesn’t stay mad — He’s so happy when we come back to Him. Is there anything you need to say sorry for?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jun-23-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What did David do when he realized he was wrong? What does it mean to repent?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jun-23-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b6-w4-n3', 6, 'Week 4 · Night 3', 'Solomon Asks for Wisdom', '1 Kings 3:1–15', '[{"type": "cover", "img": "images/book/jun-24-0.jpg", "alt": "Cover illustration for “Solomon Asks for Wisdom”"}, {"type": "story", "img": "images/book/jun-24-1.jpg", "alt": "Illustration: After David, his son Solomon became king.", "text": ["After David, his son Solomon became king. Solomon was young. He wanted to be a good king like his father had been.", "One night, Solomon had a dream. Heavenly Father said, “Solomon, ask Me for anything! What do you want?” Solomon could have asked for anything!"]}, {"type": "story", "img": "images/book/jun-24-2.jpg", "alt": "Illustration: Solomon didn’t ask for money.", "text": ["Solomon didn’t ask for money. He didn’t ask for power. He didn’t ask to live a long time. Instead, he said, “Please give me wisdom to lead Your people well.”", "Heavenly Father was SO pleased! He said, “Because you asked for wisdom and not selfish things, I’ll give you wisdom AND riches AND honor!” Solomon became the wisest king ever!"]}, {"type": "moment", "img": "images/book/jun-24-3.jpg", "alt": "Illustration: Pretend a wish-granting genie just said you can have ANYTHING.", "text": ["Pretend a wish-granting genie just said you can have ANYTHING. What would you ask for? Maybe candy? A toy? A pony? Solomon could have asked for anything too — but he asked for WISDOM, the ability to make good choices! Tap your forehead three times. That’s your brain — wisdom helps your brain make good choices. When we ask Heavenly Father for things that help us be better, He’s so happy with us!"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When YOU pray, what do you ask for? It’s okay to ask for help with your hopes and dreams. But the BEST things to pray for are things like Solomon asked for: wisdom, kindness, courage, patience, faith, and love. Heavenly Father loves it when we ask to be BETTER, not just to GET more stuff. The next time you pray, try asking Heavenly Father to help you be wise, kind, or brave! What’s something good (not a thing or toy) you could ask Heavenly Father for?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jun-01-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What did Solomon ask Heavenly Father for? Why did this please God so much?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jun-24-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b6-w4-n4', 6, 'Week 4 · Night 4', 'Two Mothers and One Baby', '1 Kings 3:16–28', '[{"type": "cover", "img": "images/book/jun-25-0.jpg", "alt": "Cover illustration for “Two Mothers and One Baby”"}, {"type": "story", "img": "images/book/jun-25-1.jpg", "alt": "Illustration: Two mothers came to King Solomon.", "text": ["Two mothers came to King Solomon. They were arguing about a baby! Both of them said, “This baby is MINE!” They needed Solomon to help them.", "Solomon thought carefully. Then he said something shocking: “Bring me a sword! I’ll cut the baby in half — half for each mother.”"]}, {"type": "story", "img": "images/book/jun-25-2.jpg", "alt": "Illustration: The REAL mother cried out, “NO!", "text": ["The REAL mother cried out, “NO! Don’t hurt the baby! Give him to her — just don’t hurt him!” The other woman said, “Yes, cut him in half!”", "Solomon smiled. He knew the real mother right away! A real mother would rather lose her baby than see him hurt. Solomon gave the baby back to his real mommy. Everyone saw how WISE Solomon was!"]}, {"type": "moment", "img": "images/book/jun-25-3.jpg", "alt": "Illustration: Hold an imaginary baby in your arms — gently, gently, like it’s the most precious thing!", "text": ["Hold an imaginary baby in your arms — gently, gently, like it’s the most precious thing! That’s how a real mommy holds her baby. The real mother loved her baby SO much that she’d give him up rather than see him hurt. That’s REAL love. Now think of the people you love most — your mommy, daddy, brothers and sisters. How much do you love them? Real love means wanting what’s best for them, even if it’s hard for you."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Solomon used the wisdom Heavenly Father gave him to find the truth. YOU can ask for wisdom too! When you have a hard problem to solve — like figuring out who took your toy, or what’s the right thing to do — pray to Heavenly Father. He gives wisdom to those who ask! Also, real love means wanting what’s best for someone, even when it’s hard. The real mother loved her baby more than herself. Can you love your sibling or friend like that — wanting what’s best for them?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jun-25-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["How did Solomon know which mother was the real mother? What does real love look like?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jun-25-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b6-w4-n5', 6, 'Week 4 · Night 5', 'Building the Temple', '1 Kings 6', '[{"type": "cover", "img": "images/book/jun-26-0.jpg", "alt": "Cover illustration for “Building the Temple”"}, {"type": "story", "img": "images/book/jun-26-1.jpg", "alt": "Illustration: King Solomon wanted to build a beautiful temple for Heavenly Father.", "text": ["King Solomon wanted to build a beautiful temple for Heavenly Father. He gathered the BEST materials — strong cedar wood, smooth stones, and shining gold!", "Thousands of workers helped. They cut the stones perfectly far away. When they put the stones together at the temple, no one heard a hammer or chisel! It was so quiet and holy."]}, {"type": "story", "img": "images/book/jun-26-2.jpg", "alt": "Illustration: The temple took SEVEN whole years to build!", "text": ["The temple took SEVEN whole years to build! Inside, everything was covered in gold. There were carvings of angels and flowers everywhere. It was the most beautiful place ever!", "The temple was a special place where people could feel close to Heavenly Father. Solomon wanted to give Heavenly Father his very best. We can give Heavenly Father our best too!"]}, {"type": "moment", "img": "images/book/jun-26-3.jpg", "alt": "Illustration: Pretend you’re holding the most precious, most beautiful thing in the world.", "text": ["Pretend you’re holding the most precious, most beautiful thing in the world. Hold it gently. Look at it carefully. That’s how Solomon felt about the temple! He wanted EVERYTHING to be perfect for Heavenly Father. Now think about how special temples still are today. We have temples in our church! They’re beautiful places where families can be together forever. When you grow up, you can go to the temple too!"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Solomon gave Heavenly Father his BEST work, his BEST materials, his BEST effort. YOU can give Heavenly Father your best too! How? You can do your best at school, give your best at chores, sing your best in Primary, behave your best in church, and pray your best prayers. Don’t just do “good enough” — try your very BEST for Heavenly Father! And someday, you can go to the temple — a special place even better than Solomon’s. What’s something you can do your best at this week?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jun-26-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What was the temple like? Why did Solomon want it to be so beautiful?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jun-26-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b6-w4-n6', 6, 'Week 4 · Night 6', 'Solomon’s Prayer at the Temple', '1 Kings 8', '[{"type": "cover", "img": "images/book/jun-27-0.jpg", "alt": "Cover illustration for “Solomon’s Prayer at the Temple”"}, {"type": "story", "img": "images/book/jun-27-1.jpg", "alt": "Illustration: When the temple was finished, Solomon gathered ALL of Israel together.", "text": ["When the temple was finished, Solomon gathered ALL of Israel together. He stood in front of the new temple. It was time to dedicate it to Heavenly Father!", "Solomon knelt down. He spread out his hands toward heaven. He prayed a beautiful prayer: “Heavenly Father, when Your people pray here, please HEAR them!”"]}, {"type": "story", "img": "images/book/jun-27-2.jpg", "alt": "Illustration: Solomon prayed for everyone — for the people of Israel, for strangers visiting from far away, even for people…", "text": ["Solomon prayed for everyone — for the people of Israel, for strangers visiting from far away, even for people who would pray years later. He asked God to hear ALL their prayers!", "When Solomon finished praying, a bright cloud filled the temple! Everyone knew Heavenly Father had heard the prayer. He was there!"]}, {"type": "moment", "img": "images/book/jun-27-3.jpg", "alt": "Illustration: Get on your knees right where you are.", "text": ["Get on your knees right where you are. Now spread out your arms toward the sky like Solomon did. Doesn’t that feel like you’re reaching up to Heavenly Father? When you pray like this — humble, with your heart open — Heavenly Father hears you. Solomon prayed not just for himself, but for everyone! You can pray for other people too. Who do you want to pray for tonight?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When YOU pray, Heavenly Father HEARS you! Just like Solomon prayed and the cloud came, your prayers are heard by God. You don’t have to be in a temple to pray. You can pray in your bedroom, in the car, at school, when you’re scared, when you’re happy — anywhere! And like Solomon, you can pray for OTHER people too: your family, your friends, people who are sick, people who are sad. Praying for others is one of the best things you can do! Who can you pray for today?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jun-27-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What did Solomon ask Heavenly Father to do? Does Heavenly Father hear OUR prayers?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jun-27-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b6-w4-n7', 6, 'Week 4 · Night 7', 'Keep Your Heart Close to God', '1 Kings 9', '[{"type": "cover", "img": "images/book/jun-28-0.jpg", "alt": "Cover illustration for “Keep Your Heart Close to God”"}, {"type": "story", "img": "images/book/jun-28-1.jpg", "alt": "Illustration: After the beautiful temple was built, Heavenly Father appeared to Solomon again.", "text": ["After the beautiful temple was built, Heavenly Father appeared to Solomon again. He had something very important to tell him.", "Heavenly Father said, “Solomon, if you keep My commandments and follow Me, you and your family will be blessed forever! But if you turn away and worship other gods, things will go badly.”"]}, {"type": "story", "img": "images/book/jun-28-2.jpg", "alt": "Illustration: This was a big promise — and a big warning!", "text": ["This was a big promise — and a big warning! Heavenly Father wanted Solomon to keep his heart close to Him. Even kings need to obey God!", "Sadly, when Solomon got older, he didn’t always follow Heavenly Father. He started worshiping other gods. We must always keep our hearts close to Heavenly Father — every day, our whole life!"]}, {"type": "moment", "img": "images/book/jun-28-3.jpg", "alt": "Illustration: Put both hands over your heart.", "text": ["Put both hands over your heart. Feel it beating? That’s the heart Heavenly Father wants! He wants your WHOLE heart, all the time. Now imagine pulling something little out of your heart — that’s what happens when we let little bad things in. Solomon did that, little by little, until his heart was far from God. Push your hands back to your heart and squeeze tight. Keep your heart close to Heavenly Father always!"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["It’s not enough to love Heavenly Father just once. We have to choose Him EVERY day, our WHOLE life! Solomon was wise and built a beautiful temple, but later he stopped following God. Don’t be like older Solomon — be faithful your WHOLE life! You can keep your heart close to Heavenly Father by praying every day, going to church, reading scriptures, choosing the right, and remembering Him always. Even when you grow up, keep loving Heavenly Father! Will you promise to keep your heart close to God forever?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jun-28-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What did Heavenly Father warn Solomon about? How can we keep our hearts close t o God?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jun-28-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

-- ---------------------------------------------------------------------
--  There Is a Prophet in Israel
-- ---------------------------------------------------------------------
insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w1-n1', 7, 'Week 1 · Night 1', 'Two Kings, One Choice', '1 Kings 12', '[{"type": "cover", "img": "images/book/jul-01-0.jpg", "alt": "Cover illustration for “Two Kings, One Choice”"}, {"type": "story", "img": "images/book/jul-01-1.jpg", "alt": "Illustration: Long ago, wise King Solomon died.", "text": ["Long ago, wise King Solomon died. His son Rehoboam became the new king. The people came to him and said, “Please be kind and gentle to us.” Rehoboam said, “Give me three days to think.”", "First he asked the old, wise men what to do. They said, “Be kind, and the people will love you forever.” But then he asked his young friends. They told him, “Be tough and bossy!”"]}, {"type": "story", "img": "images/book/jul-01-2.jpg", "alt": "Illustration: Rehoboam listened to his friends instead of the wise men.", "text": ["Rehoboam listened to his friends instead of the wise men. He spoke harsh, unkind words to the people. This made everyone sad and upset. The kingdom split into two pieces.", "Heavenly Father gives us wise people to guide us — parents, prophets, and teachers. When we listen to them, our hearts stay happy and safe. When we ignore good counsel, things can fall apart. Wise listening keeps families together."]}, {"type": "moment", "img": "images/book/jul-01-3.jpg", "alt": "Illustration: Cup your hands behind your ears like big bunny ears.", "text": ["Cup your hands behind your ears like big bunny ears. Now listen very carefully — can you hear quiet sounds in the room? That is good listening! Rehoboam forgot to listen to the wise men, and it made everything hard. Let’s practice listening to the people who love us."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["YOU can be a good listener! When mom or dad asks you to do something, listen the first time. When your teacher gives you a rule, follow it. Wise people want to keep you safe and happy. Who is someone wise you can listen to this week?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-01-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["Who did Rehoboam listen to? What happened to the kingdom when he didn’t listen to the wise men?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-01-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w1-n2', 7, 'Week 1 · Night 2', 'The Ravens Feed Elijah', '1 Kings 17', '[{"type": "cover", "img": "images/book/jul-02-0.jpg", "alt": "Cover illustration for “The Ravens Feed Elijah”"}, {"type": "story", "img": "images/book/jul-02-1.jpg", "alt": "Illustration: Elijah was a prophet who loved Heavenly Father.", "text": ["Elijah was a prophet who loved Heavenly Father. He told the wicked king there would be no rain for a long time. Then Heavenly Father said, “Go hide by the little brook. I will take care of you.”", "Elijah went and stayed by the brook. He drank the cool, clear water. But where would he get food? There were no stores out there."]}, {"type": "story", "img": "images/book/jul-02-2.jpg", "alt": "Illustration: Then something amazing happened!", "text": ["Then something amazing happened! Big black birds called ravens flew to Elijah. They carried bread and meat in their beaks. They brought him food every morning and every night.", "Heavenly Father took care of Elijah in a surprising way. He uses all sorts of helpers — even birds! When we trust Him, He always finds a way to take care of us. Heavenly Father never forgets His children."]}, {"type": "moment", "img": "images/book/jul-02-3.jpg", "alt": "Illustration: Flap your arms like a bird carrying food.", "text": ["Flap your arms like a bird carrying food. Now “fly” your hands over and drop pretend bread into someone’s lap. That’s what the ravens did for Elijah! Heavenly Father sent them so Elijah would not be hungry. Think about all the ways He takes care of YOU."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Heavenly Father takes care of you every single day! He gives you food, a home, and people who love you. Sometimes His help comes in surprising ways. When you wonder if He sees you, remember the ravens. What is one way Heavenly Father took care of you today?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-02-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["Who brought Elijah food? Who sent the ravens to help him?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-02-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w1-n3', 7, 'Week 1 · Night 3', 'The Jar That Never Ran Out', '1 Kings 17', '[{"type": "cover", "img": "images/book/jul-03-0.jpg", "alt": "Cover illustration for “The Jar That Never Ran Out”"}, {"type": "story", "img": "images/book/jul-03-1.jpg", "alt": "Illustration: Heavenly Father sent Elijah to a poor widow in another town.", "text": ["Heavenly Father sent Elijah to a poor widow in another town. She had a little boy and almost no food left. She had just a tiny bit of flour and a tiny bit of oil. She thought it was their very last meal.", "Elijah said, “Please make me a little bread first. Don’t be afraid.” The woman was kind. She shared her last food with the prophet, even though she was scared."]}, {"type": "story", "img": "images/book/jul-03-2.jpg", "alt": "Illustration: Then a miracle happened!", "text": ["Then a miracle happened! Her jar of flour never got empty. Her oil never ran out. Every day there was enough food for the widow, her son, and Elijah.", "Because the woman trusted God and shared, He blessed her with plenty. When we give even when it’s hard, Heavenly Father takes care of us. Sharing opens the door for blessings. God can make a little become a lot."]}, {"type": "moment", "img": "images/book/jul-03-3.jpg", "alt": "Illustration: Pretend to pour from a jar — tip your hand and say “glug, glug, glug.” Now pour again…", "text": ["Pretend to pour from a jar — tip your hand and say “glug, glug, glug.” Now pour again… and again… it never runs out! That’s the miracle Heavenly Father gave the widow. He turned her little bit into more than enough."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When you share, Heavenly Father is so pleased! Sharing your snack, your toys, or your turn can feel hard. But God blesses people who give with a happy heart. What is something you can share this week, even if it feels hard?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-03-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What did the widow share with Elijah? What happened to her flour and oil?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-03-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w1-n4', 7, 'Week 1 · Night 4', 'Elijah Prays for the Little Boy', '1 Kings 17', '[{"type": "cover", "img": "images/book/jul-04-0.jpg", "alt": "Cover illustration for “Elijah Prays for the Little Boy”"}, {"type": "story", "img": "images/book/jul-04-1.jpg", "alt": "Illustration: The widow’s little boy got very, very sick.", "text": ["The widow’s little boy got very, very sick. He got so sick that he stopped breathing. His mother was heartbroken and cried. She did not know what to do.", "Elijah said, “Give me your son.” He carried the boy upstairs and laid him down. Then Elijah prayed to Heavenly Father with all his heart. “Please, Lord, let this child live again.”"]}, {"type": "story", "img": "images/book/jul-04-2.jpg", "alt": "Illustration: Heavenly Father heard Elijah’s prayer.", "text": ["Heavenly Father heard Elijah’s prayer. The little boy started breathing again! Elijah carried him back down to his mother. “See,” he said, “your son is alive!”", "The mother knew for sure that Elijah was God’s prophet. Prayer is powerful because Heavenly Father is listening. He hears every prayer we say. Nothing is too hard for Him."]}, {"type": "moment", "img": "images/book/jul-04-3.jpg", "alt": "Illustration: Fold your arms and bow your head like Elijah praying.", "text": ["Fold your arms and bow your head like Elijah praying. Whisper, “Please help, Heavenly Father.” Feel how quiet and peaceful that is. Heavenly Father heard Elijah, and He hears you too."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When something feels too big or too scary, YOU can pray! Heavenly Father loves to hear from you. He listened to Elijah, and He listens to little children just the same. What is something you can pray about tonight?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-04-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What did Elijah do when the boy was sick? Did Heavenly Father hear his prayer?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-04-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w1-n5', 7, 'Week 1 · Night 5', 'Fire from Heaven', '1 Kings 18', '[{"type": "cover", "img": "images/book/jul-05-0.jpg", "alt": "Cover illustration for “Fire from Heaven”"}, {"type": "story", "img": "images/book/jul-05-1.jpg", "alt": "Illustration: Many people had forgotten Heavenly Father.", "text": ["Many people had forgotten Heavenly Father. They worshiped a pretend god named Baal. Elijah said, “Let’s find out who the real God is!” He gathered everyone on top of a mountain.", "The prophets of Baal called and called to their pretend god all day. But nothing happened — no answer at all. Baal was not real, so he could not hear them."]}, {"type": "story", "img": "images/book/jul-05-2.jpg", "alt": "Illustration: Then Elijah built an altar and prayed to the true God.", "text": ["Then Elijah built an altar and prayed to the true God. He even poured water all over it! Suddenly, FIRE came down from heaven and burned it all up — the water, the wood, even the stones!", "Everyone fell down and said, “The Lord, He is the real God!” There is only one true God — our Heavenly Father. He is real, He is powerful, and He hears us. We follow Him because He is true."]}, {"type": "moment", "img": "images/book/jul-05-3.jpg", "alt": "Illustration: Wiggle your fingers up high like flickering flames, then bring them whooshing down — that’s the fire from heav…", "text": ["Wiggle your fingers up high like flickering flames, then bring them whooshing down — that’s the fire from heaven! Heavenly Father showed everyone He was real. Make your hands strong and say, “The Lord, He is God!”"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["There is only ONE true God — your Heavenly Father! He is more real and more powerful than anything pretend. We don’t follow toys, or money, or anything else more than Him. We choose Him first. How can you show Heavenly Father that you choose Him?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-05-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What came down from heaven for Elijah? Who is the one true God?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-05-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w1-n6', 7, 'Week 1 · Night 6', 'The Still, Small Voice', '1 Kings 19', '[{"type": "cover", "img": "images/book/jul-06-0.jpg", "alt": "Cover illustration for “The Still, Small Voice”"}, {"type": "story", "img": "images/book/jul-06-1.jpg", "alt": "Illustration: Elijah was tired and scared and ran far away.", "text": ["Elijah was tired and scared and ran far away. He sat down all alone and felt very sad. Heavenly Father sent an angel to bring him food and rest. Then God told Elijah to wait on the mountain.", "First came a big, loud WIND that broke the rocks. But God was not in the wind. Then came a shaking EARTHQUAKE. But God was not in the earthquake."]}, {"type": "story", "img": "images/book/jul-06-2.jpg", "alt": "Illustration: Then came a hot, crackling FIRE.", "text": ["Then came a hot, crackling FIRE. But God was not in the fire either. After all the loud noise came a tiny, gentle whisper. And THAT is where Elijah felt God.", "Heavenly Father often speaks in a quiet, peaceful way. It’s a soft feeling inside, called the Holy Ghost. To hear Him, we have to be calm and still. His gentle voice guides us to what is right."]}, {"type": "moment", "img": "images/book/jul-06-3.jpg", "alt": "Illustration: Make a big loud “WHOOOSH” wind sound, then stomp like an earthquake, then “crackle” like fire.", "text": ["Make a big loud “WHOOOSH” wind sound, then stomp like an earthquake, then “crackle” like fire. Now… get very, very still and quiet. Shhh. That stillness is where Elijah felt God. Can you feel how peaceful quiet can be?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Heavenly Father usually speaks in a quiet, gentle way — through the Holy Ghost. It’s a warm, peaceful feeling in your heart. To hear Him, you have to be calm and listen. When have you felt that quiet, good feeling inside?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-06-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["Was God in the loud wind, earthquake, or fire? Where did Elijah finally feel God?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-06-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w1-n7', 7, 'Week 1 · Night 7', 'Micaiah Tells the Truth', '1 Kings 22', '[{"type": "cover", "img": "images/book/jul-07-0.jpg", "alt": "Cover illustration for “Micaiah Tells the Truth”"}, {"type": "story", "img": "images/book/jul-07-1.jpg", "alt": "Illustration: King Ahab wanted to go to a big battle.", "text": ["King Ahab wanted to go to a big battle. He gathered lots of prophets who only said what he wanted to hear. “You’ll win! You’ll win!” they cheered. But that wasn’t really true.", "There was one true prophet named Micaiah. The king didn’t like him because Micaiah always told the truth. The messenger said, “Just say something nice like everyone else.” But Micaiah said, “I will only say what God tells me.”"]}, {"type": "story", "img": "images/book/jul-07-2.jpg", "alt": "Illustration: Micaiah bravely told the truth: “If you go to battle, it will not go well.” The king got angry and put Micaiah…", "text": ["Micaiah bravely told the truth: “If you go to battle, it will not go well.” The king got angry and put Micaiah away. But Micaiah was right — he had told the truth.", "Telling the truth can be hard, especially when others want you to fib. But Heavenly Father wants us to be honest, even when it’s scary. Brave, truthful people please the Lord. Truth is always the right choice."]}, {"type": "moment", "img": "images/book/jul-07-3.jpg", "alt": "Illustration: Stand up tall and strong like brave Micaiah.", "text": ["Stand up tall and strong like brave Micaiah. Put your hand on your heart and say, “I will tell the truth!” It takes courage to be honest when others want you to fib. Feel how good and clean it feels to tell the truth."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Always tell the truth, even when it’s hard! Sometimes people want you to fib, or you might be scared of getting in trouble. But Heavenly Father is so happy when you are honest. When is a time it might be hard to tell the truth — and you can choose to be honest anyway?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-07-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["Did Micaiah say what the king wanted, or did he tell the truth? Was telling the truth easy or hard?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-07-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w2-n1', 7, 'Week 2 · Night 1', 'Elijah Goes Up to Heaven', '2 Kings 2', '[{"type": "cover", "img": "images/book/jul-08-0.jpg", "alt": "Cover illustration for “Elijah Goes Up to Heaven”"}, {"type": "story", "img": "images/book/jul-08-1.jpg", "alt": "Illustration: Elijah the prophet was very old.", "text": ["Elijah the prophet was very old. His helper Elisha loved him and stayed close by his side. Elisha would not leave Elijah, no matter what. They walked together as good friends.", "They came to a river. Elijah rolled up his coat and hit the water. The river split apart so they could walk across on dry ground! Heavenly Father gave Elijah great power."]}, {"type": "story", "img": "images/book/jul-08-2.jpg", "alt": "Illustration: Suddenly a chariot of fire and horses of fire came down!", "text": ["Suddenly a chariot of fire and horses of fire came down! Elijah went up, up, up to heaven in a whirlwind. Elisha watched in wonder. Then Elijah’s coat floated down to him.", "Now Elisha became the new prophet. He picked up the coat and trusted God just like Elijah did. Heavenly Father always has a living prophet to lead His people. When one prophet finishes, another is ready to help us."]}, {"type": "moment", "img": "images/book/jul-08-3.jpg", "alt": "Illustration: Whirl your arms around like a spinning whirlwind going up to the sky — wheee!", "text": ["Whirl your arms around like a spinning whirlwind going up to the sky — wheee! That’s how Elijah went to heaven. Then pretend to pick up his special coat, like Elisha did. Now YOU can be a helper who follows God’s prophet."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Heavenly Father always gives us a living prophet to lead us! Today we have a prophet too. He helps us know what God wants. When we follow the prophet, we follow Heavenly Father. Do you know the name of our prophet today?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-08-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["How did Elijah go up to heaven? Who became the new prophet after him?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-08-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w2-n2', 7, 'Week 2 · Night 2', 'The Widow’s Oil', '2 Kings 4', '[{"type": "cover", "img": "images/book/jul-09-0.jpg", "alt": "Cover illustration for “The Widow’s Oil”"}, {"type": "story", "img": "images/book/jul-09-1.jpg", "alt": "Illustration: A kind woman was very sad.", "text": ["A kind woman was very sad. Her husband had died, and she owed money she could not pay. All she had left was one little pot of oil. She came to the prophet Elisha for help.", "Elisha said, “Go borrow lots of empty jars from your neighbors. Get as many as you can!” So she and her sons gathered jars and jars and jars. Then they shut the door."]}, {"type": "story", "img": "images/book/jul-09-2.jpg", "alt": "Illustration: She started pouring her little bit of oil.", "text": ["She started pouring her little bit of oil. But it kept pouring and pouring! It filled every single jar, right to the top. The oil only stopped when there were no more jars left.", "Elisha said, “Now sell the oil and pay what you owe.” Heavenly Father gave her more than enough. When we trust God and obey His prophet, He provides. He cares about our family’s needs."]}, {"type": "moment", "img": "images/book/jul-09-3.jpg", "alt": "Illustration: Pretend you’re holding a jar and pouring oil — tip your hand and watch it fill up…", "text": ["Pretend you’re holding a jar and pouring oil — tip your hand and watch it fill up… and another… and another! It just keeps coming! That’s the miracle God gave the widow. He took her little bit and made it more than enough.", "Sweet Boys & Girls"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When you obey, Heavenly Father can do amazing things! The widow listened to the prophet and got a miracle. God knows what your family needs. He can make your “little bit” into plenty. What is something you can obey cheerfully this week?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-09-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What did the widow have at the start? What happened when she poured her oil?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-09-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w2-n3', 7, 'Week 2 · Night 3', 'A Special Room for the Prophet', '2 Kings 4', '[{"type": "cover", "img": "images/book/jul-10-0.jpg", "alt": "Cover illustration for “A Special Room for the Prophet”"}, {"type": "story", "img": "images/book/jul-10-1.jpg", "alt": "Illustration: There was a kind woman who loved Heavenly Father.", "text": ["There was a kind woman who loved Heavenly Father. Whenever Elisha walked by, she gave him food. She told her husband, “Let’s make a little room for the prophet.” So they built him a cozy room with a bed, a table, a chair, and a lamp.", "Elisha was so thankful for her kindness. He wanted to do something nice for her too. He asked, “What can I do for you?” The woman had always wished for a baby."]}, {"type": "story", "img": "images/book/jul-10-2.jpg", "alt": "Illustration: Elisha said, “Next year you will hold a baby boy in your arms.” The woman could hardly believe it!", "text": ["Elisha said, “Next year you will hold a baby boy in your arms.” The woman could hardly believe it! And it came true — she had a sweet baby son. Heavenly Father blessed her kindness.", "When we are kind and make room for others, Heavenly Father notices. He blesses people who serve quietly and lovingly. Kindness is never wasted. God remembers every good thing we do."]}, {"type": "moment", "img": "images/book/jul-10-3.jpg", "alt": "Illustration: Pretend to fluff a pillow and pat a cozy bed — you’re making a nice room for someone special!", "text": ["Pretend to fluff a pillow and pat a cozy bed — you’re making a nice room for someone special! That’s what the kind woman did for the prophet. Now give a warm, welcoming wave like you’re saying, “Come in, you’re welcome here!”"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Being kind and welcoming makes Heavenly Father happy! You can make room for others — share your space, your snack, or a smile. The kind woman served the prophet, and God blessed her. Who can you be kind and welcoming to this week?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-10-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What did the kind woman build for the prophet? How did Heavenly Father bless her?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-10-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w2-n4', 7, 'Week 2 · Night 4', 'Naaman Washes Seven Times', '2 Kings 5', '[{"type": "cover", "img": "images/book/jul-11-0.jpg", "alt": "Cover illustration for “Naaman Washes Seven Times”"}, {"type": "story", "img": "images/book/jul-11-1.jpg", "alt": "Illustration: Naaman was a strong, important soldier.", "text": ["Naaman was a strong, important soldier. But he was very sick with sores all over his skin. A little servant girl said, “There’s a prophet who can help you!” So Naaman traveled to find Elisha.", "Elisha sent a simple message: “Go wash in the river seven times.” Naaman was upset! “That’s too easy. Why didn’t he do something fancy?” He almost went home still sick."]}, {"type": "story", "img": "images/book/jul-11-2.jpg", "alt": "Illustration: But his servants said kindly, “Just try it!” So Naaman dipped in the river — one, two, three, four, five, six…", "text": ["But his servants said kindly, “Just try it!” So Naaman dipped in the river — one, two, three, four, five, six, seven times. When he came up, his skin was all better! He was completely healed.", "Sometimes Heavenly Father asks us to do simple things. They might seem too easy, but obeying brings big blessings. Naaman learned to be humble and obey. Doing the small things God asks really matters."]}, {"type": "moment", "img": "images/book/jul-11-3.jpg", "alt": "Illustration: Let’s count and dip together!", "text": ["Let’s count and dip together! Pretend to dip down in the water seven times — “one, two, three, four, five, six, seven!” Now pop up clean and healthy like Naaman! Doing the simple thing God asked made all the difference."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Do the simple things Heavenly Father asks, even if they seem small! Saying prayers, being kind, listening, and obeying might feel plain. But those little things bring big blessings. What simple, good thing can you do today?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-11-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What did Elisha tell Naaman to do? Was Naaman healed when he finally obeyed?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-11-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w2-n5', 7, 'Week 2 · Night 5', 'The Floating Axe Head', '2 Kings 6', '[{"type": "cover", "img": "images/book/jul-12-0.jpg", "alt": "Cover illustration for “The Floating Axe Head”"}, {"type": "story", "img": "images/book/jul-12-1.jpg", "alt": "Illustration: Elisha and his helpers were chopping wood by the river.", "text": ["Elisha and his helpers were chopping wood by the river. They were building a new place to live and work. One man was swinging hard with a borrowed axe. Suddenly — splash! — the metal axe head flew off into the deep water.", "The man felt terrible. “Oh no! That axe wasn’t even mine — I borrowed it!” He was worried because he could not pay for it. He didn’t know what to do."]}, {"type": "story", "img": "images/book/jul-12-2.jpg", "alt": "Illustration: Elisha asked, “Where did it fall?” The man showed him the spot.", "text": ["Elisha asked, “Where did it fall?” The man showed him the spot. Elisha cut a stick and threw it in the water. Then the heavy iron axe head floated right up to the top!", "Heavenly Father cares about big things AND little things. He helped with a lost axe head because His prophet asked. No worry is too small for God. He loves us and helps with everything."]}, {"type": "moment", "img": "images/book/jul-12-3.jpg", "alt": "Illustration: Pretend to swing an axe — chop, chop, chop — then “whoops!” let it splash into the water.", "text": ["Pretend to swing an axe — chop, chop, chop — then “whoops!” let it splash into the water. Now use your finger to make the axe head float up, up to the top! Heavenly Father cared about that little lost axe. He cares about your little worries too."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["No problem is too small for Heavenly Father! Maybe you lost a toy, or you’re worried about something little. You can still talk to Him about it. He cared about a lost axe head, and He cares about YOU. What little thing can you tell Heavenly Father about today?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-12-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What did the man lose in the water? What did Elisha do to help?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-12-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w2-n6', 7, 'Week 2 · Night 6', 'Horses of Fire All Around', '2 Kings 6', '[{"type": "cover", "img": "images/book/jul-13-0.jpg", "alt": "Cover illustration for “Horses of Fire All Around”"}, {"type": "story", "img": "images/book/jul-13-1.jpg", "alt": "Illustration: An enemy army wanted to catch Elisha.", "text": ["An enemy army wanted to catch Elisha. One morning, Elisha’s young helper woke up and saw soldiers all around the city! “Oh no!” he cried. “What are we going to do?”", "But Elisha was calm. “Don’t be afraid,” he said. “There are more helpers with us than there are enemies.” The young man looked around and felt scared and confused. He couldn’t see any helpers."]}, {"type": "story", "img": "images/book/jul-13-2.jpg", "alt": "Illustration: So Elisha prayed, “Lord, open his eyes so he can see.” Suddenly the young man saw the hills full of horses and…", "text": ["So Elisha prayed, “Lord, open his eyes so he can see.” Suddenly the young man saw the hills full of horses and chariots of FIRE! God’s mighty helpers were everywhere, protecting them.", "Heavenly Father sends help we cannot always see. Angels and His power are all around us. When we feel scared, we don’t have to be — God is bigger than anything. We are never really alone."]}, {"type": "moment", "img": "images/book/jul-13-3.jpg", "alt": "Illustration: Cover your eyes with your hands like the scared helper.", "text": ["Cover your eyes with your hands like the scared helper. Now open them wide and look all around — “Wow! Horses of fire everywhere!” Heavenly Father had helpers all around them the whole time. He has helpers around you too, even when you can’t see them."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When you feel scared, remember: Heavenly Father’s helpers are all around you! You can’t always see them, but they are there. God is stronger than anything that scares you. You are never alone. What helps you feel brave when you’re afraid?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-13-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What did Elisha’s helper see after Elisha prayed? Who has more helpers — God’s side or the enemy’s?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-13-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w2-n7', 7, 'Week 2 · Night 7', 'Good News to Share', '2 Kings 7', '[{"type": "cover", "img": "images/book/jul-14-0.jpg", "alt": "Cover illustration for “Good News to Share”"}, {"type": "story", "img": "images/book/jul-14-1.jpg", "alt": "Illustration: There was no food in the city, and everyone was hungry.", "text": ["There was no food in the city, and everyone was hungry. Four men sat outside the gate, hungry too. “Let’s go to the enemy camp,” they said. “Maybe they’ll give us food.” But when they got there — the camp was empty!", "Heavenly Father had made the enemies run away in fear. They left behind food, gold, clothes, everything! The four men ate and ate. They were so happy and full."]}, {"type": "story", "img": "images/book/jul-14-2.jpg", "alt": "Illustration: Then they stopped and said, “This is good news!", "text": ["Then they stopped and said, “This is good news! We can’t keep it to ourselves. Everyone in the city is hungry — we have to tell them!” So they hurried back to share the wonderful news.", "Soon the whole city had food, just like the prophet said! When we have good news, we share it. The gospel is the best news of all. Heavenly Father wants us to share His love with everyone."]}, {"type": "moment", "img": "images/book/jul-14-3.jpg", "alt": "Illustration: Cup your hands around your mouth and call out, “I have good news!” Now run in place like the four men hurrying…", "text": ["Cup your hands around your mouth and call out, “I have good news!” Now run in place like the four men hurrying to tell everyone. Sharing good news makes everyone happy! The best news of all is that Heavenly Father loves us."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When you know something wonderful, share it! The men found food and shared it with everyone. You know the best news of all — that Heavenly Father and Jesus love you! Who can you share Heavenly Father’s love with this week?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-14-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What did the four men find in the camp? Why did they decide to share the good news?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-14-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w3-n1', 7, 'Week 3 · Night 1', 'Good King Hezekiah Trusts God', '2 Kings 18', '[{"type": "cover", "img": "images/book/jul-15-0.jpg", "alt": "Cover illustration for “Good King Hezekiah Trusts God”"}, {"type": "story", "img": "images/book/jul-15-1.jpg", "alt": "Illustration: Hezekiah became the king of Judah.", "text": ["Hezekiah became the king of Judah. He loved Heavenly Father with all his heart. The people had been worshiping pretend gods and idols. Hezekiah said, “We will follow the true God!”", "He took away all the idols and false things. He helped the people remember Heavenly Father. Hezekiah trusted God more than any king before him. He held tight to the Lord and obeyed Him."]}, {"type": "story", "img": "images/book/jul-15-2.jpg", "alt": "Illustration: Because Hezekiah trusted God, Heavenly Father was with him.", "text": ["Because Hezekiah trusted God, Heavenly Father was with him. The Lord helped him and blessed the people. When troubles came, Hezekiah knew where to turn. He always looked to God first.", "Trusting Heavenly Father means believing He will help us. It means choosing Him over everything else. When we trust God, He stays close to us. Trusting God is the best choice a heart can make."]}, {"type": "moment", "img": "images/book/jul-15-3.jpg", "alt": "Illustration: Reach out and grab a grown-up’s hand and hold on tight — don’t let go!", "text": ["Reach out and grab a grown-up’s hand and hold on tight — don’t let go! That’s how Hezekiah held onto Heavenly Father, trusting Him completely. Holding God’s hand keeps us safe and brave. Who can you trust and hold onto?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Trusting Heavenly Father means believing He loves you and will help you. King Hezekiah trusted God and got rid of anything that pulled him away. You can trust God too — He is always there for you. How can you show Heavenly Father you trust Him?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-15-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What did Hezekiah get rid of so the people could follow God? Did Hezekiah trust the Lord?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-15-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w3-n2', 7, 'Week 3 · Night 2', 'Hezekiah Shows God the Letter', '2 Kings 19', '[{"type": "cover", "img": "images/book/jul-16-0.jpg", "alt": "Cover illustration for “Hezekiah Shows God the Letter”"}, {"type": "story", "img": "images/book/jul-16-1.jpg", "alt": "Illustration: A scary enemy king sent King Hezekiah a mean letter.", "text": ["A scary enemy king sent King Hezekiah a mean letter. The letter said, “We’re going to win! Your God can’t save you!” Hezekiah felt worried and afraid. What should he do?", "Hezekiah didn’t fight or panic. Instead, he took the letter straight to the temple. He spread the letter open before Heavenly Father. “Please, Lord, see this and help us,” he prayed."]}, {"type": "story", "img": "images/book/jul-16-2.jpg", "alt": "Illustration: Heavenly Father heard Hezekiah’s prayer.", "text": ["Heavenly Father heard Hezekiah’s prayer. He sent the prophet Isaiah with a message: “Don’t be afraid. I will protect this city.” And God did! He saved His people that very night.", "When we have a big worry, we can bring it to Heavenly Father. We can “spread it out” before Him in prayer. He listens, and He helps. Taking our troubles to God is always the right thing to do."]}, {"type": "moment", "img": "images/book/jul-16-3.jpg", "alt": "Illustration: Pretend you have a worry in your hands.", "text": ["Pretend you have a worry in your hands. Now “spread it out” and lay it down in front of you, like Hezekiah laid the letter before God. Take a deep breath out — whoosh — and let the worry go. Heavenly Father can carry our worries for us."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When you’re worried or scared, take it to Heavenly Father! Hezekiah didn’t keep his worry inside — he spread it out before God in prayer. You can tell Heavenly Father exactly what’s bothering you. What worry can you give to Heavenly Father tonight?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-16-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What did Hezekiah do with the scary letter? Did Heavenly Father help him?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-16-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w3-n3', 7, 'Week 3 · Night 3', 'God Gives Hezekiah More Days', '2 Kings 20', '[{"type": "cover", "img": "images/book/jul-17-0.jpg", "alt": "Cover illustration for “God Gives Hezekiah More Days”"}, {"type": "story", "img": "images/book/jul-17-1.jpg", "alt": "Illustration: One day King Hezekiah got very, very sick.", "text": ["One day King Hezekiah got very, very sick. The prophet said he might not get better. Hezekiah was sad. He turned his face to the wall and prayed and cried to Heavenly Father.", "“Please, Lord, remember how I have tried to follow You.” Heavenly Father heard his prayer right away. He told the prophet, “Go back and tell Hezekiah I have heard him. I will make him well.”"]}, {"type": "story", "img": "images/book/jul-17-2.jpg", "alt": "Illustration: God promised Hezekiah fifteen more years of life!", "text": ["God promised Hezekiah fifteen more years of life! As a special sign, He even made a shadow move backward. Hezekiah got better, just like Heavenly Father said.", "Heavenly Father hears our prayers, even when we are very sad. He loves us and answers in the way that is best. Hezekiah trusted God, and God blessed him. Prayer brings us close to our Father in Heaven."]}, {"type": "moment", "img": "images/book/jul-17-3.jpg", "alt": "Illustration: Put your hand over your heart and say a quiet “thank you” to Heavenly Father, like Hezekiah did when he got be…", "text": ["Put your hand over your heart and say a quiet “thank you” to Heavenly Father, like Hezekiah did when he got better. Feel your heart beating — that’s a gift from God! Heavenly Father gives us each day. Let’s be thankful for the days we have."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Heavenly Father hears your prayers, even when you’re sad! Hezekiah prayed when he was sick, and God answered him. You can pray when you feel sick, sad, or scared. What is something you can thank Heavenly Father for today?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-17-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What did Hezekiah do when he was very sick? How did Heavenly Father answer him?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-17-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w3-n4', 7, 'Week 3 · Night 4', 'The Boy Who Became King', '2 Kings 22', '[{"type": "cover", "img": "images/book/jul-18-0.jpg", "alt": "Cover illustration for “The Boy Who Became King”"}, {"type": "story", "img": "images/book/jul-18-1.jpg", "alt": "Illustration: There was a little boy named Josiah.", "text": ["There was a little boy named Josiah. When he was only eight years old, he became the king! That’s younger than some of your friends. But Josiah had a good and tender heart.", "Even though he was young, Josiah wanted to do what was right. The kings before him had made many bad choices. But Josiah chose to follow Heavenly Father. He did not turn to the left or the right."]}, {"type": "story", "img": "images/book/jul-18-2.jpg", "alt": "Illustration: Josiah didn’t say, “I’m too little to be good.” He just tried his best to please the Lord every day.", "text": ["Josiah didn’t say, “I’m too little to be good.” He just tried his best to please the Lord every day. People could see his good heart. He became a wonderful king.", "You are never too young to be good! Heavenly Father is pleased when little children choose the right. Josiah was small, but his good choices were big. You can be like Josiah today."]}, {"type": "moment", "img": "images/book/jul-18-3.jpg", "alt": "Illustration: Stand up tall and proud, even though you’re little — like young King Josiah!", "text": ["Stand up tall and proud, even though you’re little — like young King Josiah! Put on a pretend crown and say, “I can choose the right!” You don’t have to be big to be good. Heavenly Father loves your good choices, no matter how little you are."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["You are NEVER too young to choose the right! Josiah was just eight years old, but he had a good heart and followed God. You can be kind, honest, and obedient right now, today. What good choice can you make today, even though you’re little?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-18-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["How old was Josiah when he became king? Did he choose to follow Heavenly Father?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-18-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w3-n5', 7, 'Week 3 · Night 5', 'The Lost Book Is Found', '2 Kings 22', '[{"type": "cover", "img": "images/book/jul-19-0.jpg", "alt": "Cover illustration for “The Lost Book Is Found”"}, {"type": "story", "img": "images/book/jul-19-1.jpg", "alt": "Illustration: King Josiah wanted to fix up the temple, God’s house.", "text": ["King Josiah wanted to fix up the temple, God’s house. The workers cleaned and repaired it carefully. While they were working, they found something amazing. It was a long-lost book — the holy scriptures!", "The people had forgotten about God’s words for a long, long time. The priest brought the book to King Josiah. When Josiah heard the scriptures read out loud, he listened with all his heart."]}, {"type": "story", "img": "images/book/jul-19-2.jpg", "alt": "Illustration: Josiah was so moved that he tore his clothes — that’s how people showed strong feelings back then.", "text": ["Josiah was so moved that he tore his clothes — that’s how people showed strong feelings back then. He realized the people had not been following God’s words. “We need to obey what the scriptures say!” he said.", "The scriptures are God’s words to us, and they are precious. They teach us how to be happy and good. Josiah treasured them. We can read and listen to the scriptures too."]}, {"type": "moment", "img": "images/book/jul-19-3.jpg", "alt": "Illustration: Pretend to open a big, special book and hug it close to your heart.", "text": ["Pretend to open a big, special book and hug it close to your heart. The scriptures are a treasure! Run your finger across a pretend page like you’re reading God’s words. Heavenly Father speaks to us through the scriptures. Aren’t we lucky to have them?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["The scriptures are a special treasure from Heavenly Father! They are full of His words, just for us. King Josiah was so happy to find them and obey them. You can listen to scripture stories every day, like right now! How does it feel to hear stories from God’s word?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-19-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What special book did the workers find in the temple? How did King Josiah feel when he heard God’s words?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-19-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w3-n6', 7, 'Week 3 · Night 6', 'Huldah Speaks for God', '2 Kings 22', '[{"type": "cover", "img": "images/book/jul-20-0.jpg", "alt": "Cover illustration for “Huldah Speaks for God”"}, {"type": "story", "img": "images/book/jul-20-1.jpg", "alt": "Illustration: King Josiah had a big question.", "text": ["King Josiah had a big question. He wanted to know what Heavenly Father thought about His people. So he sent his helpers to ask a wise woman named Huldah. Huldah was a prophetess — God spoke through her.", "The helpers came to Huldah and asked for God’s message. Huldah listened to the Lord. Then she told them exactly what Heavenly Father wanted to say. She spoke God’s truth bravely and clearly."]}, {"type": "story", "img": "images/book/jul-20-2.jpg", "alt": "Illustration: Huldah said the Lord saw Josiah’s tender, humble heart.", "text": ["Huldah said the Lord saw Josiah’s tender, humble heart. Because Josiah had listened and tried so hard, God would bless him. The king was grateful for her message from the Lord.", "Heavenly Father speaks through people He chooses, like Huldah and the prophets. When we listen to them, we hear God’s words. God can use anyone with a willing heart. We can listen and obey His messengers."]}, {"type": "moment", "img": "images/book/jul-20-3.jpg", "alt": "Illustration: Cup your hand to your ear and listen carefully, like Josiah’s helpers listening to Huldah.", "text": ["Cup your hand to your ear and listen carefully, like Josiah’s helpers listening to Huldah. Now nod your head “yes” to show you’ll obey. Heavenly Father gives us messengers to share His words. When we listen, we stay close to God."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Heavenly Father speaks through special people He chooses! Huldah listened to God and shared His message bravely. When we listen to prophets and good leaders, we hear what God wants. Who is someone who teaches you about Heavenly Father?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-20-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["Who did the king’s helpers ask about God’s message? What did Huldah do?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-20-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w3-n7', 7, 'Week 3 · Night 7', 'King Josiah Makes a Promise', '2 Kings 23', '[{"type": "cover", "img": "images/book/jul-21-0.jpg", "alt": "Cover illustration for “King Josiah Makes a Promise”"}, {"type": "story", "img": "images/book/jul-21-1.jpg", "alt": "Illustration: After hearing God’s words, King Josiah gathered all the people together.", "text": ["After hearing God’s words, King Josiah gathered all the people together. He read the holy scriptures out loud so everyone could hear. Then he made a special promise to Heavenly Father. “We will love God and keep His commandments!”", "All the people stood up and made the promise too. Josiah helped them clean every bad and false thing out of the land. They got rid of all the idols. They wanted to follow only the true God."]}, {"type": "story", "img": "images/book/jul-21-2.jpg", "alt": "Illustration: Josiah also helped the people celebrate a special holy day to remember God.", "text": ["Josiah also helped the people celebrate a special holy day to remember God. There had not been a celebration like it for a very long time. Everyone’s heart turned back to Heavenly Father.", "When we make promises to God, we call them covenants. Keeping our promises to Heavenly Father makes us strong and happy. Josiah led the people back to God. We can keep our promises too."]}, {"type": "moment", "img": "images/book/jul-21-3.jpg", "alt": "Illustration: Put your hand over your heart and make a promise: “I will follow Heavenly Father.” That’s a covenant — a speci…", "text": ["Put your hand over your heart and make a promise: “I will follow Heavenly Father.” That’s a covenant — a special promise to God! Josiah and all the people did this together. Promises to God make our hearts strong. Let’s keep our promises!"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["A promise to Heavenly Father is called a covenant, and keeping it makes you strong! Josiah promised to follow God, and so did all the people. You make promises too — to be kind, to obey, to pray. What good promise can you keep this week?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-21-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What promise did Josiah and the people make to God? What did they clean out of the land?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-21-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w4-n1', 7, 'Week 4 · Night 1', 'King Asa Calls on God', '2 Chronicles 14', '[{"type": "cover", "img": "images/book/jul-22-0.jpg", "alt": "Cover illustration for “King Asa Calls on God”"}, {"type": "story", "img": "images/book/jul-22-1.jpg", "alt": "Illustration: Asa was a good king of Judah who loved Heavenly Father.", "text": ["Asa was a good king of Judah who loved Heavenly Father. He helped the people get rid of idols and follow God. One day, a HUGE army came to fight against them. There were so many enemies — way more than Asa’s soldiers!", "Asa wasn’t sure how they could win. But he didn’t give up or panic. Instead, he cried out to Heavenly Father. “Lord, only You can help us! We trust in You.”"]}, {"type": "story", "img": "images/book/jul-22-2.jpg", "alt": "Illustration: Heavenly Father heard Asa’s prayer.", "text": ["Heavenly Father heard Asa’s prayer. He helped the small army of Judah win! The big enemy army ran away. God’s power is bigger than any problem.", "It doesn’t matter how big a problem is. With Heavenly Father, anything is possible! Asa didn’t count on numbers — he counted on God. When we call on the Lord, He helps us. He is our greatest helper."]}, {"type": "moment", "img": "images/book/jul-22-3.jpg", "alt": "Illustration: Make yourself small and say “uh oh, the problem is so big!” Now reach up high to Heavenly Father and call, “He…", "text": ["Make yourself small and say “uh oh, the problem is so big!” Now reach up high to Heavenly Father and call, “Help me, Lord!” With God, even big problems become small. He is stronger than anything you face!"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["No problem is too big for Heavenly Father! Asa had a tiny army and a giant enemy, but he trusted God and won. When something feels too big for you, call on the Lord. What big thing can you ask Heavenly Father to help you with?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-22-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["Was Asa’s army big or small? Who helped Asa win against the giant army?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-22-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w4-n2', 7, 'Week 4 · Night 2', 'Be Strong and Don’t Give Up', '2 Chronicles 15', '[{"type": "cover", "img": "images/book/jul-23-0.jpg", "alt": "Cover illustration for “Be Strong and Don’t Give Up”"}, {"type": "story", "img": "images/book/jul-23-1.jpg", "alt": "Illustration: A man named Azariah had a message from Heavenly Father for King Asa.", "text": ["A man named Azariah had a message from Heavenly Father for King Asa. He said, “The Lord is with you when you are with Him. If you look for God, you will find Him!” That was wonderful news.", "Then Azariah said something important: “Be strong! Don’t let your hands be weak. Your good work will be rewarded.” This helped King Asa feel brave and happy."]}, {"type": "story", "img": "images/book/jul-23-2.jpg", "alt": "Illustration: So Asa kept working hard to follow God.", "text": ["So Asa kept working hard to follow God. He kept getting rid of bad things and doing good. The people gathered together and promised to seek the Lord with all their hearts.", "Heavenly Father wants us to be strong and not give up doing good. When we seek Him, we always find Him. Our good work is never wasted. Keep going — God will reward you!"]}, {"type": "moment", "img": "images/book/jul-23-3.jpg", "alt": "Illustration: Flex your arms and make your strongest muscles!", "text": ["Flex your arms and make your strongest muscles! Say loudly, “Be strong! Don’t give up!” That’s the message God gave to King Asa. When you feel like quitting, be strong and keep doing good. God sees all your good work!"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Be strong and don’t give up doing good! Sometimes good things are hard, and you might want to quit. But Heavenly Father says, “Be strong — your good work will be rewarded!” What good thing can you keep doing, even when it’s hard?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-23-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What did Azariah tell King Asa to do? What happens when we look for Heavenly Father?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-23-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w4-n3', 7, 'Week 4 · Night 3', 'When Asa Forgot to Trust', '2 Chronicles 16', '[{"type": "cover", "img": "images/book/jul-24-0.jpg", "alt": "Cover illustration for “When Asa Forgot to Trust”"}, {"type": "story", "img": "images/book/jul-24-1.jpg", "alt": "Illustration: King Asa had trusted God for many years.", "text": ["King Asa had trusted God for many years. But when a new problem came, Asa forgot to ask Heavenly Father first. Instead, he tried to fix it all by himself. He made a deal with another king for help.", "A wise messenger named Hanani came to Asa. He said, “Asa, why didn’t you trust the Lord this time? God’s eyes look all over the earth to help those who trust Him.”"]}, {"type": "story", "img": "images/book/jul-24-2.jpg", "alt": "Illustration: Asa felt upset because he knew he had made a mistake.", "text": ["Asa felt upset because he knew he had made a mistake. Even good King Asa forgot to lean on God this time. We all make mistakes sometimes. The important thing is to remember to trust God again.", "Heavenly Father wants us to trust Him in EVERYTHING — big and small. Even when we forget, we can turn back to Him. God is always watching, ready to help. Let’s remember to ask Him first."]}, {"type": "moment", "img": "images/book/jul-24-3.jpg", "alt": "Illustration: Point to your eyes, then point all around the room — Heavenly Father’s eyes see everywhere, looking for people…", "text": ["Point to your eyes, then point all around the room — Heavenly Father’s eyes see everywhere, looking for people to help! Now point up and say, “I’ll trust You first, Heavenly Father.” Even when we forget, we can always turn back to God."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Remember to trust Heavenly Father in everything — even the little things! Asa was a good king, but one time he forgot to ask God first. We all forget sometimes, and that’s okay. We can always turn back and trust Him again. What can you remember to ask Heavenly Father about?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-24-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What did Asa forget to do when a new problem came? Who is always watching, ready to help us?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-24-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w4-n4', 7, 'Week 4 · Night 4', 'Judges Who Are Fair', '2 Chronicles 19', '[{"type": "cover", "img": "images/book/jul-25-0.jpg", "alt": "Cover illustration for “Judges Who Are Fair”"}, {"type": "story", "img": "images/book/jul-25-1.jpg", "alt": "Illustration: King Jehoshaphat loved Heavenly Father.", "text": ["King Jehoshaphat loved Heavenly Father. He wanted everyone in the land to be treated fairly. So he chose good, wise people to be judges. Judges help decide what is right and fair.", "Jehoshaphat told the judges something important. “Be careful and fair. Remember, you are not just judging for people — you are judging for the Lord!” He wanted them to be honest and kind."]}, {"type": "story", "img": "images/book/jul-25-2.jpg", "alt": "Illustration: He told them, “Do your work with a happy, brave heart, and God will be with the good.” The judges promised to…", "text": ["He told them, “Do your work with a happy, brave heart, and God will be with the good.” The judges promised to be fair to everyone. They wanted to please Heavenly Father.", "Heavenly Father wants us to be fair and kind to everyone. We treat all people the way God would want. Being fair makes families and friends happy. Fairness shows we love God and His children."]}, {"type": "moment", "img": "images/book/jul-25-3.jpg", "alt": "Illustration: Hold out both hands flat like a balance scale and keep them even and level.", "text": ["Hold out both hands flat like a balance scale and keep them even and level. That’s being fair — treating everyone the same! Jehoshaphat wanted everyone to be treated fairly. Can you keep your hands nice and even, like fairness?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Heavenly Father wants you to be fair and kind to everyone! That means taking turns, sharing, and not leaving anyone out. King Jehoshaphat wanted everyone treated fairly. How can you be fair and kind to someone today?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-25-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What did King Jehoshaphat want the judges to be? Who did he say they were really judging for?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-25-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w4-n5', 7, 'Week 4 · Night 5', 'Our Eyes Are upon Thee', '2 Chronicles 20', '[{"type": "cover", "img": "images/book/jul-26-0.jpg", "alt": "Cover illustration for “Our Eyes Are upon Thee”"}, {"type": "story", "img": "images/book/jul-26-1.jpg", "alt": "Illustration: A huge army was coming to fight King Jehoshaphat’s people.", "text": ["A huge army was coming to fight King Jehoshaphat’s people. There were so many enemies! Jehoshaphat felt afraid. But he knew exactly what to do — he gathered everyone to pray.", "Jehoshaphat prayed a beautiful prayer: “Heavenly Father, we don’t know what to do. But OUR EYES ARE UPON THEE.” That means, “We are looking to You for help, Lord!”"]}, {"type": "story", "img": "images/book/jul-26-2.jpg", "alt": "Illustration: Heavenly Father answered, “Don’t be afraid.", "text": ["Heavenly Father answered, “Don’t be afraid. This battle is Mine. Just stand still and watch Me save you.” So the next day, the people SANG praises to God as they marched out. And the enemies were defeated without Judah even fighting!", "When we don’t know what to do, we can look to Heavenly Father. “Our eyes are upon Thee” means we trust God to lead us. He fights our battles. We just need to keep our eyes on Him."]}, {"type": "moment", "img": "images/book/jul-26-3.jpg", "alt": "Illustration: Point to your eyes, then look up toward heaven and say, “Our eyes are upon Thee!” That means, “I’m looking to…", "text": ["Point to your eyes, then look up toward heaven and say, “Our eyes are upon Thee!” That means, “I’m looking to You, Heavenly Father!” When you don’t know what to do, look up to God. He always knows the way."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When you don’t know what to do, look to Heavenly Father — “our eyes are upon Thee!” Jehoshaphat didn’t know how to win, so he kept his eyes on God. And God saved them! When have you not known what to do? You can look to Him!"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-26-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What did Jehoshaphat pray when he was scared? What did the people do instead of fighting?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-26-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w4-n6', 7, 'Week 4 · Night 6', 'The King Who Forgot to Stay Humble', '2 Chronicles 26', '[{"type": "cover", "img": "images/book/jul-27-0.jpg", "alt": "Cover illustration for “The King Who Forgot to Stay Humble”"}, {"type": "story", "img": "images/book/jul-27-1.jpg", "alt": "Illustration: Uzziah became king when he was just sixteen.", "text": ["Uzziah became king when he was just sixteen. He loved God, and as long as he sought the Lord, God helped him do amazing things. He built towers and won battles. He became very strong and famous.", "But when Uzziah got strong, he started to feel proud. He forgot that his blessings came from Heavenly Father. He thought he could do whatever he wanted, even break God’s rules."]}, {"type": "story", "img": "images/book/jul-27-2.jpg", "alt": "Illustration: Uzziah went into the temple to do something only the priests were supposed to do.", "text": ["Uzziah went into the temple to do something only the priests were supposed to do. The priests said, “Please don’t — that’s not your job!” But Uzziah got angry instead of humble. Then he got sick right away.", "Pride means thinking we’re better than others and forgetting God. Heavenly Father wants us to stay humble and grateful. When we remember our blessings come from Him, we stay happy and close to God. Humble hearts please the Lord."]}, {"type": "moment", "img": "images/book/jul-27-3.jpg", "alt": "Illustration: Puff up your chest big and proud, then let all the air out and bow your head humbly.", "text": ["Puff up your chest big and proud, then let all the air out and bow your head humbly. Ahh, that feels better! Heavenly Father loves a humble heart. Let’s stay thankful and remember our blessings come from Him."], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Stay humble and remember that your blessings come from Heavenly Father! King Uzziah did great things, but then he got proud and forgot God. Being humble means saying “thank you” to God and following His rules. What can you thank Heavenly Father for tonight?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-27-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What happened to Uzziah’s heart when he became strong? Does Heavenly Father want us proud or humble?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-27-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b7-w4-n7', 7, 'Week 4 · Night 7', 'Come Celebrate with God', '2 Chronicles 30', '[{"type": "cover", "img": "images/book/jul-28-0.jpg", "alt": "Cover illustration for “Come Celebrate with God”"}, {"type": "story", "img": "images/book/jul-28-1.jpg", "alt": "Illustration: Good King Hezekiah wanted everyone to come back to Heavenly Father.", "text": ["Good King Hezekiah wanted everyone to come back to Heavenly Father. He sent invitations all across the land. “Come to God’s house! Let’s celebrate and remember the Lord together!”", "Some people laughed and didn’t want to come. That made Hezekiah a little sad. But many other people humbled their hearts and said, “Yes! We will come!” They traveled to join the celebration."]}, {"type": "story", "img": "images/book/jul-28-2.jpg", "alt": "Illustration: Everyone gathered together to worship and remember Heavenly Father.", "text": ["Everyone gathered together to worship and remember Heavenly Father. There was so much joy and singing and gladness! It was the happiest celebration in a very long time. The people’s hearts turned back to God.", "Heavenly Father always invites us to come back to Him. There is great joy in worshiping God together. When we come to Him with a humble heart, He welcomes us with love. Coming back to God always brings happiness."]}, {"type": "moment", "img": "images/book/jul-28-3.jpg", "alt": "Illustration: Wave your arm like you’re inviting friends over: “Come, come celebrate with God!” Now clap and cheer for the h…", "text": ["Wave your arm like you’re inviting friends over: “Come, come celebrate with God!” Now clap and cheer for the happy celebration! Heavenly Father loves it when we come to Him. There is so much joy in worshiping together. Can you feel the happiness?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Heavenly Father always invites you to come close to Him — and it brings great joy! King Hezekiah invited everyone to celebrate God, and those who came were so happy. You can come to Heavenly Father anytime, through prayer, church, and good choices. How can you come closer to Heavenly Father this week?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/jul-28-5.jpg", "alt": "A parent and child talking together at bedtime", "text": ["What did King Hezekiah invite everyone to do? How did the people feel when they came to celebrate God?"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/jul-28-6.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

-- ---------------------------------------------------------------------
--  I Will Trust and Sing
-- ---------------------------------------------------------------------
insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b8-w1-n1', 8, 'Week 1 · Night 1', 'The King Says, “You May Go Home!”', 'Ezra 1; 3–7; Nehemiah 2; 4–6; 8', '[{"type": "cover", "img": "images/book/aug-01-0.jpg", "alt": "Cover illustration for “The King Says, “You May Go Home!””"}, {"type": "story", "img": "images/book/aug-01-1.jpg", "alt": "Illustration: Long ago, Heavenly Father’s people lived far away from home in a land called Babylon.", "text": ["Long ago, Heavenly Father’s people lived far away from home in a land called Babylon. Their beautiful city, Jerusalem, was empty, and Heavenly Father’s temple was gone. The people missed home so very much.", "One day, a mighty king named Cyrus stood up and made a wonderful announcement. “Heavenly Father has helped me,” he said. “His people may go home and build Him a temple again!”"]}, {"type": "story", "img": "images/book/aug-01-2.jpg", "alt": "Illustration: The people could hardly believe their happy ears.", "text": ["The people could hardly believe their happy ears. King Cyrus even gave back the special gold and silver bowls that belonged in Heavenly Father’s temple. Families packed their bags with big smiles and started the long journey home. Heavenly Father had promised long ago that they could return — and He kept His promise. When Heavenly Father makes a promise, He always keeps it."]}, {"type": "moment", "img": "images/book/aug-01-3.jpg", "alt": "Illustration: Scout fits tonight because going home took trust that Heavenly Father would lead the way.", "text": ["Scout fits tonight because going home took trust that Heavenly Father would lead the way. In Scout’s world today: Scout’s family just moved to a brand-new house, and the new room felt strange and a little scary. But Scout took a big breath, remembered Heavenly Father leads His children, and went exploring — finding a friendly neighbor’s dog and the coziest reading corner. “Heavenly Father helped me find good things here!” Just like the people trusted Him on the road home, Scout trusted Him in a brand-new place."], "eyebrow": "Scripture Traveler of the Night", "heading": "Scout the Seeker"}, {"type": "moment", "img": "images/book/aug-01-4.jpg", "alt": "Illustration: Let’s pack a pretend bag!", "text": ["Let’s pack a pretend bag! Reach out and “grab” your favorite things and tuck them inside. Now sling it over your shoulder and take three big marching steps — we’re going home! Can you feel how happy a big journey feels?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Heavenly Father keeps His promises to YOU, just like He did for His people going home. When He asks you to do something good, you can trust Him with your whole heart. What is one thing you can trust Heavenly Father to help you with tomorrow?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/aug-01-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“Who let Heavenly Father’s people go home?”", "“What did the people go home to build?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/aug-01-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b8-w1-n2', 8, 'Week 1 · Night 2', 'The First Big Stone', 'Ezra 1; 3–7; Nehemiah 2; 4–6; 8', '[{"type": "cover", "img": "images/book/aug-02-0.jpg", "alt": "Cover illustration for “The First Big Stone”"}, {"type": "story", "img": "images/book/aug-02-1.jpg", "alt": "Illustration: When the people reached home, the temple ground was just dirt and rubble.", "text": ["When the people reached home, the temple ground was just dirt and rubble. But they were not sad for long — they were ready to build Heavenly Father’s house!", "First, they set up an altar so they could pray and worship together. Then the builders came with big, heavy stones to lay the very first layer, called the foundation."]}, {"type": "story", "img": "images/book/aug-02-2.jpg", "alt": "Illustration: When the foundation was finished, the people had a giant celebration!", "text": ["When the foundation was finished, the people had a giant celebration! Trumpets played and cymbals crashed. Everyone sang, “Heavenly Father is so good; His love lasts forever!”", "Something tender happened too. The oldest people remembered the very first temple, long ago, and happy tears rolled down their cheeks. So there was singing AND crying, all mixed together, and Heavenly Father saw every bit of it. Big feelings are welcome when we worship Him."]}, {"type": "moment", "img": "images/book/aug-02-3.jpg", "alt": "Illustration: Willow fits tonight because she notices every kind of feeling.", "text": ["Willow fits tonight because she notices every kind of feeling. In Willow’s world today: at Grandma’s birthday, Willow saw Grandma cry — but they were happy tears! Instead of feeling worried, Willow climbed up for a hug and said, “Your happy tears are okay, Grandma.” Just like the people who laughed and cried while they praised Heavenly Father, Willow learned that joy and tears can live in the very same heart."], "eyebrow": "Scripture Traveler of the Night", "heading": "Willow the Warm"}, {"type": "moment", "img": "images/book/aug-02-4.jpg", "alt": "Illustration: Let’s make a joyful noise!", "text": ["Let’s make a joyful noise! Clap your hands like clanging cymbals — crash, crash! Now hum a happy little “la-la-la.” Some feelings are so big they bring happy tears. Can you show me a happy face… and a teary face?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Your feelings are a gift from Heavenly Father — even the big ones! It’s okay to feel happy and cry at the very same time. He loves your whole heart. When was a time you felt a really big feeling today?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/aug-02-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did the people build first?”", "“Why did some of the older people cry?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/aug-02-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b8-w1-n3', 8, 'Week 1 · Night 3', 'The Temple Is Finished!', 'Ezra 1; 3–7; Nehemiah 2; 4–6; 8', '[{"type": "cover", "img": "images/book/aug-03-0.jpg", "alt": "Cover illustration for “The Temple Is Finished!”"}, {"type": "story", "img": "images/book/aug-03-1.jpg", "alt": "Illustration: Building the temple was not always easy.", "text": ["Building the temple was not always easy. Some unkind neighbors tried to make the people stop, and for a while the work grew quiet and slow.", "But two of Heavenly Father’s prophets, Haggai and Zechariah, cheered the people on. “Keep going!” they said. “Heavenly Father is with you!” So the people picked up their tools again."]}, {"type": "story", "img": "images/book/aug-03-2.jpg", "alt": "Illustration: A new king named Darius found King Cyrus’s old promise in the royal books.", "text": ["A new king named Darius found King Cyrus’s old promise in the royal books. “Let them build!” Darius said. “And give them whatever they need.” What wonderful news!", "Tap, tap, tap — the hammers sang, and higher and higher the temple rose, until at last it was finished! The people threw a joyful party to give the whole temple to Heavenly Father. He had helped them finish what they started, even when it was hard."]}, {"type": "moment", "img": "images/book/aug-03-3.jpg", "alt": "Illustration: Beau fits tonight because he keeps going when things get hard.", "text": ["Beau fits tonight because he keeps going when things get hard. In Beau’s world today: Beau was building a tall block tower and it kept toppling — crash! Beau wanted to quit and cry. But he took a breath, said a little prayer, and tried again, stacking slower and steadier, until the tower stood tall. “I didn’t give up!” Just like the people who finished Heavenly Father’s temple, Beau finished the hard thing with Heavenly Father’s help."], "eyebrow": "Scripture Traveler of the Night", "heading": "Beau the Brave"}, {"type": "moment", "img": "images/book/aug-03-4.jpg", "alt": "Illustration: Let’s build together!", "text": ["Let’s build together! Stack your hands one on top of the other, higher and higher — tap, tap, tap. Now throw your arms up high: “It’s finished!” Doesn’t it feel good to finish something you worked hard on?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When something good is hard, Heavenly Father helps you keep going! Maybe you’re learning to tie your shoes or clean your whole room. Don’t give up — He is right there with you. What is something hard you can keep trying, even when it’s tricky?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/aug-03-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“Who told the people to keep building?”", "“How did everyone feel when the temple was finished?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/aug-03-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b8-w1-n4', 8, 'Week 1 · Night 4', 'Ezra Loves the Scriptures', 'Ezra 1; 3–7; Nehemiah 2; 4–6; 8', '[{"type": "cover", "img": "images/book/aug-04-0.jpg", "alt": "Cover illustration for “Ezra Loves the Scriptures”"}, {"type": "story", "img": "images/book/aug-04-1.jpg", "alt": "Illustration: There was a good man named Ezra who loved Heavenly Father with all his heart.", "text": ["There was a good man named Ezra who loved Heavenly Father with all his heart. More than almost anything, Ezra loved to read Heavenly Father’s holy words, the scriptures.", "Ezra didn’t just read the scriptures once and forget them. He studied them carefully. He set his heart to learn them, to live them, and to teach them to others."]}, {"type": "story", "img": "images/book/aug-04-2.jpg", "alt": "Illustration: The king trusted Ezra so much that he sent him on a long journey to help the people back home.", "text": ["The king trusted Ezra so much that he sent him on a long journey to help the people back home. “Teach them Heavenly Father’s ways,” the king said.", "So Ezra traveled far, carrying the scriptures like a treasure. Heavenly Father watched over him the whole way. When we love the scriptures like Ezra, our hearts grow wise and strong."]}, {"type": "moment", "img": "images/book/aug-04-3.jpg", "alt": "Illustration: Wren fits tonight because she slows down to let good things sink in.", "text": ["Wren fits tonight because she slows down to let good things sink in. In Wren’s world today: at story time, everyone was rushing to the next page, but Wren wanted to stop and think. “Wait — what did that part mean?” she wondered. She read it again and found something wonderful. Just like Ezra, who set his heart to study Heavenly Father’s words, Wren learned that pondering slowly helps the good things stay in your heart."], "eyebrow": "Scripture Traveler of the Night", "heading": "Wren the Wonderer"}, {"type": "moment", "img": "images/book/aug-04-4.jpg", "alt": "Illustration: Let’s open a pretend book!", "text": ["Let’s open a pretend book! Hold out both hands like pages and “read” with your finger, left to right. Now hug the book close to your heart. Heavenly Father’s words are a treasure. Can you show me how much you love them with a great big squeeze?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["You can love the scriptures like Ezra did — even now! When you listen to a bedtime scripture story, you are filling your heart with Heavenly Father’s words. What is your favorite scripture story so far?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/aug-04-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did Ezra love more than almost anything?”", "“What did the king send Ezra to do?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/aug-04-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b8-w1-n5', 8, 'Week 1 · Night 5', 'Nehemiah’s Brave Idea', 'Ezra 1; 3–7; Nehemiah 2; 4–6; 8', '[{"type": "cover", "img": "images/book/aug-05-0.jpg", "alt": "Cover illustration for “Nehemiah’s Brave Idea”"}, {"type": "story", "img": "images/book/aug-05-1.jpg", "alt": "Illustration: Far away in the king’s palace, a man named Nehemiah heard sad news.", "text": ["Far away in the king’s palace, a man named Nehemiah heard sad news. The walls around Jerusalem were broken down, and his people were not safe.", "Nehemiah’s heart felt so heavy. But he knew just what to do — he prayed and prayed to Heavenly Father for many days."]}, {"type": "story", "img": "images/book/aug-05-2.jpg", "alt": "Illustration: Then Nehemiah felt brave.", "text": ["Then Nehemiah felt brave. He asked the king, “May I please go home and rebuild the walls?” And the king said yes! He even sent wood to help.", "When Nehemiah reached Jerusalem, he quietly rode all around the broken walls at night to see what needed fixing. Then he told the people, “Come, let us rise up and build!” Heavenly Father had turned his heavy heart into a brave one."]}, {"type": "moment", "img": "images/book/aug-05-3.jpg", "alt": "Illustration: Beau fits tonight because a prayer helped him feel brave.", "text": ["Beau fits tonight because a prayer helped him feel brave. In Beau’s world today: Beau had a big pile of toys to clean up and it felt too big to start. His tummy felt worried. So Beau said a quick prayer — “Please help me” — took a deep breath, and picked up just one toy, then another. Soon the whole room was tidy! Just like Nehemiah prayed and then began the big work, Beau prayed and started, one little step at a time."], "eyebrow": "Scripture Traveler of the Night", "heading": "Beau the Brave"}, {"type": "moment", "img": "images/book/aug-05-4.jpg", "alt": "Illustration: Let’s be brave like Nehemiah!", "text": ["Let’s be brave like Nehemiah! First, fold your arms and bow your head to pray — soft and quiet. Now stand up tall, put your hands on your hips, and say, “Let us rise up and build!” Can you feel your prayer turning into brave?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When your heart feels heavy or scared, you can pray — and Heavenly Father will help you be brave! Then you can start your job one little step at a time, just like Nehemiah. What is something brave you’d like Heavenly Father to help you do?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/aug-05-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did Nehemiah do first when his heart felt heavy?”", "“What did he want to rebuild?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/aug-05-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b8-w1-n6', 8, 'Week 1 · Night 6', '“I Am Doing a Great Work”', 'Ezra 1; 3–7; Nehemiah 2; 4–6; 8', '[{"type": "cover", "img": "images/book/aug-06-0.jpg", "alt": "Cover illustration for ““I Am Doing a Great Work””"}, {"type": "story", "img": "images/book/aug-06-1.jpg", "alt": "Illustration: As the people built the walls, some grumpy men tried to stop them.", "text": ["As the people built the walls, some grumpy men tried to stop them. They laughed and teased. “You can’t do it!” they said. But the people just kept building.", "The workers were wise. They held a building tool in one hand and stayed close together, trusting Heavenly Father to keep them safe. “Heavenly Father will fight for us,” they said."]}, {"type": "story", "img": "images/book/aug-06-2.jpg", "alt": "Illustration: The grumpy men tried a sneaky trick.", "text": ["The grumpy men tried a sneaky trick. “Come down and talk to us,” they called, again and again, hoping Nehemiah would stop his important work.", "But Nehemiah stood tall on the wall and called back, “I am doing a great work, so I cannot come down!” He would not let anything pull him away from Heavenly Father’s job. And in just fifty-two days, the wall was finished!"]}, {"type": "moment", "img": "images/book/aug-06-3.jpg", "alt": "Illustration: Wren fits tonight because she stops to think about what matters most.", "text": ["Wren fits tonight because she stops to think about what matters most. In Wren’s world today: Wren was cleaning up like Mom asked when a friend called, “Come play right now!” Wren paused and wondered, “What’s most important first?” She finished her job, then went to play with a happy heart. Just like Nehemiah wouldn’t come down from his great work, Wren knew the difference between a silly distraction and an important job."], "eyebrow": "Scripture Traveler of the Night", "heading": "Wren the Wonderer"}, {"type": "moment", "img": "images/book/aug-06-4.jpg", "alt": "Illustration: Let’s stay strong on the wall!", "text": ["Let’s stay strong on the wall! Plant your feet, stand up tall, and shake your head “no, no, no” to the silly distractions. Now say it big: “I am doing a great work!” Can you keep building with your hands while you say it?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["You can keep doing good, even when others try to pull you away! Like Nehemiah, you can say, “I have important work to do.” Finishing your good jobs makes Heavenly Father happy. What is a “great work” you can finish this week — a chore, or a kind deed?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/aug-06-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did the grumpy men want Nehemiah to do?”", "“What did Nehemiah say back to them?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/aug-06-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b8-w1-n7', 8, 'Week 1 · Night 7', 'The Happiest Reading Day', 'Ezra 1; 3–7; Nehemiah 2; 4–6; 8', '[{"type": "cover", "img": "images/book/aug-07-0.jpg", "alt": "Cover illustration for “The Happiest Reading Day”"}, {"type": "story", "img": "images/book/aug-07-1.jpg", "alt": "Illustration: When the walls were finished, all the people gathered together in one big place.", "text": ["When the walls were finished, all the people gathered together in one big place. They wanted to hear Heavenly Father’s holy words.", "Good Ezra stood on a tall wooden platform and opened the scriptures. He read out loud from early morning, and everyone listened carefully with all their hearts."]}, {"type": "story", "img": "images/book/aug-07-2.jpg", "alt": "Illustration: As they listened, some of the people began to cry.", "text": ["As they listened, some of the people began to cry. They were sorry for the times they had forgotten Heavenly Father. But the leaders said something kind: “Don’t be sad today! This is a happy day.”", "Then came the best part: “The joy of the Lord is your strength!” So the people wiped their tears, shared yummy food with everyone, and celebrated. It was one of the happiest days ever — all because of Heavenly Father’s words."]}, {"type": "moment", "img": "images/book/aug-07-3.jpg", "alt": "Illustration: Scout fits tonight because Scout loves to discover treasure and share it.", "text": ["Scout fits tonight because Scout loves to discover treasure and share it. In Scout’s world today: at preschool, Scout learned a happy new song about Heavenly Father and could hardly wait to share it. Scout ran home, calling, “Listen! I learned something wonderful!” and taught it to the whole family. Just like the people who found joy in Heavenly Father’s words, Scout discovered that the best things are even better when we share them."], "eyebrow": "Scripture Traveler of the Night", "heading": "Scout the Seeker"}, {"type": "moment", "img": "images/book/aug-07-4.jpg", "alt": "Illustration: Let’s celebrate the scriptures!", "text": ["Let’s celebrate the scriptures! Cup your hands around your mouth and cheer, “Hooray for Heavenly Father’s word!” Now rub your tummy and share a pretend treat with someone you love. Can you turn a sad face into a great big joyful smile?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Heavenly Father’s words can make your heart glad and strong, even on a hard day! When you listen to scripture stories, joy sneaks right into your heart. How do you feel inside when you hear a story about Heavenly Father?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/aug-07-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did Ezra read to all the people?”", "“What did the leaders say would be the people’s strength?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/aug-07-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b8-w2-n1', 8, 'Week 2 · Night 1', 'A Kind Girl Becomes Queen', 'Esther', '[{"type": "cover", "img": "images/book/aug-08-0.jpg", "alt": "Cover illustration for “A Kind Girl Becomes Queen”"}, {"type": "story", "img": "images/book/aug-08-1.jpg", "alt": "Illustration: In a faraway kingdom lived a kind young woman named Esther.", "text": ["In a faraway kingdom lived a kind young woman named Esther. She had no mommy or daddy, so her good cousin Mordecai took care of her and loved her like his own.", "One day, the king was looking for a new queen. Many young women came to the palace, but Esther’s gentle, kind heart shone the brightest of all."]}, {"type": "story", "img": "images/book/aug-08-2.jpg", "alt": "Illustration: The king chose Esther to be the new queen!", "text": ["The king chose Esther to be the new queen! She wore a beautiful crown, but she stayed just as humble and kind as before.", "Mordecai told Esther to keep something special a secret for now — that she was one of Heavenly Father’s chosen people. Esther listened wisely. Heavenly Father had a special plan for this kind, humble girl."]}, {"type": "moment", "img": "images/book/aug-08-3.jpg", "alt": "Illustration: Willow fits tonight because a kind heart is her superpower.", "text": ["Willow fits tonight because a kind heart is her superpower. In Willow’s world today: a new child stood alone at the playground, looking shy. Willow could have kept playing, but instead she walked over and said, “Want to play with me?” The new friend beamed. Just like Esther’s kindness shone in the palace, Willow’s kindness helped someone feel welcome and loved."], "eyebrow": "Scripture Traveler of the Night", "heading": "Willow the Warm"}, {"type": "moment", "img": "images/book/aug-08-4.jpg", "alt": "Illustration: Let’s put on a pretend crown!", "text": ["Let’s put on a pretend crown! Place your hands gently on your head like a sparkly crown, then take a little bow. A crown is nice — but a kind heart is even better. Can you show me your very kindest smile?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Your kind heart is beautiful to Heavenly Father — more than any crown! You can be gentle and kind wherever you go, just like Esther. Who is someone you can be kind to tomorrow?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/aug-08-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“Who took care of Esther and loved her?”", "“What did the king choose Esther to be?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/aug-08-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b8-w2-n2', 8, 'Week 2 · Night 2', 'Mordecai Stands Tall', 'Esther', '[{"type": "cover", "img": "images/book/aug-09-0.jpg", "alt": "Cover illustration for “Mordecai Stands Tall”"}, {"type": "story", "img": "images/book/aug-09-1.jpg", "alt": "Illustration: There was a very proud man named Haman who worked for the king.", "text": ["There was a very proud man named Haman who worked for the king. Haman wanted everyone to bow down low to him whenever he walked by.", "Everybody bowed — everybody except Mordecai. Mordecai was kind and respectful, but he only bowed down to worship Heavenly Father."]}, {"type": "story", "img": "images/book/aug-09-2.jpg", "alt": "Illustration: This made proud Haman very angry.", "text": ["This made proud Haman very angry. But Mordecai stood quietly and firmly. He knew that worship belongs only to Heavenly Father.", "Mordecai was not being unkind — he was being faithful. It can take courage to do what’s right when everyone else is doing something different. Heavenly Father is pleased when we stand tall for Him."]}, {"type": "moment", "img": "images/book/aug-09-3.jpg", "alt": "Illustration: Beau fits tonight because he does what’s right even when it’s hard.", "text": ["Beau fits tonight because he does what’s right even when it’s hard. In Beau’s world today: some kids were teasing another child, and they wanted Beau to join in. Beau felt his tummy flip, but he shook his head and said, “That’s not kind.” Then he went and sat by the child who was sad. Just like Mordecai stood tall for Heavenly Father, Beau stood tall for what was right, even when it wasn’t easy."], "eyebrow": "Scripture Traveler of the Night", "heading": "Beau the Brave"}, {"type": "moment", "img": "images/book/aug-09-4.jpg", "alt": "Illustration: Let’s stand tall like Mordecai!", "text": ["Let’s stand tall like Mordecai! Put your feet strong on the floor, straighten your back, and stand as tall as you can. Now put your hand on your heart. Can you stand tall and say, “I love Heavenly Father”?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["You can stand tall for Heavenly Father, even when others don’t! You can be kind and respectful and still choose what’s right. When might it be brave to do the right thing this week?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/aug-09-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“Who did Mordecai bow down to worship?”", "“Why did Haman get angry?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/aug-09-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b8-w2-n3', 8, 'Week 2 · Night 3', 'For Such a Time as This', 'Esther', '[{"type": "cover", "img": "images/book/aug-10-0.jpg", "alt": "Cover illustration for “For Such a Time as This”"}, {"type": "story", "img": "images/book/aug-10-1.jpg", "alt": "Illustration: Proud Haman made a wicked plan to hurt Heavenly Father’s people.", "text": ["Proud Haman made a wicked plan to hurt Heavenly Father’s people. Mordecai was very worried. He sent a message to Queen Esther, asking her to help. Esther felt afraid. Going to the king without being called could be dangerous. What should she do?"]}, {"type": "story", "img": "images/book/aug-10-2.jpg", "alt": "Illustration: Then Mordecai said something wise: “Maybe Heavenly Father made you queen for this very reason — for such a tim…", "text": ["Then Mordecai said something wise: “Maybe Heavenly Father made you queen for this very reason — for such a time as this.”", "Esther grew quiet and thought about her special purpose. Perhaps Heavenly Father had placed her right where she was to help save her people. Heavenly Father gives each of us a purpose, right where we are."]}, {"type": "moment", "img": "images/book/aug-10-3.jpg", "alt": "Illustration: Wren the Wonderer", "eyebrow": "Scripture Traveler of the Night", "heading": "Wren the Wonderer"}, {"type": "moment", "img": "images/book/aug-10-4.jpg", "alt": "Illustration: Let’s think quietly, like Esther.", "text": ["Let’s think quietly, like Esther. Put your finger to your chin and make a big “hmm, I wonder” face. Now nod your head like you’ve decided something brave. What do you think Esther will do?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Heavenly Father gives YOU a purpose, right where you are — in your family, your class, your home! You can look for ways to help, just like Esther. How might Heavenly Father want to use your helping hands?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/aug-10-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What wise thing did Mordecai tell Esther?”", "“What did “for such a time as this”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/aug-10-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b8-w2-n4', 8, 'Week 2 · Night 4', 'Esther’s Brave Choice', 'Esther', '[{"type": "cover", "img": "images/book/aug-11-0.jpg", "alt": "Cover illustration for “Esther’s Brave Choice”"}, {"type": "story", "img": "images/book/aug-11-1.jpg", "alt": "Illustration: Esther decided to be brave and help her people.", "text": ["Esther decided to be brave and help her people. But first, she wanted Heavenly Father’s help.", "She asked everyone to fast and pray with her for three whole days. “Then I will go to the king,” she said, “and if I perish, I perish.” That means she would be brave no matter what."]}, {"type": "story", "img": "images/book/aug-11-2.jpg", "alt": "Illustration: After praying, Esther put on her royal robe and walked bravely to the king.", "text": ["After praying, Esther put on her royal robe and walked bravely to the king. Her heart was probably beating fast, but she kept going.", "The king smiled and welcomed her! He held out his golden scepter, which meant, “Come closer, I’m happy to see you.” Heavenly Father had helped brave Esther every step of the way."]}, {"type": "moment", "img": "images/book/aug-11-3.jpg", "alt": "Illustration: Beau fits tonight because he asks Heavenly Father for help before doing hard things.", "text": ["Beau fits tonight because he asks Heavenly Father for help before doing hard things. In Beau’s world today: Beau had to get a shot at the doctor, and he felt scared. He squeezed Mom’s hand, took a big brave breath, and whispered a little prayer. It still pinched, but Beau did it! Just like Esther prayed and then bravely went to the king, Beau prayed and then did the hard, brave thing."], "eyebrow": "Scripture Traveler of the Night", "heading": "Beau the Brave"}, {"type": "moment", "img": "images/book/aug-11-4.jpg", "alt": "Illustration: ", "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When something feels scary, you can pray and ask Heavenly Father for a brave heart — then do the hard thing anyway, like Esther! What is something brave Heavenly Father can help you do?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/aug-11-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did Esther ask everyone to do for three days?”", "“How did the king welcome Esther?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/aug-11-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b8-w2-n5', 8, 'Week 2 · Night 5', 'Esther’s Wise Plan', 'Esther', '[{"type": "cover", "img": "images/book/aug-12-0.jpg", "alt": "Cover illustration for “Esther’s Wise Plan”"}, {"type": "story", "img": "images/book/aug-12-1.jpg", "alt": "Illustration: Esther was brave, and she was also wise.", "text": ["Esther was brave, and she was also wise. She did not rush. She invited the king and Haman to a special dinner she had prepared.", "Everyone ate the yummy food, and the king asked, “Esther, what would you like? I will give it to you.” But Esther waited for just the right moment."]}, {"type": "story", "img": "images/book/aug-12-2.jpg", "alt": "Illustration: “Please come to one more dinner tomorrow,” she said kindly.", "text": ["“Please come to one more dinner tomorrow,” she said kindly. She was being patient and wise, waiting for the best time to speak.", "The next night, when the moment was just right, Esther would tell the king the truth. Heavenly Father helped her know when to wait and when to speak. Being wise means choosing the right time."]}, {"type": "moment", "img": "images/book/aug-12-3.jpg", "alt": "Illustration: Wren fits tonight because she knows the wisdom of waiting for the right moment.", "text": ["Wren fits tonight because she knows the wisdom of waiting for the right moment. In Wren’s world today: Wren wanted to tell Dad her big news, but he was on an important phone call. She really, really wanted to interrupt! Instead, she waited patiently, and when he finished, she shared her news — and he could truly listen. Just like Esther waited for the right time, Wren learned that patience makes our words land better."], "eyebrow": "Scripture Traveler of the Night", "heading": "Wren the Wonderer"}, {"type": "moment", "img": "images/book/aug-12-4.jpg", "alt": "Illustration: Let’s practice waiting wisely.", "text": ["Let’s practice waiting wisely. Fold your hands in your lap and sit as still as a statue... wait... wait... now gently smile. Waiting can be hard! Can you show me your calmest, most patient face?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Heavenly Father can help you be patient and wait for the right time, just like wise Esther! Waiting is hard, but it helps good things go well. When is a time you can practice patient waiting?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/aug-12-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did Esther invite the king and Haman to?”", "“What did wise Esther choose to do before speaking?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b8-w2-n6', 8, 'Week 2 · Night 6', 'The King Saves the People', 'Esther', '[{"type": "cover", "img": "images/book/aug-13-0.jpg", "alt": "Cover illustration for “The King Saves the People”"}, {"type": "story", "img": "images/book/aug-13-1.jpg", "alt": "Illustration: At the second dinner, the moment was finally right.", "text": ["At the second dinner, the moment was finally right. Brave Queen Esther spoke the truth to the king. “Please save me and my people,” she said. “A wicked plan has been made to hurt us.” The king asked, “Who would do such a thing?” Esther answered, “It is Haman.”"]}, {"type": "story", "img": "images/book/aug-13-2.jpg", "alt": "Illustration: The king was very upset with proud Haman.", "text": ["The king was very upset with proud Haman. He stopped Haman’s wicked plan right away and kept Esther and her people safe.", "Because Esther was brave and told the truth, Heavenly Father’s people were saved! Speaking the truth, even when it’s hard, can help and protect the people we love."]}, {"type": "moment", "img": "images/book/aug-13-3.jpg", "alt": "Illustration: Scout fits tonight because Scout is honest and speaks up.", "text": ["Scout fits tonight because Scout is honest and speaks up. In Scout’s world today: Scout saw a smaller child’s tower get knocked down by accident, and the child was blamed. Scout spoke up: “It was a bump — nobody meant to.” Telling the truth made everything fair again. Just like brave Esther told the truth to save her people, Scout learned that honest words can protect and help others."], "eyebrow": "Scripture Traveler of the Night", "heading": "Scout the Seeker"}, {"type": "moment", "img": "images/book/aug-13-4.jpg", "alt": "Illustration: Let’s use a brave, truthful voice!", "text": ["Let’s use a brave, truthful voice! Stand tall, put your hand on your heart, and say clearly, “I will tell the truth.” A truthful voice is a strong voice. Can you say it big and brave?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Telling the truth, even when it’s hard, is brave and good — and it can help the people you love! You can be honest like Esther. When might it take courage to tell the truth?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/aug-13-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What truth did Esther bravely tell the king?”", "“What did the king do to keep the people safe?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/aug-13-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b8-w2-n7', 8, 'Week 2 · Night 7', 'A Happy Celebration', 'Esther', '[{"type": "cover", "img": "images/book/aug-14-0.jpg", "alt": "Cover illustration for “A Happy Celebration”"}, {"type": "story", "img": "images/book/aug-14-1.jpg", "alt": "Illustration: Heavenly Father’s people were safe, and their sadness turned into great joy!", "text": ["Heavenly Father’s people were safe, and their sadness turned into great joy! They wanted to remember this wonderful day forever.", "So they made a special holiday called Purim. Every year, families would celebrate that Heavenly Father had saved them through brave Queen Esther."]}, {"type": "story", "img": "images/book/aug-14-2.jpg", "alt": "Illustration: On this happy day, people shared yummy treats and gave gifts to one another.", "text": ["On this happy day, people shared yummy treats and gave gifts to one another. They even gave presents to those who had little, so everyone could feel the joy. Remembering how Heavenly Father helps us fills our hearts with thankfulness. And sharing our joy with others — especially by giving — makes the happiness even bigger."]}, {"type": "moment", "img": "images/book/aug-14-3.jpg", "alt": "Illustration: Willow fits tonight because she loves to share joy and give to others.", "text": ["Willow fits tonight because she loves to share joy and give to others. In Willow’s world today: Willow had two cookies and saw a friend who had none. She thought about keeping both… but instead she said, “Here — let’s share!” Both girls giggled with happy, full hearts. Just like the people shared gifts at their celebration, Willow learned that joy grows bigger the moment we share it."], "eyebrow": "Scripture Traveler of the Night", "heading": "Willow the Warm"}, {"type": "moment", "img": "images/book/aug-14-4.jpg", "alt": "Illustration: Let’s celebrate!", "text": ["Let’s celebrate! Clap your hands three times — clap, clap, clap! Now pretend to hand a gift to someone you love: “This is for you!” Sharing makes joy grow. Can you show me your happiest celebration dance?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When Heavenly Father helps us, we can be thankful and share our joy with others! Giving a gift or a smile makes happiness grow. Who could you share a little joy with tomorrow?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/aug-14-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What special holiday did the people make to remember?”", "“What did people share with each other on that happy day?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/aug-14-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b8-w3-n1', 8, 'Week 3 · Night 1', 'Job Loved Heavenly Father', 'Job 1–3; 12–14; 19; 21–24; 38–40; 42', '[{"type": "cover", "img": "images/book/aug-15-0.jpg", "alt": "Cover illustration for “Job Loved Heavenly Father”"}, {"type": "story", "img": "images/book/aug-15-1.jpg", "alt": "Illustration: Long ago there lived a good man named Job.", "text": ["Long ago there lived a good man named Job. He loved Heavenly Father with all his heart, and he was kind to everyone around him.", "Job had a happy family and many animals to care for. Every day he thanked Heavenly Father for his blessings."]}, {"type": "story", "img": "images/book/aug-15-2.jpg", "alt": "Illustration: Job wasn’t only good when things were easy.", "text": ["Job wasn’t only good when things were easy. Loving Heavenly Father was simply who he was, deep down inside.", "Each morning, Job would pray for his family, asking Heavenly Father to watch over them. His heart was full of love and thankfulness. Heavenly Father was very pleased with faithful Job."]}, {"type": "moment", "img": "images/book/aug-15-3.jpg", "alt": "Illustration: Willow the Warm", "eyebrow": "Scripture Traveler of the Night", "heading": "Willow the Warm"}, {"type": "moment", "img": "images/book/aug-15-4.jpg", "alt": "Illustration: Let’s thank Heavenly Father like Job!", "text": ["Let’s thank Heavenly Father like Job! Put your hands together and count three blessings on your fingers — one, two, three. Now give a happy sigh: “Thank you, Heavenly Father.” What are you thankful for tonight?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["You can love Heavenly Father and thank Him every day, just like Job — not only when things are easy, but all the time! What is one blessing you can thank Heavenly Father for right now?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/aug-15-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“Who did Job love with all his heart?”", "“What did Job do every morning for his family?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/aug-15-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b8-w3-n2', 8, 'Week 3 · Night 2', 'Job Keeps Trusting', 'Job 1–3; 12–14; 19; 21–24; 38–40; 42', '[{"type": "cover", "img": "images/book/aug-16-0.jpg", "alt": "Cover illustration for “Job Keeps Trusting”"}, {"type": "story", "img": "images/book/aug-16-1.jpg", "alt": "Illustration: One day, hard things began to happen to Job.", "text": ["One day, hard things began to happen to Job. He lost his animals, and then his big house was gone too. Soon after, Job did not feel well at all.", "Job was very sad. So many good things had gone away, and he didn’t understand why."]}, {"type": "story", "img": "images/book/aug-16-2.jpg", "alt": "Illustration: But even with his heavy heart, Job did something wonderful.", "text": ["But even with his heavy heart, Job did something wonderful. He bowed down and said, “I will still trust Heavenly Father.”", "Job didn’t stop loving Heavenly Father, even when life was hard. He held onto his faith like a strong little anchor. Trusting Heavenly Father in hard times is one of the bravest things we can do."]}, {"type": "moment", "img": "images/book/aug-16-3.jpg", "alt": "Illustration: Beau fits tonight because he trusts Heavenly Father even when things are hard.", "text": ["Beau fits tonight because he trusts Heavenly Father even when things are hard. In Beau’s world today: Beau’s favorite toy broke, and he felt so sad — he even cried a little. But after his tears, Beau took a breath and remembered that Heavenly Father still loved him and would help him feel better. Just like Job kept trusting through his hard day, Beau learned that we can be sad AND still trust Heavenly Father at the same time."], "eyebrow": "Scripture Traveler of the Night", "heading": "Beau the Brave"}, {"type": "moment", "img": "images/book/aug-16-4.jpg", "alt": "Illustration: When things are hard, we can hold on tight.", "text": ["When things are hard, we can hold on tight. Give yourself a big squeezy hug and hold on… hold on… now take a slow breath out. Heavenly Father holds us close. Can you give a strong “holding-on” hug?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Even when something makes you sad, you can still trust Heavenly Father — He never leaves you! It’s okay to feel sad and hold onto Him at the same time. Who can you talk to when you feel sad?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/aug-16-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What happened to Job that made him sad?”", "“What did Job say he would still do?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/aug-16-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b8-w3-n3', 8, 'Week 3 · Night 3', 'Kind Friends Come to Sit', 'Job 1–3; 12–14; 19; 21–24; 38–40; 42', '[{"type": "cover", "img": "images/book/aug-17-0.jpg", "alt": "Cover illustration for “Kind Friends Come to Sit”"}, {"type": "story", "img": "images/book/aug-17-1.jpg", "alt": "Illustration: When Job was sad and not feeling well, his friends heard about it.", "text": ["When Job was sad and not feeling well, his friends heard about it. They wanted to help, so they came to be with him.", "At first, Job’s friends didn’t say a single word. They just sat quietly beside him for a long, long time."]}, {"type": "story", "img": "images/book/aug-17-2.jpg", "alt": "Illustration: Sometimes when someone is sad, the kindest thing is simply to be near them.", "text": ["Sometimes when someone is sad, the kindest thing is simply to be near them. Job’s friends showed love just by staying close.", "Being there for a sad friend is a beautiful gift. A quiet hug or a hand to hold can say, “I love you, and you’re not alone.” Heavenly Father loves it when we comfort one another."]}, {"type": "moment", "img": "images/book/aug-17-3.jpg", "alt": "Illustration: Willow fits tonight because she notices who is hurting and stays close.", "text": ["Willow fits tonight because she notices who is hurting and stays close. In Willow’s world today: Willow’s friend fell down and scraped her knee and started to cry. Willow didn’t know how to fix it, so she just sat beside her friend and held her hand until she felt better. Just like Job’s friends sat quietly with him, Willow learned that being near someone who is sad is a gift of love."], "eyebrow": "Scripture Traveler of the Night", "heading": "Willow the Warm"}, {"type": "moment", "img": "images/book/aug-17-4.jpg", "alt": "Illustration: Let’s show quiet kindness.", "text": ["Let’s show quiet kindness. Sit close to someone you love and give a gentle pat on the back — pat, pat, pat. No words needed! Can you be a kind, quiet friend right now?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When someone is sad, you can be a kind friend just by being near them — a hug or a hand to hold means so much! Who could you sit with and comfort when they feel sad?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/aug-17-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did Job’s friends do when they first came?”", "“How can we help a friend who feels sad?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/aug-17-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b8-w3-n4', 8, 'Week 3 · Night 4', 'Job Tells Heavenly Father His Feelings', 'Job1–3;12–14;19;21–24;38–40;42', '[{"type": "cover", "img": "images/book/aug-18-0.jpg", "alt": "Cover illustration for “Job Tells Heavenly Father His Feelings”"}, {"type": "story", "img": "images/book/aug-18-1.jpg", "alt": "Illustration: Job had so many big feelings inside.", "text": ["Job had so many big feelings inside. He felt sad and confused, and he had lots of questions.", "So Job talked to Heavenly Father about all of it. He didn’t hide his feelings — he shared them honestly, just like talking to a loving Father."]}, {"type": "story", "img": "images/book/aug-18-2.jpg", "alt": "Illustration: Even in his sadness, Job remembered something hopeful.", "text": ["Even in his sadness, Job remembered something hopeful. “I know that my Redeemer lives,” he said. That means he trusted that Heavenly Father would make everything right someday.", "It’s good to tell Heavenly Father exactly how we feel. He is never upset by our honest hearts. And He always gives us hope, even on our hardest days."]}, {"type": "moment", "img": "images/book/aug-18-3.jpg", "alt": "Illustration: Wren fits tonight because she thinks deeply and holds onto hope.", "text": ["Wren fits tonight because she thinks deeply and holds onto hope. In Wren’s world today: Wren had a hard day and felt grumpy inside. At bedtime, instead of keeping it in, she told Heavenly Father all about it in her prayer. Afterward, she felt lighter, and she remembered that tomorrow was a fresh new day. Just like Job shared his honest feelings and kept his hope, Wren learned that telling Heavenly Father everything brings peace."], "eyebrow": "Scripture Traveler of the Night", "heading": "Wren the Wonderer"}, {"type": "moment", "img": "images/book/aug-18-4.jpg", "alt": "Illustration: Let’s tell Heavenly Father our feelings.", "text": ["Let’s tell Heavenly Father our feelings. Put your hand on your heart and take a deep breath. Now whisper, “Heavenly Father, this is how I feel.” He always listens. Can you take a big feelings-breath with me?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["You can tell Heavenly Father exactly how you feel — even the sad or confused feelings! He always listens and always gives hope. What feeling would you like to share with Heavenly Father tonight?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/aug-18-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“Who did Job talk to about his big feelings?”", "“What hopeful thing did Job remember?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/aug-18-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b8-w3-n5', 8, 'Week 3 · Night 5', 'Heavenly Father Shows His Wonders', 'Job 1–3; 12–14; 19; 21–24; 38–40; 42', '[{"type": "cover", "img": "images/book/aug-19-0.jpg", "alt": "Cover illustration for “Heavenly Father Shows His Wonders”"}, {"type": "story", "img": "images/book/aug-19-1.jpg", "alt": "Illustration: After a long, hard time, Heavenly Father spoke to Job.", "text": ["After a long, hard time, Heavenly Father spoke to Job. But He didn’t scold him. Instead, He showed Job all the amazing things He had made!", "“Job, did you hang the twinkling stars? Did you make the great big sea? Do you know where the snow is kept?” Heavenly Father asked."]}, {"type": "story", "img": "images/book/aug-19-2.jpg", "alt": "Illustration: Job looked at the wide sky, the wild animals, and the deep ocean, and his eyes grew big with wonder.", "text": ["Job looked at the wide sky, the wild animals, and the deep ocean, and his eyes grew big with wonder. Heavenly Father was so much bigger and wiser than Job had ever imagined.", "When we look at the stars, the mountains, and the tiny ladybugs, we can see how great Heavenly Father is. He made it all, and He is wise enough to take care of everything — including us."]}, {"type": "moment", "img": "images/book/aug-19-3.jpg", "alt": "Illustration: Scout fits tonight because Scout loves to notice the wonders of Heavenly Father’s world.", "text": ["Scout fits tonight because Scout loves to notice the wonders of Heavenly Father’s world. In Scout’s world today: on a walk, Scout stopped to watch a tiny ant carry a crumb ten times its size. “Look and see — how did Heavenly Father make something so little so strong?” Scout wondered. Just like Job’s eyes grew big at Heavenly Father’s creations, Scout discovered that the whole world is full of Heavenly Father’s amazing work."], "eyebrow": "Scripture Traveler of the Night", "heading": "Scout the Seeker"}, {"type": "moment", "img": "images/book/aug-19-4.jpg", "alt": "Illustration: Let’s look at the wonders!", "text": ["Let’s look at the wonders! Point up high like you’re touching the stars, then sweep your arms wide like the big ocean. Wow — Heavenly Father made it all! Can you show me your most amazed “wow” face?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When you look at the stars, the animals, and the tiny bugs, you can see how great and wise Heavenly Father is — big enough to care for you! What is your favorite thing Heavenly Father made?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/aug-19-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did Heavenly Father show Job?”", "“What can we learn about Heavenly Father from the stars and the sea?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/aug-19-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b8-w3-n6', 8, 'Week 3 · Night 6', 'Job Trusts Heavenly Father’s Wisdom', 'Job 1–3; 12–14; 19; 21–24; 38–40; 42', '[{"type": "cover", "img": "images/book/aug-20-0.jpg", "alt": "Cover illustration for “Job Trusts Heavenly Father’s Wisdom”"}, {"type": "story", "img": "images/book/aug-20-1.jpg", "alt": "Illustration: After seeing all of Heavenly Father’s wonderful works, Job understood something important.", "text": ["After seeing all of Heavenly Father’s wonderful works, Job understood something important. Heavenly Father knows and sees everything — even the things Job could not understand.", "“I trust You,” Job said humbly. “You are wise, and You know what is best. I don’t need to understand everything.”"]}, {"type": "story", "img": "images/book/aug-20-2.jpg", "alt": "Illustration: Job felt peaceful again.", "text": ["Job felt peaceful again. He didn’t have all the answers, but he had something even better: he had trust in Heavenly Father.", "Sometimes we won’t understand why hard things happen, and that’s okay. We can still trust that Heavenly Father is wise and loving. His plan is always good, even when we can’t see the whole picture."]}, {"type": "moment", "img": "images/book/aug-20-3.jpg", "alt": "Illustration: Wren fits tonight because she’s learning that we don’t have to understand everything.", "text": ["Wren fits tonight because she’s learning that we don’t have to understand everything. In Wren’s world today: Wren asked why she couldn’t have a treat before dinner, and Mom said, “Trust me — it’s so you’ll feel good later.” Wren didn’t fully understand, but she trusted Mom’s love. Just like Job trusted Heavenly Father’s wisdom without knowing everything, Wren learned that trust means believing in someone’s love and wisdom."], "eyebrow": "Scripture Traveler of the Night", "heading": "Wren the Wonderer"}, {"type": "moment", "img": "images/book/aug-20-4.jpg", "alt": "Illustration: Let’s show trusting hearts.", "text": ["Let’s show trusting hearts. Cross your arms gently over your heart and give a little squeeze. Now nod your head “yes” to Heavenly Father. Can you whisper, “I trust You, Heavenly Father”?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Sometimes we won’t understand why things happen — and that’s okay! We can still trust that Heavenly Father is wise and loves us. What is something you can trust Heavenly Father with, even if you don’t understand it?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/aug-20-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did Job say he would do, even without understanding everything?”", "“How did Job feel once he trusted Heavenly Father?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/aug-20-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b8-w3-n7', 8, 'Week 3 · Night 7', 'Heavenly Father Blesses Job Again', 'Job 1–3; 12–14; 19; 21–24; 38–40; 42', '[{"type": "cover", "img": "images/book/aug-21-0.jpg", "alt": "Cover illustration for “Heavenly Father Blesses Job Again”"}, {"type": "story", "img": "images/book/aug-21-1.jpg", "alt": "Illustration: Job’s hard time didn’t last forever.", "text": ["Job’s hard time didn’t last forever. After all his trusting and waiting, Heavenly Father blessed Job again — even more than before!", "Job had a happy home once more, with animals to care for and family all around. His heart was filled up with joy and thankfulness."]}, {"type": "story", "img": "images/book/aug-21-2.jpg", "alt": "Illustration: Job had learned something he would never forget: Heavenly Father is always good, in the hard times and the hap…", "text": ["Job had learned something he would never forget: Heavenly Father is always good, in the hard times and the happy times.", "Even on our very hardest days, morning always comes again. Heavenly Father loves us through the sad parts and brings joy back around. He is always, always faithful."]}, {"type": "moment", "img": "images/book/aug-21-3.jpg", "alt": "Illustration: Beau fits tonight because his faithfulness carried him all the way through to joy.", "text": ["Beau fits tonight because his faithfulness carried him all the way through to joy. In Beau’s world today: Beau was sad when it rained all day and playtime outside was canceled. But he trusted it would pass — and the next morning, the sun came out and the puddles were perfect for splashing! Just like Job trusted Heavenly Father through the hard time and joy came back, Beau learned that after the rain, the sunshine always returns."], "eyebrow": "Scripture Traveler of the Night", "heading": "Beau the Brave"}, {"type": "moment", "img": "images/book/aug-21-4.jpg", "alt": "Illustration: Let’s celebrate the sunshine after the rain!", "text": ["Let’s celebrate the sunshine after the rain! Wiggle your fingers down like falling rain, then throw your arms up like a bright, warm sun. Joy comes back! Can you show me rain… and then a big, happy sun?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Even on your hardest days, morning always comes again — Heavenly Father brings joy back around! He loves you through the sad parts. What is something happy you can look forward to tomorrow?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/aug-21-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did Heavenly Father do for Job after his hard time?”", "“What did Job learn about Heavenly Father?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/aug-21-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b8-w4-n1', 8, 'Week 4 · Night 1', 'The Happy Little Tree', 'Psalms 1–2; 8; 19–33; 40; 46', '[{"type": "cover", "img": "images/book/aug-22-0.jpg", "alt": "Cover illustration for “The Happy Little Tree”"}, {"type": "story", "img": "images/book/aug-22-1.jpg", "alt": "Illustration: A very long time ago, people wrote beautiful songs and poems to Heavenly Father.", "text": ["A very long time ago, people wrote beautiful songs and poems to Heavenly Father. We call them Psalms. One of them tells about a happy little tree. The song says a person who loves Heavenly Father’s words is like a tree planted right beside a cool, flowing river."]}, {"type": "story", "img": "images/book/aug-22-2.jpg", "alt": "Illustration: Because the tree drinks from the water every day, its roots grow deep and strong.", "text": ["Because the tree drinks from the water every day, its roots grow deep and strong. Its leaves stay green, and it grows sweet, healthy fruit.", "When we listen to Heavenly Father’s words each day, we’re like that happy tree drinking from the river. Our hearts grow strong and good, and we bloom with kindness and love."]}, {"type": "moment", "img": "images/book/aug-22-3.jpg", "alt": "Illustration: Wren fits tonight because she loves to soak in Heavenly Father’s words.", "text": ["Wren fits tonight because she loves to soak in Heavenly Father’s words. In Wren’s world today: every night, Wren asks for one more scripture story before bed. Little by little, those stories are growing in her heart like water helps a tree. When a friend was sad, Wren remembered a story about kindness and knew just what to do. Just like the happy tree by the river, Wren is growing strong and good from Heavenly Father’s words."], "eyebrow": "Scripture Traveler of the Night", "heading": "Wren the Wonderer"}, {"type": "moment", "img": "images/book/aug-22-4.jpg", "alt": "Illustration: Let’s be a strong little tree!", "text": ["Let’s be a strong little tree! Stand tall, stretch your arms up like branches, and wiggle your fingers like leaves in the breeze. Now stand firm and strong. Can you be a happy tree, rooted deep?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When you listen to Heavenly Father’s words each day, you grow strong and good, just like the happy little tree by the river! What good thing can you do each day to help your heart grow?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/aug-22-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What is the person who loves Heavenly Father’s words like?”", "“What helps the little tree grow strong?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/aug-22-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b8-w4-n2', 8, 'Week 4 · Night 2', 'Look at the Stars!', 'Psalms 1–2; 8; 19–33; 40; 46', '[{"type": "cover", "img": "images/book/aug-23-0.jpg", "alt": "Cover illustration for “Look at the Stars!”"}, {"type": "story", "img": "images/book/aug-23-1.jpg", "alt": "Illustration: One night, a person looked up at the wide, dark sky and saw thousands of twinkling stars.", "text": ["One night, a person looked up at the wide, dark sky and saw thousands of twinkling stars. It filled his heart with wonder, so he sang a song to Heavenly Father.", "“Heavenly Father, You are so wonderful! You made the moon and the shining stars and put them in their places.”"]}, {"type": "story", "img": "images/book/aug-23-2.jpg", "alt": "Illustration: Then he thought about something amazing.", "text": ["Then he thought about something amazing. With all the great big sky and stars, Heavenly Father still knows and loves each one of us.", "Even the littlest children are precious to Heavenly Father. He made the whole universe, and He still has room in His heart for you. How wonderful is that!"]}, {"type": "moment", "img": "images/book/aug-23-3.jpg", "alt": "Illustration: Scout the Seeker", "eyebrow": "Scripture Traveler of the Night", "heading": "Scout the Seeker"}, {"type": "moment", "img": "images/book/aug-23-4.jpg", "alt": "Illustration: Let’s reach for the stars!", "text": ["Let’s reach for the stars! Open and close your hands high in the sky like twinkling stars — twinkle, twinkle. Now point to yourself: Heavenly Father loves ME! Can you make your hands twinkle like little stars?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Heavenly Father made the whole sky full of stars — and He still knows and loves YOU! You are precious to Him. How does it feel to know Heavenly Father loves you so much?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/aug-23-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did the person see in the night sky?”", "“Even with all the stars, who does Heavenly Father still love?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/aug-23-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b8-w4-n3', 8, 'Week 4 · Night 3', 'The Good Shepherd', 'Psalms 1–2; 8; 19–33; 40; 46', '[{"type": "cover", "img": "images/book/aug-24-0.jpg", "alt": "Cover illustration for “The Good Shepherd”"}, {"type": "story", "img": "images/book/aug-24-1.jpg", "alt": "Illustration: A shepherd boy named David wrote one of the most beautiful songs of all.", "text": ["A shepherd boy named David wrote one of the most beautiful songs of all. He knew all about sheep and how a good shepherd takes care of them.", "“The Lord is my shepherd,” David sang. “He leads me to soft green grass and cool, quiet water. He helps me rest.”"]}, {"type": "story", "img": "images/book/aug-24-2.jpg", "alt": "Illustration: David knew that Heavenly Father cares for us just like a shepherd cares for his little lambs.", "text": ["David knew that Heavenly Father cares for us just like a shepherd cares for his little lambs. He leads us, feeds us, and keeps us safe.", "“Even in the dark, I will not be afraid,” David sang, “because Heavenly Father is with me.” When we feel scared, we can remember: our good Shepherd is always right beside us."]}, {"type": "moment", "img": "images/book/aug-24-3.jpg", "alt": "Illustration: Willow the Warm", "eyebrow": "Scripture Traveler of the Night", "heading": "Willow the Warm"}, {"type": "moment", "img": "images/book/aug-24-4.jpg", "alt": "Illustration: Let’s be cozy little lambs!", "text": ["Let’s be cozy little lambs! Curl up small and soft, then give a gentle “baa.” Now feel safe, because the Good Shepherd is near. Can you snuggle up like a sleepy little lamb?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Heavenly Father is your Good Shepherd — He leads you, keeps you safe, and is with you even in the dark! When you feel scared, what could you remember about your Shepherd?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/aug-24-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did David call Heavenly Father in his song?”", "“Why didn’t David need to be afraid, even in the dark?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/aug-24-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b8-w4-n4', 8, 'Week 4 · Night 4', 'Heavenly Father Is My Light', 'Psalms 1–2; 8; 19–33; 40; 46', '[{"type": "cover", "img": "images/book/aug-25-0.jpg", "alt": "Cover illustration for “Heavenly Father Is My Light”"}, {"type": "story", "img": "images/book/aug-25-1.jpg", "alt": "Illustration: Another song says, “Heavenly Father is my light.", "text": ["Another song says, “Heavenly Father is my light. Whom shall I fear?” A light helps us see and chases the scary dark away.", "When it’s nighttime and dark, a little light makes everything feel better. We can see where we’re going, and we don’t feel so afraid."]}, {"type": "story", "img": "images/book/aug-25-2.jpg", "alt": "Illustration: Heavenly Father is like that light for our hearts.", "text": ["Heavenly Father is like that light for our hearts. When we feel worried or scared, He shines warm and bright inside us.", "With Heavenly Father as our light, we don’t need to be afraid of the dark or of hard things. His love shines brightly, and it never, ever goes out."]}, {"type": "moment", "img": "images/book/aug-25-3.jpg", "alt": "Illustration: Beau fits tonight because Heavenly Father’s light makes him brave.", "text": ["Beau fits tonight because Heavenly Father’s light makes him brave. In Beau’s world today: the power went out and the whole house went dark, and Beau felt his heart jump. Then he remembered that Heavenly Father was with him, bright as any light. He took a brave breath, helped find the flashlight, and even comforted his little sister. Just like the psalm-writer said Heavenly Father is his light, Beau’s fear turned to brave."], "eyebrow": "Scripture Traveler of the Night", "heading": "Beau the Brave"}, {"type": "moment", "img": "images/book/aug-25-4.jpg", "alt": "Illustration: Let’s be a little light!", "text": ["Let’s be a little light! Make a fist, then pop your fingers open wide like a bright light turning on — shine! Now hold your light up high. Heavenly Father lights our hearts. Can you shine your bright light?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Heavenly Father is your light! When you feel worried or scared, He shines warm and bright inside you and helps you be brave. What makes you feel brave when you’re afraid of the dark?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/aug-25-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did the song say Heavenly Father is?”", "“How does a light help us when it’s dark?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/aug-25-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b8-w4-n5', 8, 'Week 4 · Night 5', 'Be Still and Know', 'Psalms 1–2; 8; 19–33; 40; 46', '[{"type": "cover", "img": "images/book/aug-26-0.jpg", "alt": "Cover illustration for “Be Still and Know”"}, {"type": "story", "img": "images/book/aug-26-1.jpg", "alt": "Illustration: Sometimes life feels loud and busy and fast.", "text": ["Sometimes life feels loud and busy and fast. There’s a special song for those times that says, “Be still, and know that Heavenly Father is with you.”", "Being still means slowing our bodies down and making our hearts quiet and calm."]}, {"type": "story", "img": "images/book/aug-26-2.jpg", "alt": "Illustration: When we get very still, we can feel Heavenly Father close, like a warm, peaceful hug for our hearts.", "text": ["When we get very still, we can feel Heavenly Father close, like a warm, peaceful hug for our hearts. Heavenly Father is our safe place. When everything feels too fast or too big, we can be still, take a breath, and remember He is right here with us. In the quiet, we find His peace."]}, {"type": "moment", "img": "images/book/aug-26-3.jpg", "alt": "Illustration: Wren fits tonight because she knows the gift of being still.", "text": ["Wren fits tonight because she knows the gift of being still. In Wren’s world today: the day was noisy and Wren felt wiggly and grumpy all over. Mom said, “Let’s be still for a minute.” Wren sat quietly, took a few slow breaths, and felt the grumpies melt away. Just like the psalm says to be still and know Heavenly Father is near, Wren discovered that quiet moments bring His peace."], "eyebrow": "Scripture Traveler of the Night", "heading": "Wren the Wonderer"}, {"type": "moment", "img": "images/book/aug-26-4.jpg", "alt": "Illustration: Let’s be still together.", "text": ["Let’s be still together. Sit very quietly and put your hands softly in your lap. Take one slow breath in... and out. Shhh — can you feel how peaceful still can be? Can you be as still as a sleeping kitten?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When everything feels too fast or too big, you can be still, take a breath, and remember Heavenly Father is right here with you! When could you practice being still and calm?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/aug-26-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What does the song say to do when life feels busy?”", "“What can we feel when we get very still?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/aug-26-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b8-w4-n6', 8, 'Week 4 · Night 6', 'A Brand-New Song', 'Psalms 1–2; 8; 19–33; 40; 46', '[{"type": "cover", "img": "images/book/aug-27-0.jpg", "alt": "Cover illustration for “A Brand-New Song”"}, {"type": "story", "img": "images/book/aug-27-1.jpg", "alt": "Illustration: One song-writer remembered a hard time when he felt stuck, like he was down in a deep, muddy pit and couldn’t…", "text": ["One song-writer remembered a hard time when he felt stuck, like he was down in a deep, muddy pit and couldn’t get out.", "So he called out to Heavenly Father for help. And Heavenly Father heard him! He gently lifted him up and set his feet on solid, strong rock."]}, {"type": "story", "img": "images/book/aug-27-2.jpg", "alt": "Illustration: The person was so thankful and happy that Heavenly Father even put a brand-new song in his heart — a joyful so…", "text": ["The person was so thankful and happy that Heavenly Father even put a brand-new song in his heart — a joyful song of thanks.", "When we feel stuck or sad, we can call out to Heavenly Father, and He will help lift us up. And when He does, our hearts fill up with a happy new song of thankfulness."]}, {"type": "moment", "img": "images/book/aug-27-3.jpg", "alt": "Illustration: Willow fits tonight because she knows the joy of being lifted up.", "text": ["Willow fits tonight because she knows the joy of being lifted up. In Willow’s world today: Willow felt stuck and grumpy because she couldn’t build her puzzle. She was about to cry when Grandpa gently helped her find the right piece. Suddenly her heart felt light and happy, and she hummed a little tune. Just like Heavenly Father lifted the psalm-writer from the pit and gave him a new song, kind help turned Willow’s stuck feeling into joy."], "eyebrow": "Scripture Traveler of the Night", "heading": "Willow the Warm"}, {"type": "moment", "img": "images/book/aug-27-4.jpg", "alt": "Illustration: Let’s climb up out of the pit!", "text": ["Let’s climb up out of the pit! Reach your hands down low, then slowly lift up, up, up onto strong rock — you made it! Now sing a happy “la-la- la.” Can you climb up and sing your new song?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When you feel stuck or sad, you can call out to Heavenly Father — He will help lift you up and put a happy song in your heart! Who can you call on for help when you feel stuck?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/aug-27-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“How did the person feel before Heavenly Father helped him?”", "“What did Heavenly Father put in his heart?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/aug-27-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b8-w4-n7', 8, 'Week 4 · Night 7', 'Sing with All Your Heart', 'Psalms 1–2; 8; 19–33; 40; 46', '[{"type": "cover", "img": "images/book/aug-28-0.jpg", "alt": "Cover illustration for “Sing with All Your Heart”"}, {"type": "story", "img": "images/book/aug-28-1.jpg", "alt": "Illustration: The Psalms are full of happy songs, and one of them says, “Sing to Heavenly Father a joyful song!", "text": ["The Psalms are full of happy songs, and one of them says, “Sing to Heavenly Father a joyful song! Play music and praise Him!”", "Long ago, people praised Heavenly Father with harps and horns and all kinds of joyful sounds. They sang because their hearts were so full of love for Him."]}, {"type": "story", "img": "images/book/aug-28-2.jpg", "alt": "Illustration: The song reminds us that Heavenly Father made the whole big world, and His love fills the earth from top to bo…", "text": ["The song reminds us that Heavenly Father made the whole big world, and His love fills the earth from top to bottom.", "We can praise Heavenly Father too — by singing, humming, clapping, or just saying “thank You” with a happy heart. He loves to hear our joyful praise!"]}, {"type": "moment", "img": "images/book/aug-28-3.jpg", "alt": "Illustration: Scout fits tonight because Scout loves to share joyful praise.", "text": ["Scout fits tonight because Scout loves to share joyful praise. In Scout’s world today: Scout woke up to a bright, sunny morning and felt so happy that a little song just bubbled right out. Scout marched around singing, “Thank you, Heavenly Father, for this beautiful day!” and soon the whole family was singing along. Just like the psalm invites us to sing joyfully, Scout discovered that praising Heavenly Father makes joy spread everywhere."], "eyebrow": "Scripture Traveler of the Night", "heading": "Scout the Seeker"}, {"type": "moment", "img": "images/book/aug-28-4.jpg", "alt": "Illustration: Let’s make joyful music!", "text": ["Let’s make joyful music! Clap a happy beat — clap, clap, clap — then pretend to strum a harp or toot a horn: “toot-toot!” Now sing “I love Heavenly Father!” Can you make a joyful, praising sound?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["You can praise Heavenly Father with singing, clapping, or a happy “thank You” — He loves your joyful praise! What is a happy way you like to praise Heavenly Father?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/aug-28-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“How did people praise Heavenly Father in the song?”", "“What fills the whole earth, according to the song?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/aug-28-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b8-w5-n1', 8, 'Week 5 · Night 1', 'A Clean, New Heart', 'Psalms 49–51; 61–66; 69–72; 77–78; 85–86', '[{"type": "cover", "img": "images/book/aug-29-0.jpg", "alt": "Cover illustration for “A Clean, New Heart”"}, {"type": "story", "img": "images/book/aug-29-1.jpg", "alt": "Illustration: Sometimes we make mistakes or do things we know are wrong, and our hearts feel yucky and sad inside.", "text": ["Sometimes we make mistakes or do things we know are wrong, and our hearts feel yucky and sad inside. One of the Psalms is a gentle song about that.", "The person sang, “Heavenly Father, please make my heart clean and new again.” He knew Heavenly Father could help him feel better."]}, {"type": "story", "img": "images/book/aug-29-2.jpg", "alt": "Illustration: When we say we’re sorry and try to do better, Heavenly Father washes our hearts clean — just like warm water w…", "text": ["When we say we’re sorry and try to do better, Heavenly Father washes our hearts clean — just like warm water washes away the mud.", "Heavenly Father always forgives us when we come to Him. He gives us a fresh, clean heart and a happy new start. Isn’t that a wonderful gift?"]}, {"type": "moment", "img": "images/book/aug-29-3.jpg", "alt": "Illustration: Willow the Warm", "eyebrow": "Scripture Traveler of the Night", "heading": "Willow the Warm"}, {"type": "moment", "img": "images/book/aug-29-4.jpg", "alt": "Illustration: Let’s wash our hearts clean!", "text": ["Let’s wash our hearts clean! Rub your hands together like you’re washing with warm, soapy water — scrub, scrub. Now shake them out and feel fresh and new! Can you show me your clean, happy heart?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When you make a mistake, you can say sorry, and Heavenly Father will make your heart clean and new again! He always forgives you. What helps you feel better after you’ve done something wrong?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/aug-29-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did the person ask Heavenly Father to make new?”", "“What does Heavenly Father do when we say we’re sorry?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/aug-29-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b8-w5-n2', 8, 'Week 5 · Night 2', 'My Strong, Safe Rock', 'Psalms 49–51; 61–66; 69–72; 77–78; 85–86', '[{"type": "cover", "img": "images/book/aug-30-0.jpg", "alt": "Cover illustration for “My Strong, Safe Rock”"}, {"type": "story", "img": "images/book/aug-30-1.jpg", "alt": "Illustration: When we feel small or shaky, it helps to stand on something big and strong.", "text": ["When we feel small or shaky, it helps to stand on something big and strong. One of the Psalms calls Heavenly Father a great big Rock.", "“Heavenly Father is my Rock,” the person sang. “He is my safe, high place. I will trust in Him.”"]}, {"type": "story", "img": "images/book/aug-30-2.jpg", "alt": "Illustration: A rock doesn’t wobble or tip over.", "text": ["A rock doesn’t wobble or tip over. It stays strong and steady, no matter what. That’s just like Heavenly Father.", "When we feel weak or worried, we can lean on Heavenly Father, our strong and steady Rock. He will always hold us up. We are safe when we trust in Him."]}, {"type": "moment", "img": "images/book/aug-30-3.jpg", "alt": "Illustration: Beau fits tonight because he leans on Heavenly Father when he feels weak.", "text": ["Beau fits tonight because he leans on Heavenly Father when he feels weak. In Beau’s world today: it was Beau’s first day at a new preschool, and his legs felt wobbly and unsure. He took a deep breath and remembered Heavenly Father was his strong Rock, holding him up. He felt steadier, walked in, and even made a new friend. Just like the psalm-writer trusted Heavenly Father as his Rock, Beau leaned on Him and found his strong."], "eyebrow": "Scripture Traveler of the Night", "heading": "Beau the Brave"}, {"type": "moment", "img": "images/book/aug-30-4.jpg", "alt": "Illustration: Let’s be strong and steady like a rock!", "text": ["Let’s be strong and steady like a rock! Stand with your feet apart, make your body big and firm, and don’t wobble. Now say, “Heavenly Father is my Rock!” Can you stand as steady as a strong rock?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When you feel weak or wobbly, you can lean on Heavenly Father — your strong, safe Rock! He will always hold you up. When could you lean on Heavenly Father to feel steady?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/aug-30-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did the person call Heavenly Father?”", "“How is Heavenly Father like a strong rock?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/aug-30-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b8-w5-n3', 8, 'Week 5 · Night 3', 'Thinking of Heavenly Father at Night', 'Psalms 49–51; 61–66; 69–72; 77–78; 85–86', '[{"type": "cover", "img": "images/book/aug-31-0.jpg", "alt": "Cover illustration for “Thinking of Heavenly Father at Night”"}, {"type": "story", "img": "images/book/aug-31-1.jpg", "alt": "Illustration: One song-writer loved Heavenly Father so much that he thought about Him all the time — even when he was lying…", "text": ["One song-writer loved Heavenly Father so much that he thought about Him all the time — even when he was lying in bed at night.", "“I think about You while I rest,” he sang. “My heart wants to be close to You, like a thirsty person wants a cool drink of water.”"]}, {"type": "story", "img": "images/book/aug-31-2.jpg", "alt": "Illustration: When the world got quiet and still, he would remember all the good things Heavenly Father had done, and it mad…", "text": ["When the world got quiet and still, he would remember all the good things Heavenly Father had done, and it made his heart feel happy and full. Bedtime is a wonderful time to think about Heavenly Father. As we snuggle down to sleep, we can remember His love and feel Him close, all through the peaceful night."]}, {"type": "moment", "img": "images/book/aug-31-3.jpg", "alt": "Illustration: Wren the Wonderer", "eyebrow": "Scripture Traveler of the Night", "heading": "Wren the Wonderer"}, {"type": "moment", "img": "images/book/aug-31-4.jpg", "alt": "Illustration: Let’s get cozy and think of Heavenly Father.", "text": ["Let’s get cozy and think of Heavenly Father. Rest your head on your hands like a little pillow and close your eyes softly. Now think one happy thought about Heavenly Father. Can you show me your sleepy, peaceful face?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Bedtime is a wonderful time to think about Heavenly Father and feel Him close! As you fall asleep, you can remember His love. What happy thought about Heavenly Father will you take to sleep?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/aug-31-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“When did the person think about Heavenly Father?”", "“What did he remember that made his heart full?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/aug-31-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b8-w5-n4', 8, 'Week 5 · Night 4', 'Come and Hear!', 'Psalms 49–51; 61–66; 69–72; 77–78; 85–86', '[{"type": "cover", "img": "images/book/aug-30-0.jpg", "alt": "Cover illustration for “Come and Hear!”"}, {"type": "story", "img": "images/book/aug-32-1.jpg", "alt": "Illustration: When something wonderful happens, we can hardly wait to tell everybody about it!", "text": ["When something wonderful happens, we can hardly wait to tell everybody about it! One of the Psalms is exactly like that.", "“Come and hear!” the person sang out. “Let me tell you all the wonderful things Heavenly Father has done!”"]}, {"type": "story", "img": "images/book/aug-32-2.jpg", "alt": "Illustration: He was so thankful and excited that he wanted to share Heavenly Father’s goodness with every single person he…", "text": ["He was so thankful and excited that he wanted to share Heavenly Father’s goodness with every single person he could find.", "When Heavenly Father does good things for us, we can share the happy news too — with our family, our friends, and everyone we love. Telling about Heavenly Father’s goodness makes our joy grow bigger."]}, {"type": "moment", "img": "images/book/aug-32-3.jpg", "alt": "Illustration: Scout fits tonight because Scout loves sharing good news.", "text": ["Scout fits tonight because Scout loves sharing good news. In Scout’s world today: Scout prayed to find a lost stuffed bunny, and later that day, there it was under the bed! Scout was so happy and grateful that he ran to tell the whole family, “Heavenly Father helped me find it!” Just like the psalm-writer said, “Come and hear,” Scout shared how Heavenly Father had helped, and everyone’s hearts felt glad."], "eyebrow": "Scripture Traveler of the Night", "heading": "Scout the Seeker"}, {"type": "moment", "img": "images/book/aug-32-4.jpg", "alt": "Illustration: Let’s share the good news!", "text": ["Let’s share the good news! Cup your hands around your mouth and call out, “Come and hear! Heavenly Father is so good!” Now wave everyone over to listen. Can you share the happy news nice and loud?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When Heavenly Father does good things for you, you can share the happy news with everyone you love — it makes your joy grow! What good thing could you tell your family about Heavenly Father?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/aug-32-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did the person want everyone to come and do?”", "“What was he so excited to tell about?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/aug-32-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b8-w5-n5', 8, 'Week 5 · Night 5', 'My Hope Since I Was Little', 'Psalms 49–51; 61–66; 69–72; 77–78; 85–86', '[{"type": "cover", "img": "images/book/aug-33-0.jpg", "alt": "Cover illustration for “My Hope Since I Was Little”"}, {"type": "story", "img": "images/book/aug-33-1.jpg", "alt": "Illustration: One song-writer had grown old, and he looked back on his whole long life.", "text": ["One song-writer had grown old, and he looked back on his whole long life. He remembered that Heavenly Father had been with him the entire time.", "“Heavenly Father, You have been my hope since I was very young,” he sang. “You have taken care of me all my life.”"]}, {"type": "story", "img": "images/book/aug-33-2.jpg", "alt": "Illustration: From the time he was a tiny child until his hair turned gray, Heavenly Father had never once left his side.", "text": ["From the time he was a tiny child until his hair turned gray, Heavenly Father had never once left his side. Heavenly Father has been taking care of you since before you were even born — and He always will. He is with us when we’re little, when we’re big, and every day in between. His love never stops."]}, {"type": "moment", "img": "images/book/aug-33-3.jpg", "alt": "Illustration: Willow fits tonight because she feels Heavenly Father’s gentle, lifelong love.", "text": ["Willow fits tonight because she feels Heavenly Father’s gentle, lifelong love. In Willow’s world today: Willow looked at baby pictures and giggled at how tiny she used to be. Mom said, “Heavenly Father has loved you and watched over you this whole time.” Willow’s heart felt warm and safe, knowing she was never once alone. Just like the psalm-writer trusted Heavenly Father his whole life, Willow felt His love from the very beginning until now."], "eyebrow": "Scripture Traveler of the Night", "heading": "Willow the Warm"}, {"type": "moment", "img": "images/book/aug-33-4.jpg", "alt": "Illustration: Let’s show how we grow with Heavenly Father!", "text": ["Let’s show how we grow with Heavenly Father! Crouch down tiny like a little baby, then s-l-o-w-l-y grow up, up, up, standing tall and big. Heavenly Father is with us the whole time! Can you grow from tiny to tall?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Heavenly Father has been taking care of you since before you were born — and He always will! He is with you when you’re little and when you’re big. How does it feel to know Heavenly Father has always been with you?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/aug-33-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“How long had Heavenly Father been the person’s hope?”", "“When does Heavenly Father take care of us?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/aug-33-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b8-w5-n6', 8, 'Week 5 · Night 6', 'Tell the Children', 'Psalms 49–51; 61–66; 69–72; 77–78; 85–86', '[{"type": "cover", "img": "images/book/aug-34-0.jpg", "alt": "Cover illustration for “Tell the Children”"}, {"type": "story", "img": "images/book/aug-34-1.jpg", "alt": "Illustration: One of the Psalms has a very special job for grown-ups and children alike.", "text": ["One of the Psalms has a very special job for grown-ups and children alike. It says to remember the wonderful things Heavenly Father has done — and to tell them to the children.", "“We will not hide these things from our little ones,” the song says. “We will tell the children about Heavenly Father’s love and His mighty works.”"]}, {"type": "story", "img": "images/book/aug-34-2.jpg", "alt": "Illustration: That way, children grow up knowing Heavenly Father.", "text": ["That way, children grow up knowing Heavenly Father. And when they grow up, they tell THEIR children too. The happy stories get passed down, on and on.", "Every time you hear a story about Heavenly Father, you become part of that beautiful chain of love. And one day, you can tell these stories to others too!"]}, {"type": "moment", "img": "images/book/aug-34-3.jpg", "alt": "Illustration: Wren the Wonderer", "eyebrow": "Scripture Traveler of the Night", "heading": "Wren the Wonderer"}, {"type": "moment", "img": "images/book/aug-34-4.jpg", "alt": "Illustration: Let’s pass the story along!", "text": ["Let’s pass the story along! Cup your hand to your ear and “listen” to a story, then turn and pretend to tell the happy story to someone else — “Let me tell YOU!” Can you listen, then pass it on?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Every time you hear a story about Heavenly Father, you become part of a beautiful chain of love — and one day you can tell these stories too! Who could you tell a story about Heavenly Father?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/aug-34-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What does the song say to tell the children about?”", "“What happens when children grow up and have their own little ones?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/aug-34-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b8-w5-n7', 8, 'Week 5 · Night 7', 'Heavenly Father Is So Good', 'Psalms 49–51; 61–66; 69–72; 77–78; 85–86', '[{"type": "cover", "img": "images/book/aug-33-0.jpg", "alt": "Cover illustration for “Heavenly Father Is So Good”"}, {"type": "story", "img": "images/book/aug-35-1.jpg", "alt": "Illustration: The very last song this month is full of love and praise.", "text": ["The very last song this month is full of love and praise. The person sang about how kind and good Heavenly Father is.", "“Heavenly Father, You are so good and forgiving,” he sang. “You are full of love for everyone who calls on You. Please teach me Your way.”"]}, {"type": "story", "img": "images/book/aug-35-2.jpg", "alt": "Illustration: He wanted to learn to be more like Heavenly Father — kind, patient, and full of love.", "text": ["He wanted to learn to be more like Heavenly Father — kind, patient, and full of love. So he asked Heavenly Father to help him.", "Heavenly Father is good, and He helps us become good too. When we ask Him to teach us His ways, He fills our hearts with love and helps us grow a little more like Him each day."]}, {"type": "moment", "img": "images/book/aug-35-3.jpg", "alt": "Illustration: Scout the Seeker", "eyebrow": "Scripture Traveler of the Night", "heading": "Scout the Seeker"}, {"type": "moment", "img": "images/book/aug-35-4.jpg", "alt": "Illustration: Let’s praise good Heavenly Father!", "text": ["Let’s praise good Heavenly Father! Put both hands over your heart, then open them wide like you’re giving all your love up to Him. Now say, “Heavenly Father, You are so good!” Can you show Him your biggest love?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Heavenly Father is so good, and when you ask Him to teach you His ways, He helps you grow good and loving too — a little more each day! What good thing can you ask Heavenly Father to help you with?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/aug-35-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did the person say Heavenly Father is full of?”", "“What did he ask Heavenly Father to teach him?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/aug-35-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

-- ---------------------------------------------------------------------
--  Wonderful Is His Way
-- ---------------------------------------------------------------------
insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w1-n1', 9, 'Week 1 · Night 1', 'Bless the Lord, O My Soul', 'Psalm 103', '[{"type": "cover", "img": "images/book/sep-01-0.jpg", "alt": "Cover illustration for “Bless the Lord, O My Soul”"}, {"type": "story", "img": "images/book/sep-01-1.jpg", "alt": "Illustration: Long ago, a man named David wanted to thank Heavenly Father with his whole heart.", "text": ["Long ago, a man named David wanted to thank Heavenly Father with his whole heart. So he sang a happy song: “Bless Heavenly Father, O my soul! I will remember all the good things He does!”", "David remembered how kind Heavenly Father is. He forgives us when we’re sorry. He helps us feel better when we’re sad. He fills our lives with good things, like a warm hug that never ends.", "“Heavenly Father loves us like the very best daddy,” David sang. “As high as the sky is above the earth, that’s how big His love is for us!”"]}, {"type": "story", "img": "images/book/sep-01-2.jpg", "alt": "Illustration: And when we say we’re sorry, Heavenly Father takes our mistakes far, far away — as far as the sunrise is from…", "text": ["And when we say we’re sorry, Heavenly Father takes our mistakes far, far away — as far as the sunrise is from the sunset. He remembers them no more.", "Heavenly Father’s love is so big and so gentle. No matter what, He loves you with His whole heart, all the way to the sky and back."]}, {"type": "moment", "img": "images/book/sep-01-3.jpg", "alt": "Illustration: Willow fits tonight because she feels how gentle and forgiving love can be.", "text": ["Willow fits tonight because she feels how gentle and forgiving love can be. In Willow’s world today: Willow spilled her juice all over the floor and felt scared she was in trouble. But Mom just gave her a hug and said, “It’s okay — let’s clean it up together.” Willow’s worried heart melted into a happy one. Just like David sang about Heavenly Father’s kind, forgiving love, Willow felt how big and gentle that love can be."], "eyebrow": "Scripture Traveler of the Night", "heading": "Willow the Warm"}, {"type": "moment", "img": "images/book/sep-01-4.jpg", "alt": "Illustration: Let’s bless Heavenly Father like David!", "text": ["Let’s bless Heavenly Father like David! Wrap your arms around yourself in a big hug, then stretch them wa-a-ay up high to the sky. His love is bigger than we can even reach! Can you show me how high His love goes?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Heavenly Father loves you higher than the sky and takes your mistakes far away when you’re sorry! You are so loved, sweet one. What is one good thing Heavenly Father has done for you that you can thank Him for?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-01-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did David want to remember about Heavenly Father?”", "“How big is Heavenly Father’s love for us?”", "“What is one good thing Heavenly Father has done for you that you can thank Him for?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-01-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w1-n2', 9, 'Week 1 · Night 2', 'He Hears My Voice', 'Psalm 116', '[{"type": "cover", "img": "images/book/sep-02-0.jpg", "alt": "Cover illustration for “He Hears My Voice”"}, {"type": "story", "img": "images/book/sep-02-1.jpg", "alt": "Illustration: There once was a person who felt sad and afraid.", "text": ["There once was a person who felt sad and afraid. Big troubles were all around, and he didn’t know what to do. So he did the best thing of all — he called out to Heavenly Father.", "“Please help me, Heavenly Father!” he prayed. And guess what? Heavenly Father heard every single word.", "Heavenly Father listened close and helped him. His sadness turned to gladness, and his heart felt calm again. “I love Heavenly Father,” he sang, “because He hears me when I call!”"]}, {"type": "story", "img": "images/book/sep-02-2.jpg", "alt": "Illustration: The person was so thankful.", "text": ["The person was so thankful. He decided he would keep praying and keep loving Heavenly Father for the rest of his life.", "Whenever you talk to Heavenly Father, He hears you too — every whisper, every prayer. You are never, ever alone."]}, {"type": "moment", "img": "images/book/sep-02-3.jpg", "alt": "Illustration: Beau fits tonight because he trusts Heavenly Father to hear him when things feel hard.", "text": ["Beau fits tonight because he trusts Heavenly Father to hear him when things feel hard. In Beau’s world today: Beau got lost from Dad for a scary minute at the busy store. His heart pounded, but he remembered to whisper, “Heavenly Father, help me,” and stay put. Soon Dad came around the corner! “Heavenly Father heard me,” Beau said. Just like the person who called out and was heard, Beau learned that Heavenly Father listens the moment we call."], "eyebrow": "Scripture Traveler of the Night", "heading": "Beau the Brave"}, {"type": "moment", "img": "images/book/sep-02-4.jpg", "alt": "Illustration: Let’s call out to Heavenly Father!", "text": ["Let’s call out to Heavenly Father! Cup your hands around your mouth and softly call, “I love You, Heavenly Father!” Now put your hand on your ear — He always hears. Can you show me your best listening ears?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Whenever you talk to Heavenly Father, He hears every word — even a tiny whisper! He loves to listen to you. What would you like to tell Heavenly Father tonight?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-02-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did the person do when he felt sad and afraid?”", "“What did Heavenly Father do when he called?”", "“What would you like to tell Heavenly Father tonight?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-02-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w1-n3', 9, 'Week 1 · Night 3', 'This Is the Day!', 'Psalm 118', '[{"type": "cover", "img": "images/book/sep-03-0.jpg", "alt": "Cover illustration for “This Is the Day!”"}, {"type": "story", "img": "images/book/sep-03-1.jpg", "alt": "Illustration: One morning, a happy song-writer woke up and looked at the brand-new day.", "text": ["One morning, a happy song-writer woke up and looked at the brand-new day. The sun was shining, the birds were singing, and his heart felt full of joy.", "“This is the day that Heavenly Father made!” he sang. “I will be happy and glad in it!”", "He knew that every single day is a gift from Heavenly Father. Some days are big and exciting; some days are quiet and small. But every day is made by Him."]}, {"type": "story", "img": "images/book/sep-03-2.jpg", "alt": "Illustration: “Thank You, Heavenly Father, for You are so good!” the person sang.", "text": ["“Thank You, Heavenly Father, for You are so good!” the person sang. “Your love lasts forever and ever!”", "When you wake up tomorrow, you can remember: this new day is a gift, made just for you by Heavenly Father who loves you."]}, {"type": "moment", "img": "images/book/sep-03-3.jpg", "alt": "Illustration: Scout fits tonight because Scout finds something wonderful in every new day.", "text": ["Scout fits tonight because Scout finds something wonderful in every new day. In Scout’s world today: it was a plain, rainy morning with no big plans. But Scout said, “I wonder what good things today will bring?” and went looking — and found a puddle to splash, a rainbow after lunch, and a cozy story with Grandma. Just like the song-writer who was glad for the day Heavenly Father made, Scout discovered that every day holds a gift when we look for it."], "eyebrow": "Scripture Traveler of the Night", "heading": "Scout the Seeker"}, {"type": "moment", "img": "images/book/sep-03-4.jpg", "alt": "Illustration: Let’s welcome the new day!", "text": ["Let’s welcome the new day! Stretch your arms up in a big yawn, then open them wide like the morning sun coming up. “This is the day Heavenly Father made!” Can you show me your happiest good-morning stretch?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Every new day is a gift made just for you by Heavenly Father! You can wake up glad and look for the good in it. What is one thing you’re excited to do tomorrow?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-03-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“Who made this brand-new day?”", "“What did the song-writer say he would be?”", "“What is one thing you’re excited to do tomorrow?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-03-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w1-n4', 9, 'Week 1 · Night 4', 'A Lamp for My Feet', 'Psalm 119', '[{"type": "cover", "img": "images/book/sep-04-0.jpg", "alt": "Cover illustration for “A Lamp for My Feet”"}, {"type": "story", "img": "images/book/sep-04-1.jpg", "alt": "Illustration: The longest song in all the Psalms is about something very special: Heavenly Father’s words, the scriptures.", "text": ["The longest song in all the Psalms is about something very special: Heavenly Father’s words, the scriptures. The song-writer loved them so much!", "“Your words are like a lamp for my feet,” he sang, “and a bright light for my path.” A lamp helps us see where to walk in the dark.", "When we don’t know what to do, Heavenly Father’s words show us the way — just like a little light helps us take the next safe step."]}, {"type": "story", "img": "images/book/sep-04-2.jpg", "alt": "Illustration: The song-writer even said, “I keep Your words safe inside my heart.” He learned them and remembered them, like…", "text": ["The song-writer even said, “I keep Your words safe inside my heart.” He learned them and remembered them, like hiding a treasure where it can never be lost.", "You can keep Heavenly Father’s words in your heart too. When you listen to scripture stories, you’re filling your heart with a light that helps you always know the way."]}, {"type": "moment", "img": "images/book/sep-04-3.jpg", "alt": "Illustration: Wren fits tonight because she treasures Heavenly Father’s words in her heart.", "text": ["Wren fits tonight because she treasures Heavenly Father’s words in her heart. In Wren’s world today: Wren couldn’t decide whether to tattle or be kind when her friend made a little mistake. Then she remembered a scripture story about being gentle, and it lit up the right thing to do — like a little lamp. She chose kindness. Just like the song-writer whose path was lit by Heavenly Father’s words, Wren found that the scriptures show us the way."], "eyebrow": "Scripture Traveler of the Night", "heading": "Wren the Wonderer"}, {"type": "moment", "img": "images/book/sep-04-4.jpg", "alt": "Illustration: Let’s light our little lamp!", "text": ["Let’s light our little lamp! Hold your hands like you’re carrying a lantern out in front of you, and take slow, careful steps. The light shows the way! Can you walk your safe little path with your lamp?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Heavenly Father’s words are like a little lamp that shows you the way — and you can keep them safe in your heart! What is one thing scripture stories have taught you to do?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-04-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did the song-writer say Heavenly Father’s words were like?”", "“Where did he keep Heavenly Father’s words safe?”", "“What is one thing scripture stories have taught you to do?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-04-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w1-n5', 9, 'Week 1 · Night 5', 'You Know Me!', 'Psalm 139', '[{"type": "cover", "img": "images/book/sep-05-0.jpg", "alt": "Cover illustration for “You Know Me!”"}, {"type": "story", "img": "images/book/sep-05-1.jpg", "alt": "Illustration: One song-writer thought about something amazing: Heavenly Father knows everything about him!", "text": ["One song-writer thought about something amazing: Heavenly Father knows everything about him! He sang a wondering song about it.", "“Heavenly Father, You know when I sit down and when I stand up. You know my thoughts and every word before I say it. You are always with me!”", "He knew that wherever he went — up high or far away — Heavenly Father was right there, watching over him with love."]}, {"type": "story", "img": "images/book/sep-05-2.jpg", "alt": "Illustration: “You made me,” he sang, “and I am wonderfully made!” Every part of us — our fingers, our smiles, our giggles…", "text": ["“You made me,” he sang, “and I am wonderfully made!” Every part of us — our fingers, our smiles, our giggles — was carefully made by Heavenly Father.", "Isn’t that wonderful? Heavenly Father knows you all the way through, and He made you just right. You are precious and special to Him."]}, {"type": "moment", "img": "images/book/sep-05-3.jpg", "alt": "Illustration: Wren fits tonight because she loves to wonder at how amazing she’s made.", "text": ["Wren fits tonight because she loves to wonder at how amazing she’s made. In Wren’s world today: Wren looked at her own hand and wondered, “How did Heavenly Father make my fingers wiggle and my heart go thump?” She felt so special knowing He made every part of her on purpose. Just like the song-writer who marveled that he was wonderfully made, Wren discovered that Heavenly Father made her just right."], "eyebrow": "Scripture Traveler of the Night", "heading": "Wren the Wonderer"}, {"type": "moment", "img": "images/book/sep-05-4.jpg", "alt": "Illustration: Let’s show how well Heavenly Father knows us!", "text": ["Let’s show how well Heavenly Father knows us! Wiggle your fingers (He made those!), pat your head (He knows your thoughts!), and point to your smile (He made that too!). Can you show me all the wonderful parts He made?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Heavenly Father knows everything about you and made you wonderfully — there is no one else exactly like you! How does it feel to know Heavenly Father made you just right?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-05-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What does Heavenly Father know about us?”", "“How did Heavenly Father make each of us?”", "“How does it feel to know Heavenly Father made you just right?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-05-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w1-n6', 9, 'Week 1 · Night 6', 'Children Are a Gift', 'Psalm 127', '[{"type": "cover", "img": "images/book/sep-06-0.jpg", "alt": "Cover illustration for “Children Are a Gift”"}, {"type": "story", "img": "images/book/sep-06-1.jpg", "alt": "Illustration: Heavenly Father loves families very much.", "text": ["Heavenly Father loves families very much. One of the Psalms is a happy song all about home and children.", "“Unless Heavenly Father helps build the house, the builders work for nothing,” the song says. That means Heavenly Father is the one who helps our family and home grow strong and happy.", "Then the song says something sweet: “Children are a gift from Heavenly Father!” Every child — including YOU — is a special present He gives to a family."]}, {"type": "story", "img": "images/book/sep-06-2.jpg", "alt": "Illustration: The song paints a happy picture: a mom and dad and their little ones gathered close, like young plants growing…", "text": ["The song paints a happy picture: a mom and dad and their little ones gathered close, like young plants growing round a table full of love.", "Your family is a gift, and you are a gift too! Heavenly Father helps your home be a place of love, where you are treasured every single day."]}, {"type": "moment", "img": "images/book/sep-06-3.jpg", "alt": "Illustration: Willow fits tonight because she cherishes the people in her home.", "text": ["Willow fits tonight because she cherishes the people in her home. In Willow’s world today: at dinner, Willow looked around at everyone laughing together and felt her heart go warm. “I’m so glad you’re my family,” she said, and gave her little brother a hug — even though he’d been silly all day. Just like the song about children being a gift from Heavenly Father, Willow felt how precious her family is."], "eyebrow": "Scripture Traveler of the Night", "heading": "Willow the Warm"}, {"type": "moment", "img": "images/book/sep-06-4.jpg", "alt": "Illustration: Let’s make a cozy family circle!", "text": ["Let’s make a cozy family circle! Reach your arms out wide like they’re wrapping all around your family, then pull them into a big squeeze-hug. Home is full of love! Can you give a great big family hug?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Your family is a gift from Heavenly Father — and so are you! He helps your home be full of love. Who in your family are you thankful for tonight?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-06-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“Who helps build a happy home?”", "“What does the song say children are?”", "“Who in your family are you thankful for tonight?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-06-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w1-n7', 9, 'Week 1 · Night 7', 'Let Everything Praise Him!', 'Psalms 148–150', '[{"type": "cover", "img": "images/book/sep-07-0.jpg", "alt": "Cover illustration for “Let Everything Praise Him!”"}, {"type": "story", "img": "images/book/sep-07-1.jpg", "alt": "Illustration: The very last songs in the Psalms are the happiest of all!", "text": ["The very last songs in the Psalms are the happiest of all! They shout, “Praise Heavenly Father!” over and over with joy.", "The song calls to everyone and everything: “Sun and moon, praise Him! Shining stars, praise Him! Mountains and trees, praise Him!”", "Even the animals join in! “Whales in the sea, birds in the sky, little bugs and big lions — praise Heavenly Father!” All of creation says thank You to the One who made them."]}, {"type": "story", "img": "images/book/sep-07-2.jpg", "alt": "Illustration: And then the very last line: “Let EVERYTHING that breathes praise Heavenly Father!” That means you too — with…", "text": ["And then the very last line: “Let EVERYTHING that breathes praise Heavenly Father!” That means you too — with singing, clapping, and a happy, thankful heart.", "The whole world is like one big, joyful song to Heavenly Father. And you get to be part of it! Isn’t that wonderful?"]}, {"type": "moment", "img": "images/book/sep-07-3.jpg", "alt": "Illustration: Scout fits tonight because Scout loves to notice everything praising Heavenly Father.", "text": ["Scout fits tonight because Scout loves to notice everything praising Heavenly Father. In Scout’s world today: on a walk, Scout listened to the birds chirping, the wind whooshing the trees, and a puppy’s happy bark. “It’s like the whole world is singing to Heavenly Father!” Scout said, and started humming a thank-You song too. Just like the psalm that calls everything to praise Him, Scout discovered that all creation — and Scout — can join the joyful song."], "eyebrow": "Scripture Traveler of the Night", "heading": "Scout the Seeker"}, {"type": "moment", "img": "images/book/sep-07-4.jpg", "alt": "Illustration: Let’s join the whole world’s song!", "text": ["Let’s join the whole world’s song! Clap your hands, stomp your feet, and cheer, “Praise Heavenly Father!” Now take a big breath — you have breath, so you can praise Him too! Can you make your most joyful praising sound?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Everything that breathes can praise Heavenly Father — and that means YOU! You can praise Him with singing, clapping, and a thankful heart. What is your favorite happy way to praise Heavenly Father?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-07-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“Who does the song say should praise Heavenly Father?”", "“Since you can breathe, what can you do?”", "“What is your favorite happy way to praise Heavenly Father?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-07-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w2-n1', 9, 'Week 2 · Night 1', 'Trust Him to Lead the Way', 'Proverbs 3', '[{"type": "cover", "img": "images/book/sep-08-0.jpg", "alt": "Cover illustration for “Trust Him to Lead the Way”"}, {"type": "story", "img": "images/book/sep-08-1.jpg", "alt": "Illustration: A wise man named Solomon wrote down lots of good advice to help us live happy lives.", "text": ["A wise man named Solomon wrote down lots of good advice to help us live happy lives. We call his sayings Proverbs. One of the very best is about trusting Heavenly Father.", "“Trust in Heavenly Father with ALL your heart,” Solomon wrote. “Don’t try to figure everything out by yourself.”", "Sometimes we don’t know which way to go or what to do. That’s okay! Solomon said, “Ask Heavenly Father, and He will show you the right path.”"]}, {"type": "story", "img": "images/book/sep-08-2.jpg", "alt": "Illustration: It’s like walking with someone who knows the way.", "text": ["It’s like walking with someone who knows the way. We don’t have to see the whole road — we just hold His hand and take the next step.", "When you trust Heavenly Father with your whole heart, He leads you on good paths, step by step. You can trust Him, even when you can’t see what’s ahead."]}, {"type": "moment", "img": "images/book/sep-08-3.jpg", "alt": "Illustration: Beau fits tonight because he trusts Heavenly Father even when he can’t see the whole way.", "text": ["Beau fits tonight because he trusts Heavenly Father even when he can’t see the whole way. In Beau’s world today: Beau’s family went on a hike, and the trail wound up a hill where Beau couldn’t see the top. His legs felt unsure. But Dad said, “Just take the next step — I know the way.” Beau trusted and kept going, and the view at the top was amazing! Just like Solomon said to trust Heavenly Father to direct our paths, Beau learned to trust the One who knows the way."], "eyebrow": "Scripture Traveler of the Night", "heading": "Beau the Brave"}, {"type": "moment", "img": "images/book/sep-08-4.jpg", "alt": "Illustration: Let’s follow the leader!", "text": ["Let’s follow the leader! Hold out your hand like you’re holding Heavenly Father’s, and take slow, trusting steps forward. He knows the way! Can you walk your path, trusting your guide?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When you don’t know which way to go, you can trust Heavenly Father with your whole heart — He will lead you, step by step! What is something you can trust Heavenly Father to help you with?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-08-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“How much should we trust Heavenly Father?”", "“What does Heavenly Father do when we trust Him?”", "“What is something you can trust Heavenly Father to help you with?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-08-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w2-n2', 9, 'Week 2 · Night 2', 'Wisdom, a Hidden Treasure', 'Proverbs 2', '[{"type": "cover", "img": "images/book/sep-09-0.jpg", "alt": "Cover illustration for “Wisdom, a Hidden Treasure”"}, {"type": "story", "img": "images/book/sep-09-1.jpg", "alt": "Illustration: Wise Solomon wanted everyone to have something wonderful called wisdom.", "text": ["Wise Solomon wanted everyone to have something wonderful called wisdom. Wisdom means knowing the good and right thing to do.", "“Look for wisdom like you’re searching for hidden treasure!” Solomon said. “Dig for it, hunt for it — it’s more precious than gold and shiny jewels!”", "How do we find this treasure? Solomon said to listen to Heavenly Father, and to listen to the wise grown-ups who love us, like our mom and dad."]}, {"type": "story", "img": "images/book/sep-09-2.jpg", "alt": "Illustration: “Pay attention, my child,” he wrote.", "text": ["“Pay attention, my child,” he wrote. “Keep my good words close, and you will grow wise and happy.”", "Every time you listen and learn, you’re finding a little more treasure. Heavenly Father loves to help you grow wise, one good lesson at a time."]}, {"type": "moment", "img": "images/book/sep-09-3.jpg", "alt": "Illustration: Scout fits tonight because Scout loves to search out good and wonderful things.", "text": ["Scout fits tonight because Scout loves to search out good and wonderful things. In Scout’s world today: Scout wanted to build the tallest sandcastle but didn’t know how. Instead of giving up, Scout asked Grandpa, who knew a clever trick — wet sand sticks better! Scout listened, tried it, and built a mighty castle. Just like Solomon said to hunt for wisdom like treasure, Scout discovered that listening to wise helpers is like finding gold."], "eyebrow": "Scripture Traveler of the Night", "heading": "Scout the Seeker"}, {"type": "moment", "img": "images/book/sep-09-4.jpg", "alt": "Illustration: Let’s hunt for treasure!", "text": ["Let’s hunt for treasure! Put your hand above your eyes and “search” all around, then dig-dig-dig with your hands and — “I found it!” — hold up the sparkly treasure of wisdom. Can you show me your excited treasure-hunting face?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Wisdom is a treasure worth hunting for — and you find it by listening to Heavenly Father and the wise people who love you! What is something wise you learned from a grown-up you love?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-09-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did Solomon say to look for like treasure?”", "“How do we find the treasure of wisdom?”", "“What is something wise you learned from a grown-up you love?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-03-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w2-n3', 9, 'Week 2 · Night 3', 'A Soft, Kind Answer', 'Proverbs 15', '[{"type": "cover", "img": "images/book/sep-10-0.jpg", "alt": "Cover illustration for “A Soft, Kind Answer”"}, {"type": "story", "img": "images/book/sep-10-1.jpg", "alt": "Illustration: Wise Solomon knew that the words we say are very powerful.", "text": ["Wise Solomon knew that the words we say are very powerful. They can make a heart happy or a heart hurt.", "“A soft, kind answer makes angry feelings go away,” Solomon taught. “But mean, grumpy words just make things worse.”", "Imagine two friends. One shouts, “You broke it!” — and everyone gets upset. But if that friend says softly, “It’s okay, let’s fix it together,” the mad feelings melt like ice in the sun."]}, {"type": "story", "img": "images/book/sep-10-2.jpg", "alt": "Illustration: Soft words are gentle words.", "text": ["Soft words are gentle words. Kind words are healing words. They help everyone feel calm and loved.", "Heavenly Father can help you choose soft, kind words — even when you feel a little grumpy. Gentle words make the whole world happier."]}, {"type": "moment", "img": "images/book/sep-10-3.jpg", "alt": "Illustration: Willow fits tonight because gentle words are her superpower.", "text": ["Willow fits tonight because gentle words are her superpower. In Willow’s world today: Willow’s brother knocked over her block tower and she felt her face go hot and mad. She almost yelled — but instead she took a breath and said softly, “That’s okay, will you help me build it again?” Her brother smiled and helped, and the mad feeling floated away. Just like Solomon taught that a soft answer turns anger away, Willow found that gentle words make peace."], "eyebrow": "Scripture Traveler of the Night", "heading": "Willow the Warm"}, {"type": "moment", "img": "images/book/sep-10-4.jpg", "alt": "Illustration: Let’s practice soft words!", "text": ["Let’s practice soft words! First, make a loud grumpy face and shake your fists — grr! Now take a slow breath, soften your face, and whisper, “It’s okay.” Can you feel how a soft answer calms us down?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When you feel grumpy, you can choose soft, kind words — and watch the angry feelings melt away! Gentle words make hearts happy. When could you use a soft answer this week?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-10-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What does a soft, kind answer do to angry feelings?”", "“What do mean, grumpy words do?”", "“When could you use a soft answer this week?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-10-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w2-n4', 9, 'Week 2 · Night 4', 'Loving, Helping Hands', 'Proverbs 31', '[{"type": "cover", "img": "images/book/sep-11-0.jpg", "alt": "Cover illustration for “Loving, Helping Hands”"}, {"type": "story", "img": "images/book/sep-11-1.jpg", "alt": "Illustration: Near the end of Proverbs is a beautiful song about a wonderful woman — a mom who loved her family with all her…", "text": ["Near the end of Proverbs is a beautiful song about a wonderful woman — a mom who loved her family with all her heart.", "She worked hard with happy hands. She made yummy food, cared for her home, and helped people who needed her.", "She was kind and wise. When she spoke, gentle and good words came out, and she wasn’t afraid of hard work or new days."]}, {"type": "story", "img": "images/book/sep-11-2.jpg", "alt": "Illustration: The best part?", "text": ["The best part? Her children loved her so much. “Her little ones stand up and call her blessed,” the song says. That means they were so thankful for her!", "Heavenly Father gives us loving people — moms, dads, grandmas, grandpas — who work hard to care for us. We can thank them, and love them, and help with our own two hands too."]}, {"type": "moment", "img": "images/book/sep-11-3.jpg", "alt": "Illustration: Willow fits tonight because she loves to care for others like the kind woman in the song.", "text": ["Willow fits tonight because she loves to care for others like the kind woman in the song. In Willow’s world today: Willow noticed Mom was tired after a long day. So Willow used her helping hands — she put her toys away without being asked and brought Mom a pretend cup of tea. Mom’s face lit up. “Thank you, my helper!” Just like the loving woman whose family called her blessed, Willow learned that caring hands make a home warm."], "eyebrow": "Scripture Traveler of the Night", "heading": "Willow the Warm"}, {"type": "moment", "img": "images/book/sep-11-4.jpg", "alt": "Illustration: Let’s use loving, helping hands!", "text": ["Let’s use loving, helping hands! Pretend to stir a pot, fold a blanket, and give a pat on the back. Now clap for the people who care for you! Can you show me how YOU could help with your hands tomorrow?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Heavenly Father gives you loving people who work hard to care for you — and you can thank them AND help with your own hands! Who could you thank and help tomorrow?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-11-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“How did the woman use her hands?”", "“What did her children call her?”", "“Who could you thank and help tomorrow?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-11-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w2-n5', 9, 'Week 2 · Night 5', 'A Time for Everything', 'Ecclesiastes 3', '[{"type": "cover", "img": "images/book/sep-12-0.jpg", "alt": "Cover illustration for “A Time for Everything”"}, {"type": "story", "img": "images/book/sep-12-1.jpg", "alt": "Illustration: A wise teacher once wrote a thoughtful book called Ecclesiastes.", "text": ["A wise teacher once wrote a thoughtful book called Ecclesiastes. In it, he shared a gentle truth: there is a right time for everything.", "“There’s a time to plant seeds and a time to pick the fruit,” he said. “A time to laugh and a time to cry. A time to hug and a time to rest.”", "Heavenly Father made the world with seasons and times. Winter comes, then spring. Morning comes, then night. Everything has its own special time."]}, {"type": "story", "img": "images/book/sep-12-2.jpg", "alt": "Illustration: Some days are for playing and giggling.", "text": ["Some days are for playing and giggling. Some days are for resting and being quiet. Some feelings come and go, and that’s okay — each one has its time.", "Heavenly Father is with us in every season and every time. We can trust Him whether we’re laughing or crying, busy or still. He holds all our times in His loving hands."]}, {"type": "moment", "img": "images/book/sep-12-3.jpg", "alt": "Illustration: Wren fits tonight because she thinks about the right time for things.", "text": ["Wren fits tonight because she thinks about the right time for things. In Wren’s world today: Wren wanted to play outside, but it was pouring rain. Instead of fussing, she wondered, “Maybe this is a time to stay cozy inside.” So she read books and built a fort, and when the sun came out later, it was the perfect time to splash in puddles. Just like the wise teacher said there’s a time for everything, Wren learned to trust each season’s time."], "eyebrow": "Scripture Traveler of the Night", "heading": "Wren the Wonderer"}, {"type": "moment", "img": "images/book/sep-12-4.jpg", "alt": "Illustration: Let’s move through the times!", "text": ["Let’s move through the times! Pretend to plant a tiny seed, then reach up like it’s growing tall. Now give a big laugh — “ha ha!” — then a slow, calm breath. Can you show me a time to jump and a time to be still?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["There’s a right time for everything — a time to play and a time to rest — and Heavenly Father is with you in every one! What is something this is the right time for tonight?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-12-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What are some of the times the teacher talked about?”", "“Who is with us in every season and time?”", "“What is something this is the right time for tonight?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-12-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w2-n6', 9, 'Week 2 · Night 6', 'Remember Him While You’re Little', 'Ecclesiastes 12', '[{"type": "cover", "img": "images/book/sep-13-0.jpg", "alt": "Cover illustration for “Remember Him While You’re Little”"}, {"type": "story", "img": "images/book/sep-13-1.jpg", "alt": "Illustration: The wise teacher of Ecclesiastes had one very special piece of advice, just for young people like you.", "text": ["The wise teacher of Ecclesiastes had one very special piece of advice, just for young people like you.", "“Remember Heavenly Father now, while you are young!” he said. Don’t wait until you’re big and grown up — start loving Him today.", "When we’re little, our hearts are soft and ready to learn, like fresh soil ready for seeds. It’s the perfect time to plant love for Heavenly Father deep inside."]}, {"type": "story", "img": "images/book/sep-13-2.jpg", "alt": "Illustration: Every prayer you say, every story you hear, every kind thing you do helps you know Heavenly Father better — ri…", "text": ["Every prayer you say, every story you hear, every kind thing you do helps you know Heavenly Father better — right now, while you’re small.", "You don’t have to wait to be a friend of Heavenly Father. You can start today, and grow closer to Him every single day of your happy life."]}, {"type": "moment", "img": "images/book/sep-13-3.jpg", "alt": "Illustration: Scout fits tonight because Scout loves to start the adventure of knowing Heavenly Father early.", "text": ["Scout fits tonight because Scout loves to start the adventure of knowing Heavenly Father early. In Scout’s world today: Scout’s big cousin said, “You’re too little to say prayers by yourself.” But Scout said, “No I’m not — I can start now!” and folded little arms and prayed a sweet, simple prayer all alone. Just like the wise teacher said to remember Heavenly Father while young, Scout discovered you’re never too little to know Him."], "eyebrow": "Scripture Traveler of the Night", "heading": "Scout the Seeker"}, {"type": "moment", "img": "images/book/sep-13-4.jpg", "alt": "Illustration: Let’s start now!", "text": ["Let’s start now! Point to yourself and say, “I can love Heavenly Father today!” Now plant a pretend seed in your heart and watch it grow tall. Can you show me your heart growing love for Him, starting right now?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["You don’t have to wait until you’re grown up to know Heavenly Father — you can start today, while you’re little! What is one way you can grow closer to Heavenly Father right now?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-13-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“When did the wise teacher say to remember Heavenly Father?”", "“Are you ever too little to love Heavenly Father?”", "“What is one way you can grow closer to Heavenly Father right now?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-13-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w2-n7', 9, 'Week 2 · Night 7', 'A Good Name', 'Proverbs 22', '[{"type": "cover", "img": "images/book/sep-14-0.jpg", "alt": "Cover illustration for “A Good Name”"}, {"type": "story", "img": "images/book/sep-14-1.jpg", "alt": "Illustration: Wise Solomon shared one more treasure: he said a good name is better than piles of gold and silver.", "text": ["Wise Solomon shared one more treasure: he said a good name is better than piles of gold and silver.", "What is a “good name”? It means being someone people can trust — someone honest, kind, and true. When you do good, your name becomes a good name.", "Solomon knew that money and toys come and go. But being a good, honest person is a treasure that lasts forever."]}, {"type": "story", "img": "images/book/sep-14-2.jpg", "alt": "Illustration: Every time you tell the truth, keep a promise, or do the right thing, you’re building your good name — like ad…", "text": ["Every time you tell the truth, keep a promise, or do the right thing, you’re building your good name — like adding a shiny brick to a strong, tall wall.", "Heavenly Father is so happy when we choose to be honest and good. A good name is one of the best treasures of all, and you can build yours every day."]}, {"type": "moment", "img": "images/book/sep-14-3.jpg", "alt": "Illustration: Beau fits tonight because he chooses to be honest, even when it’s hard.", "text": ["Beau fits tonight because he chooses to be honest, even when it’s hard. In Beau’s world today: Beau accidentally broke a little toy while playing. No one saw. He could have stayed quiet — but his tummy felt yucky. So he took a brave breath and told the truth: “I broke it, and I’m sorry.” His mom hugged him and said, “Thank you for being honest.” Just like Solomon said a good name is a treasure, Beau built his good name by telling the truth."], "eyebrow": "Scripture Traveler of the Night", "heading": "Beau the Brave"}, {"type": "moment", "img": "images/book/sep-14-4.jpg", "alt": "Illustration: Let’s build a good name!", "text": ["Let’s build a good name! Stand up tall and proud, put your hand on your heart, and say, “I will be honest and good!” Now stack pretend bricks, one on top of another. Can you build your strong, good name nice and tall?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["A good name — being honest, kind, and true — is a treasure worth more than gold, and you build it every time you do right! When could it be brave to tell the truth this week?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-14-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did Solomon say is better than gold and silver?”", "“How do we build a good name?”", "“When could it be brave to tell the truth this week?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-14-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w3-n1', 9, 'Week 3 · Night 1', 'White as Snow', 'Isaiah 1', '[{"type": "cover", "img": "images/book/sep-15-0.jpg", "alt": "Cover illustration for “White as Snow”"}, {"type": "story", "img": "images/book/sep-15-1.jpg", "alt": "Illustration: Long ago, Heavenly Father sent a prophet named Isaiah to share His messages.", "text": ["Long ago, Heavenly Father sent a prophet named Isaiah to share His messages. One of Isaiah’s most beautiful messages was full of love and hope.", "Sometimes people made wrong choices, and their hearts felt dark and heavy, like a shirt with big red stains.", "But Heavenly Father said something wonderful through Isaiah: “Come, let’s talk it over. Even if your mistakes are as red as scarlet, I can make you as white and clean as fresh snow!”"]}, {"type": "story", "img": "images/book/sep-15-2.jpg", "alt": "Illustration: Isn’t that amazing?", "text": ["Isn’t that amazing? When we’re truly sorry and come to Heavenly Father, He washes our hearts pure and clean — whiter than the whitest snow.", "No mistake is too big for Heavenly Father’s love. He always welcomes us back and makes us clean and new. That is His happy promise to you."]}, {"type": "moment", "img": "images/book/sep-15-3.jpg", "alt": "Illustration: Willow fits tonight because she knows the gift of being made clean and new.", "text": ["Willow fits tonight because she knows the gift of being made clean and new. In Willow’s world today: Willow said an unkind word to her friend and felt a heavy, yucky feeling inside. She went back, gave a hug, and said, “I’m sorry — that wasn’t kind.” Right away her heart felt light and clean, like fresh snow. Just like Heavenly Father’s promise to make our hearts white as snow, Willow found that saying sorry brings a clean, happy heart."], "eyebrow": "Scripture Traveler of the Night", "heading": "Willow the Warm"}, {"type": "moment", "img": "images/book/sep-15-4.jpg", "alt": "Illustration: Let’s think of clean, white snow!", "text": ["Let’s think of clean, white snow! Wiggle your fingers down slowly like gentle snowflakes falling, then brush your hands over your heart — all clean! Can you show me your fresh, snowy-clean heart?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["No mistake is too big — when you’re sorry, Heavenly Father washes your heart white as snow, clean and new! What helps you feel better after you’ve made a mistake?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-15-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did Heavenly Father promise to make our hearts like?”", "“Is any mistake too big for Heavenly Father’s love?”", "“What helps you feel better after you’ve made a mistake?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-15-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w3-n2', 9, 'Week 3 · Night 2', 'Here Am I, Send Me', 'Isaiah 6', '[{"type": "cover", "img": "images/book/sep-16-0.jpg", "alt": "Cover illustration for “Here Am I, Send Me”"}, {"type": "story", "img": "images/book/sep-16-1.jpg", "alt": "Illustration: One day, the prophet Isaiah had an amazing experience.", "text": ["One day, the prophet Isaiah had an amazing experience. In a beautiful vision, he saw Heavenly Father’s shining throne, high and glorious, filling the temple with light.", "Bright angels flew all around, singing, “Holy, holy, holy!” Everything felt so wonderful and full of Heavenly Father’s love.", "Isaiah felt very small, but an angel gently touched his lips with something warm and bright from the altar. Right away, Isaiah felt clean and ready, and his worries floated away."]}, {"type": "story", "img": "images/book/sep-16-2.jpg", "alt": "Illustration: Then Isaiah heard Heavenly Father ask, “Who will go and share My message with My people?” Isaiah didn’t wait e…", "text": ["Then Isaiah heard Heavenly Father ask, “Who will go and share My message with My people?” Isaiah didn’t wait even a moment.", "“Here am I! Send me!” Isaiah said bravely. He was ready and willing to help Heavenly Father. When Heavenly Father needs a helper, we can be brave and say, “Send me!” too."]}, {"type": "moment", "img": "images/book/sep-16-3.jpg", "alt": "Illustration: Beau the Brave", "eyebrow": "Scripture Traveler of the Night", "heading": "Beau the Brave"}, {"type": "moment", "img": "images/book/sep-16-4.jpg", "alt": "Illustration: Let’s be a willing helper like Isaiah!", "text": ["Let’s be a willing helper like Isaiah! Raise your hand up high like you’re volunteering, and say big and brave, “Here am I — send me!” Can you show me how ready you are to help?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When there’s good work to do, you can be brave and willing like Isaiah and say, “Here am I — send me!” What is a good way you could be a helper tomorrow?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-16-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did the angels sing in Isaiah’s vision?”", "“What did Isaiah say when Heavenly Father needed a helper?”", "“What is a good way you could be a helper tomorrow?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-16-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w3-n3', 9, 'Week 3 · Night 3', 'Come to Heavenly Father’s House', 'Isaiah 2', '[{"type": "cover", "img": "images/book/sep-17-0.jpg", "alt": "Cover illustration for “Come to Heavenly Father’s House”"}, {"type": "story", "img": "images/book/sep-17-1.jpg", "alt": "Illustration: Isaiah shared a happy message about a special place: Heavenly Father’s holy house, the temple.", "text": ["Isaiah shared a happy message about a special place: Heavenly Father’s holy house, the temple.", "“In the last days,” Isaiah said, “Heavenly Father’s house will stand up high on a mountain, and people from everywhere will want to go there!”", "“Come,” the people will say to each other. “Let’s go up to Heavenly Father’s house! He will teach us His good ways, and we will walk in His paths.”"]}, {"type": "story", "img": "images/book/sep-17-2.jpg", "alt": "Illustration: The temple is a peaceful, holy place where we feel very close to Heavenly Father.", "text": ["The temple is a peaceful, holy place where we feel very close to Heavenly Father. It’s like His special home, full of light and quiet love.", "We can love going to Heavenly Father’s house too. Whether it’s the temple or church, it’s a wonderful place to feel Him near and learn His gentle ways."]}, {"type": "moment", "img": "images/book/sep-17-3.jpg", "alt": "Illustration: Scout fits tonight because Scout loves the journey to special places.", "text": ["Scout fits tonight because Scout loves the journey to special places. In Scout’s world today: Scout’s family drove to see the temple, all lit up and beautiful. Scout pressed against the window and gasped, “It’s like a castle of light!” On the peaceful grounds, Scout felt happy and calm and close to Heavenly Father. Just like Isaiah’s message about going up to Heavenly Father’s house, Scout discovered how special it feels to be near His holy home."], "eyebrow": "Scripture Traveler of the Night", "heading": "Scout the Seeker"}, {"type": "moment", "img": "images/book/sep-17-4.jpg", "alt": "Illustration: Let’s go up to Heavenly Father’s house!", "text": ["Let’s go up to Heavenly Father’s house! March your feet up a pretend hill — up, up, up — then fold your arms reverently and whisper, “It’s so peaceful here.” Can you show me your quiet, reverent face inside His house?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Heavenly Father’s house is a special, peaceful place where you can feel Him close — and you can be eager to go! How do you feel when you’re in a place that feels close to Heavenly Father?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-17-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“Where did the people want to go up to?”", "“What did they say Heavenly Father would teach them?”", "“How do you feel when you’re in a place that feels close to Heavenly Father?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-17-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w3-n4', 9, 'Week 3 · Night 4', 'A Special Baby Is Coming', 'Isaiah 9', '[{"type": "cover", "img": "images/book/sep-18-0.jpg", "alt": "Cover illustration for “A Special Baby Is Coming”"}, {"type": "story", "img": "images/book/sep-18-1.jpg", "alt": "Illustration: Isaiah shared the happiest secret of all — a promise about a very special baby who would come someday.", "text": ["Isaiah shared the happiest secret of all — a promise about a very special baby who would come someday.", "“Unto us a child will be born!” Isaiah said. “And He will be wonderful. He will be called the Prince of Peace!”", "This special baby was Jesus, Heavenly Father’s own Son. Isaiah told about Him long, long before He was born, because Heavenly Father wanted His people to have hope."]}, {"type": "story", "img": "images/book/sep-18-2.jpg", "alt": "Illustration: Jesus would be a mighty helper, full of love and peace.", "text": ["Jesus would be a mighty helper, full of love and peace. He would show everyone the way back to Heavenly Father.", "Even a long time ago, Heavenly Father was planning something wonderful for His children. He always keeps His promises — and the promise of Jesus was the most wonderful of all."]}, {"type": "moment", "img": "images/book/sep-18-3.jpg", "alt": "Illustration: Wren fits tonight because she loves to wonder about Heavenly Father’s beautiful plans.", "text": ["Wren fits tonight because she loves to wonder about Heavenly Father’s beautiful plans. In Wren’s world today: Wren saw her aunt getting ready for a new baby and wondered, “Isn’t it amazing how Heavenly Father plans good things before they even happen?” She thought about how He promised baby Jesus long ago too. Just like Isaiah wondered at the promise of the Prince of Peace, Wren marveled at Heavenly Father’s wonderful, hope-filled plans."], "eyebrow": "Scripture Traveler of the Night", "heading": "Wren the Wonderer"}, {"type": "moment", "img": "images/book/sep-18-4.jpg", "alt": "Illustration: Let’s think about the happy promise!", "text": ["Let’s think about the happy promise! Rock your arms gently like you’re holding a sweet baby, and whisper softly, “The Prince of Peace is coming.” Can you show me how gently we hold something precious?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Long ago, Heavenly Father promised a special baby — Jesus, the Prince of Peace — because He loves you and wanted you to have hope! What good thing are you feeling hopeful about?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-18-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did Isaiah say the special baby would be called?”", "“Who was the special baby that was promised?”", "“What good thing are you feeling hopeful about?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-18-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w3-n5', 9, 'Week 3 · Night 5', 'The Peaceful Kingdom', 'Isaiah 11', '[{"type": "cover", "img": "images/book/sep-19-0.jpg", "alt": "Cover illustration for “The Peaceful Kingdom”"}, {"type": "story", "img": "images/book/sep-19-1.jpg", "alt": "Illustration: Isaiah shared a dream of a beautiful, peaceful world that Heavenly Father is preparing — a world where nothing…", "text": ["Isaiah shared a dream of a beautiful, peaceful world that Heavenly Father is preparing — a world where nothing is scary and everyone is safe.", "In this happy place, the wolf and the little lamb lie down together as friends. The lion and the calf rest side by side. No one is afraid anymore!", "And guess who leads them all? A little child! “A little child shall lead them,” Isaiah said. Even the smallest one is safe and gentle there."]}, {"type": "story", "img": "images/book/sep-19-2.jpg", "alt": "Illustration: In Heavenly Father’s peaceful world, no one gets hurt and no one is mean.", "text": ["In Heavenly Father’s peaceful world, no one gets hurt and no one is mean. Everything is filled with kindness, safety, and love.", "Heavenly Father wants us to feel that peace even now. When we’re kind and gentle, we bring a little bit of His peaceful world right into our homes today."]}, {"type": "moment", "img": "images/book/sep-19-3.jpg", "alt": "Illustration: Willow fits tonight because she loves to make peace and help everyone feel safe.", "text": ["Willow fits tonight because she loves to make peace and help everyone feel safe. In Willow’s world today: at the park, a big kid and a little kid were both grabbing the same swing and starting to fuss. Willow gently said, “You can both have a turn — I’ll help count!” Soon they were laughing together. Just like Isaiah’s peaceful world where the lamb and lion are friends, Willow helped make a little pocket of peace."], "eyebrow": "Scripture Traveler of the Night", "heading": "Willow the Warm"}, {"type": "moment", "img": "images/book/sep-19-4.jpg", "alt": "Illustration: Let’s make a peaceful world!", "text": ["Let’s make a peaceful world! Pretend to pet a soft, gentle lamb, then a big friendly lion, right next to each other. Now give a calm, happy sigh — “aahh.” Can you show me your most peaceful, gentle face?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Heavenly Father is preparing a peaceful world where everyone is safe — and you can bring a little of that peace today by being kind and gentle! How could you help someone feel peaceful and safe tomorrow?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-19-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“Who lies down together as friends in Isaiah’s peaceful world?”", "“Who leads them all?”", "“How could you help someone feel peaceful and safe tomorrow?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-19-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w3-n6', 9, 'Week 3 · Night 6', 'I Will Trust and Not Be Afraid', 'Isaiah 12', '[{"type": "cover", "img": "images/book/sep-20-0.jpg", "alt": "Cover illustration for “I Will Trust and Not Be Afraid”"}, {"type": "story", "img": "images/book/sep-20-1.jpg", "alt": "Illustration: After all his wonderful messages, Isaiah sang a happy song of trust.", "text": ["After all his wonderful messages, Isaiah sang a happy song of trust. It’s the song this whole week is named after!", "“Heavenly Father saves me!” Isaiah sang. “I will trust in Him, and I will not be afraid.”", "Isaiah knew that when Heavenly Father is with us, we don’t have to be scared. He is our strength when we feel weak, and He is our song when we feel sad."]}, {"type": "story", "img": "images/book/sep-20-2.jpg", "alt": "Illustration: “Heavenly Father is my strength and my song,” Isaiah sang joyfully.", "text": ["“Heavenly Father is my strength and my song,” Isaiah sang joyfully. Even in hard times, Isaiah chose to trust instead of being afraid.", "You can sing Isaiah’s song too! When something feels scary, you can remember: Heavenly Father is with me, so I will trust Him and not be afraid."]}, {"type": "moment", "img": "images/book/sep-20-3.jpg", "alt": "Illustration: Beau fits tonight because he trusts Heavenly Father instead of being afraid.", "text": ["Beau fits tonight because he trusts Heavenly Father instead of being afraid. In Beau’s world today: there was a big thunderstorm, and the loud booms made Beau’s heart jump. But he took a deep breath and remembered Isaiah’s song. “Heavenly Father is with me — I will trust and not be afraid,” he whispered, and he even hummed a little tune until the storm passed. Just like Isaiah sang about trusting and not fearing, Beau turned his scared feeling into a brave, trusting one."], "eyebrow": "Scripture Traveler of the Night", "heading": "Beau the Brave"}, {"type": "moment", "img": "images/book/sep-20-4.jpg", "alt": "Illustration: Let’s sing a brave, trusting song!", "text": ["Let’s sing a brave, trusting song! Stand up tall, put your hands on your heart, and say, “I will trust and not be afraid!” Now hum a happy, brave little tune. Can you show me your bravest, most trusting face?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When something feels scary, you can sing Isaiah’s song — “Heavenly Father is with me, so I will trust and not be afraid!” What could you remember the next time you feel scared?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-20-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did Isaiah say he would NOT be?”", "“What did Isaiah say Heavenly Father was to him?”", "“What could you remember the next time you feel scared?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-20-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w3-n7', 9, 'Week 3 · Night 7', 'Wells of Joy', 'Isaiah 12', '[{"type": "cover", "img": "images/book/sep-21-0.jpg", "alt": "Cover illustration for “Wells of Joy”"}, {"type": "story", "img": "images/book/sep-21-1.jpg", "alt": "Illustration: Isaiah’s happy song had one more joyful part.", "text": ["Isaiah’s happy song had one more joyful part. He sang about drawing up joy like cool water from a deep, wonderful well.", "“With joy you will draw water from the wells of Heavenly Father’s saving love!” Isaiah sang. Imagine a bucket coming up full — not of water, but of happiness!", "When we remember all the good things Heavenly Father does, our hearts fill up with joy, splashing over like a fresh, cool drink on a hot day."]}, {"type": "story", "img": "images/book/sep-21-2.jpg", "alt": "Illustration: And Isaiah didn’t want to keep the joy to himself.", "text": ["And Isaiah didn’t want to keep the joy to himself. “Tell everyone!” he sang. “Sing about the wonderful things Heavenly Father has done!”", "You can draw up joy too, just by remembering Heavenly Father’s love — and then share it with everyone, so the happiness spreads and spreads."]}, {"type": "moment", "img": "images/book/sep-21-3.jpg", "alt": "Illustration: Scout fits tonight because Scout loves to find joy and share it with everyone.", "text": ["Scout fits tonight because Scout loves to find joy and share it with everyone. In Scout’s world today: Scout’s grandma got better after being sick, and Scout was so happy and grateful. Scout couldn’t hold the joy in — running to tell everyone, “Heavenly Father helped Grandma feel better!” Soon the whole family was smiling and thankful. Just like Isaiah sang about drawing up joy and telling everyone, Scout discovered that shared joy grows even bigger."], "eyebrow": "Scripture Traveler of the Night", "heading": "Scout the Seeker"}, {"type": "moment", "img": "images/book/sep-21-4.jpg", "alt": "Illustration: Let’s draw up joy from the well!", "text": ["Let’s draw up joy from the well! Pretend to pull a rope hand over hand — up, up — then lift the happy bucket high and cheer, “Joy!” Now splash the joy to someone you love. Can you draw up your happiest bucket of joy?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["You can fill your heart with joy just by remembering Heavenly Father’s love — and then share it so the happiness grows! What good thing about Heavenly Father could you share with someone tomorrow?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-21-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did Isaiah say we would draw up with joy?”", "“What did Isaiah want everyone to do with the good news?”", "“What good thing about Heavenly Father could you share with someone tomorrow?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-21-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w4-n1', 9, 'Week 4 · Night 1', 'He Wipes Away Every Tear', 'Isaiah 25', '[{"type": "cover", "img": "images/book/sep-22-0.jpg", "alt": "Cover illustration for “He Wipes Away Every Tear”"}, {"type": "story", "img": "images/book/sep-22-1.jpg", "alt": "Illustration: Isaiah shared a message so tender and kind that it feels like a warm hug from Heavenly Father.", "text": ["Isaiah shared a message so tender and kind that it feels like a warm hug from Heavenly Father.", "“Someday,” Isaiah said, “Heavenly Father will wipe away the tears from every face. There will be no more crying, and everyone will be happy!”", "Imagine Heavenly Father gently drying your tears with the softest, most loving touch, whispering, “It’s okay now, My child. Everything is going to be all right.”"]}, {"type": "story", "img": "images/book/sep-22-2.jpg", "alt": "Illustration: Heavenly Father sees every tear we cry.", "text": ["Heavenly Father sees every tear we cry. He cares about every sad feeling, and He loves to comfort us and turn our sadness into joy.", "Even when we feel sad today, we can remember Heavenly Father’s promise: He wipes away tears, and He fills our hearts with comfort and love."]}, {"type": "moment", "img": "images/book/sep-22-3.jpg", "alt": "Illustration: Willow fits tonight because she loves to comfort and dry tears.", "text": ["Willow fits tonight because she loves to comfort and dry tears. In Willow’s world today: Willow’s little cousin was crying because she missed her mommy. Willow didn’t have a way to fix it, but she gently wiped her cousin’s tears and gave her a hug and sat close until she felt better. Just like Heavenly Father’s promise to wipe away every tear, Willow brought comfort with her gentle, loving care."], "eyebrow": "Scripture Traveler of the Night", "heading": "Willow the Warm"}, {"type": "moment", "img": "images/book/sep-22-4.jpg", "alt": "Illustration: Let’s feel Heavenly Father’s comfort!", "text": ["Let’s feel Heavenly Father’s comfort! Pretend to gently wipe a tear from your cheek, then give yourself a soft, warm hug. “It’s going to be okay.” Can you show me a sad face turning into a comforted, peaceful one?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Heavenly Father sees every tear and promises to wipe them all away — He loves to comfort you! Who can give you a comforting hug when you feel sad?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-22-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did Isaiah say Heavenly Father would wipe away?”", "“What does Heavenly Father do when we feel sad?”", "“Who can give you a comforting hug when you feel sad?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-22-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w4-n2', 9, 'Week 4 · Night 2', 'Perfect Peace', 'Isaiah 26', '[{"type": "cover", "img": "images/book/sep-23-0.jpg", "alt": "Cover illustration for “Perfect Peace”"}, {"type": "story", "img": "images/book/sep-23-1.jpg", "alt": "Illustration: Isaiah shared a lovely secret about how to feel calm and peaceful inside, even when the world is busy.", "text": ["Isaiah shared a lovely secret about how to feel calm and peaceful inside, even when the world is busy.", "“Heavenly Father will keep you in perfect peace,” Isaiah said, “when you keep your mind on Him.”", "That means when we fill our thoughts with Heavenly Father — thinking about His love, remembering His stories — our hearts grow calm and quiet and peaceful."]}, {"type": "story", "img": "images/book/sep-23-2.jpg", "alt": "Illustration: It’s like when your mind is buzzing with worries, and then you think one gentle thought about Heavenly Father…", "text": ["It’s like when your mind is buzzing with worries, and then you think one gentle thought about Heavenly Father, and the buzzing settles into soft, warm peace.", "Heavenly Father wants to give you peace. When your thoughts turn to Him, He fills you up with a calm, safe, wonderful peace — the perfect kind."]}, {"type": "moment", "img": "images/book/sep-23-3.jpg", "alt": "Illustration: Wren fits tonight because she knows that thinking about Heavenly Father brings peace.", "text": ["Wren fits tonight because she knows that thinking about Heavenly Father brings peace. In Wren’s world today: Wren felt worried about her first day at a new class — her thoughts were spinning fast. So she closed her eyes and thought about how Heavenly Father loved her and was with her. Slowly, her spinning thoughts grew calm and peaceful. Just like Isaiah said keeping our minds on Heavenly Father brings perfect peace, Wren found calm by thinking of Him."], "eyebrow": "Scripture Traveler of the Night", "heading": "Wren the Wonderer"}, {"type": "moment", "img": "images/book/sep-23-4.jpg", "alt": "Illustration: Let’s find perfect peace!", "text": ["Let’s find perfect peace! Put your hands on the sides of your head, then slowly move them down as you take a deep breath, thinking one calm thought about Heavenly Father. Can you show me your peaceful, settled face?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When your thoughts feel busy or worried, you can think about Heavenly Father — and He fills you with perfect peace! What happy thought about Heavenly Father could you think when you feel worried?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-23-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“How do we get Heavenly Father’s perfect peace?”", "“What happens when we keep our minds on Heavenly Father?”", "“What happy thought about Heavenly Father could you think when you feel worried?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-23-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w4-n3', 9, 'Week 4 · Night 3', 'A Sure, Strong Rock', 'Isaiah 26', '[{"type": "cover", "img": "images/book/sep-24-0.jpg", "alt": "Cover illustration for “A Sure, Strong Rock”"}, {"type": "story", "img": "images/book/sep-24-1.jpg", "alt": "Illustration: Isaiah taught that Heavenly Father is like the strongest, most reliable rock you could ever build on.", "text": ["Isaiah taught that Heavenly Father is like the strongest, most reliable rock you could ever build on.", "“Trust in Heavenly Father forever,” Isaiah said, “for He is like a Rock that lasts always and always.”", "He also said Heavenly Father is like a precious, sure cornerstone — the special, strong stone builders use to hold a whole house together, so it never falls."]}, {"type": "story", "img": "images/book/sep-24-2.jpg", "alt": "Illustration: When we build our lives on Heavenly Father, we’re standing on something that will never wobble, crack, or crum…", "text": ["When we build our lives on Heavenly Father, we’re standing on something that will never wobble, crack, or crumble. He is steady and strong forever.", "No matter what happens around us, Heavenly Father holds us firm. When we trust in Him, we are safe and steady, standing on the strongest Rock of all."]}, {"type": "moment", "img": "images/book/sep-24-3.jpg", "alt": "Illustration: Beau fits tonight because he stands strong on Heavenly Father.", "text": ["Beau fits tonight because he stands strong on Heavenly Father. In Beau’s world today: Beau was learning to balance on the low wall at the park, and his legs felt wobbly and unsure. He remembered that Heavenly Father was his strong Rock, holding him steady. He took a brave breath, steadied himself, and walked the whole way! Just like Isaiah said to trust Heavenly Father, the Rock that lasts forever, Beau found his steady footing by leaning on Him."], "eyebrow": "Scripture Traveler of the Night", "heading": "Beau the Brave"}, {"type": "moment", "img": "images/book/sep-24-4.jpg", "alt": "Illustration: Let’s stand on the strong Rock!", "text": ["Let’s stand on the strong Rock! Plant your feet wide, make your body big and firm, and don’t wobble — steady as a rock! Now say, “Heavenly Father is my strong Rock!” Can you stand as steady and sure as stone?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Heavenly Father is your sure, strong Rock — when you trust in Him, you can stand steady and safe forever! When could you lean on Heavenly Father to feel steady?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-24-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What strong, steady thing did Isaiah say Heavenly Father is like?”", "“What happens when we build our lives on Heavenly Father?”", "“When could you lean on Heavenly Father to feel steady?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-24-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w4-n4', 9, 'Week 4 · Night 4', 'A Marvellous Work and a Wonder', 'Isaiah 29', '[{"type": "cover", "img": "images/book/sep-25-0.jpg", "alt": "Cover illustration for “A Marvellous Work and a Wonder”"}, {"type": "story", "img": "images/book/sep-25-1.jpg", "alt": "Illustration: This week’s book is named after something Isaiah said Heavenly Father would do: “a marvellous work and a wonde…", "text": ["This week’s book is named after something Isaiah said Heavenly Father would do: “a marvellous work and a wonder!”", "That means Heavenly Father does amazing, surprising, wonderful things — things so good and clever that they make us say, “Wow!”", "Isaiah promised that Heavenly Father would do a wonder that would help all His children — teaching and blessing even those who thought they couldn’t learn."]}, {"type": "story", "img": "images/book/sep-25-2.jpg", "alt": "Illustration: Heavenly Father is full of surprises!", "text": ["Heavenly Father is full of surprises! He can make wonderful things happen in ways we never even imagined. His works are truly marvelous.", "When you see something amazing — a rainbow, a new baby, a kind miracle — you can remember: Heavenly Father is still doing marvelous works and wonders, today and always."]}, {"type": "moment", "img": "images/book/sep-25-3.jpg", "alt": "Illustration: Scout fits tonight because Scout loves to discover Heavenly Father’s marvelous wonders.", "text": ["Scout fits tonight because Scout loves to discover Heavenly Father’s marvelous wonders. In Scout’s world today: after a rainstorm, Scout spotted a huge, bright rainbow arching across the whole sky. “How does Heavenly Father DO that?” Scout gasped, staring in wonder. It felt like a marvelous surprise made just for that moment. Just like Isaiah said Heavenly Father does a marvellous work and a wonder, Scout discovered that His amazing works are everywhere."], "eyebrow": "Scripture Traveler of the Night", "heading": "Scout the Seeker"}, {"type": "moment", "img": "images/book/sep-25-4.jpg", "alt": "Illustration: Let’s be amazed at Heavenly Father’s wonders!", "text": ["Let’s be amazed at Heavenly Father’s wonders! Open your eyes and mouth w-i-d-e in a big “WOW!” and throw your hands up in surprise. Heavenly Father does marvelous things! Can you show me your most amazed, wonder-filled face?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Heavenly Father does marvelous works and wonders — amazing, surprising, wonderful things — today and always! What marvelous thing that Heavenly Father made amazes you most?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-25-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did Isaiah say Heavenly Father would do?”", "“What do marvelous works make us want to say?”", "“What marvelous thing that Heavenly Father made amazes you most?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-24-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w4-n5', 9, 'Week 4 · Night 5', 'This Is the Way', 'Isaiah 30', '[{"type": "cover", "img": "images/book/sep-26-0.jpg", "alt": "Cover illustration for “This Is the Way”"}, {"type": "story", "img": "images/book/sep-26-1.jpg", "alt": "Illustration: Isaiah shared a comforting message about how Heavenly Father helps us know which way to go.", "text": ["Isaiah shared a comforting message about how Heavenly Father helps us know which way to go.", "“When you’re not sure which way to turn,” Isaiah said, “you will hear a gentle voice behind you saying, ‘This is the way — walk in it.’”", "Heavenly Father helps guide us, like a kind whisper in our hearts showing us the right path — the good and safe way to go.", "Isaiah also said that being quiet and calm helps us hear Him. “In quietness and trust is your strength,” he taught. When we get still, we can feel Heavenly Father’s gentle guidance."]}, {"type": "story", "img": "images/book/sep-26-2.jpg", "alt": "Illustration: Whenever you don’t know what’s right, you can get quiet, listen with your heart, and trust Heavenly Father to…", "text": ["Whenever you don’t know what’s right, you can get quiet, listen with your heart, and trust Heavenly Father to whisper, “This is the way.” He always helps you find the good path."]}, {"type": "moment", "img": "images/book/sep-26-3.jpg", "alt": "Illustration: Wren fits tonight because she gets quiet and listens with her heart.", "text": ["Wren fits tonight because she gets quiet and listens with her heart. In Wren’s world today: Wren wasn’t sure whether to share her new crayons or keep them all to herself. Instead of rushing, she got quiet and thought about what was kind. In the calm, she felt a gentle nudge in her heart: sharing is the good way. She shared, and it felt right. Just like Isaiah said we hear “this is the way” when we’re quiet and trusting, Wren listened and found the good path."], "eyebrow": "Scripture Traveler of the Night", "heading": "Wren the Wonderer"}, {"type": "moment", "img": "images/book/sep-26-4.jpg", "alt": "Illustration: Let’s listen for the way!", "text": ["Let’s listen for the way! Cup your hand to your ear and get very quiet… then point ahead and whisper, “This is the way!” Now take a peaceful step forward. Can you show me your best quiet- listening ears?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["When you’re not sure what’s right, you can get quiet and listen — Heavenly Father will gently guide you, whispering, “This is the way!” When could you get quiet and listen for the good way?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-26-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What gentle words does Heavenly Father help us hear?”", "“What helps us hear Heavenly Father’s guidance?”", "“When could you get quiet and listen for the good way?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-26-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w4-n6', 9, 'Week 4 · Night 6', 'The Desert Blooms', 'Isaiah 35', '[{"type": "cover", "img": "images/book/sep-27-0.jpg", "alt": "Cover illustration for “The Desert Blooms”"}, {"type": "story", "img": "images/book/sep-27-1.jpg", "alt": "Illustration: Isaiah painted the most beautiful picture of hope.", "text": ["Isaiah painted the most beautiful picture of hope. He told about a dry, empty desert — and then something wonderful happened!", "“The desert will be glad,” Isaiah said, “and the dry, thirsty ground will burst into bloom with flowers! It will blossom like a beautiful rose.”", "Imagine a bare, brown place suddenly filling up with soft green grass, splashing streams, and bright, happy flowers everywhere. That’s what Heavenly Father can do!"]}, {"type": "story", "img": "images/book/sep-27-2.jpg", "alt": "Illustration: Heavenly Father can bring beautiful life to even the driest, saddest places.", "text": ["Heavenly Father can bring beautiful life to even the driest, saddest places. He turns empty into full, and sad into glad, and brown into bloom.", "When your heart feels dry or sad, remember: Heavenly Father can make good things bloom again. With Him, there is always hope for something beautiful."]}, {"type": "moment", "img": "images/book/sep-27-3.jpg", "alt": "Illustration: Willow fits tonight because she believes good things can bloom again.", "text": ["Willow fits tonight because she believes good things can bloom again. In Willow’s world today: Willow’s favorite little plant looked droopy and brown, and she felt sad. But Mom showed her how to water it and set it in the sun. Day by day, it grew green and even sprouted a tiny flower! Willow clapped with joy. Just like Isaiah’s desert that blossomed like a rose, Willow learned that with gentle care and hope, beautiful things can bloom."], "eyebrow": "Scripture Traveler of the Night", "heading": "Willow the Warm"}, {"type": "moment", "img": "images/book/sep-27-4.jpg", "alt": "Illustration: Let’s watch the desert bloom!", "text": ["Let’s watch the desert bloom! Crouch down small like dry, cracked ground, then slowly grow up and open your arms wide like a flower bursting into bloom. Can you show me the empty desert blossoming into a beautiful garden?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Heavenly Father can make good things bloom, even in the driest, saddest places — so there’s always hope for something beautiful! What is something you’re hopeful will get better and bloom?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-27-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did Isaiah say the dry desert would do?”", "“What can Heavenly Father do to dry, sad places?”", "“What is something you’re hopeful will get better and bloom?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-27-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

insert into public.book_nights (id, book, night, title, reference, beats) values
  ('b9-w4-n7', 9, 'Week 4 · Night 7', 'Be Strong, Don’t Be Afraid', 'Isaiah 35', '[{"type": "cover", "img": "images/book/sep-28-0.jpg", "alt": "Cover illustration for “Be Strong, Don’t Be Afraid”"}, {"type": "story", "img": "images/book/sep-28-1.jpg", "alt": "Illustration: Isaiah’s beautiful message ended with words of courage and joy — a wonderful way to finish the whole month!", "text": ["Isaiah’s beautiful message ended with words of courage and joy — a wonderful way to finish the whole month!", "“Be strong, and don’t be afraid,” Isaiah said. “Heavenly Father is coming to help you and save you!”", "In Isaiah’s happy picture, wonderful things happen: streams splash through the desert, and everyone who was sad leaps and sings for joy. “Sorrow and sighing fly away!”"]}, {"type": "story", "img": "images/book/sep-28-2.jpg", "alt": "Illustration: Isaiah even told of a special, safe road — a happy path that leads home to Heavenly Father, where His people w…", "text": ["Isaiah even told of a special, safe road — a happy path that leads home to Heavenly Father, where His people walk and sing with joy forever.", "So be strong and brave, little one! Heavenly Father is always helping you and leading you home. And on the way, He fills our hearts with singing, and turns all our sorrow into joy."]}, {"type": "moment", "img": "images/book/sep-28-3.jpg", "alt": "Illustration: Beau fits tonight because his courage carries him all the way to joy.", "text": ["Beau fits tonight because his courage carries him all the way to joy. In Beau’s world today: Beau felt nervous about riding his bike without training wheels — it seemed so hard and a little scary. But he remembered to be strong and not afraid, took a deep breath, and pushed off. Wobble, wobble — then he was riding! He leaped off, cheering with pure joy. Just like Isaiah said, “Be strong, don’t be afraid,” Beau’s brave heart turned into a happy, joyful one."], "eyebrow": "Scripture Traveler of the Night", "heading": "Beau the Brave"}, {"type": "moment", "img": "images/book/sep-28-4.jpg", "alt": "Illustration: Let’s be strong and joyful!", "text": ["Let’s be strong and joyful! Flex your muscles strong — “I am brave!” — then leap up high and cheer, “Joy!” Sorrow flies away! Can you show me strong and brave, then leaping with joy?"], "eyebrow": "Move &middot; Imagine &middot; Connect", "heading": "A Feeling Moment"}, {"type": "moment", "text": ["Be strong and don’t be afraid — Heavenly Father is always helping you and leading you home, and He turns sorrow into joy! What is something brave and strong Heavenly Father can help you do?"], "eyebrow": "Sweet boys &amp; girls", "heading": "Remember This"}, {"type": "moment", "img": "images/book/sep-28-6.jpg", "alt": "A parent and child talking together at bedtime", "text": ["“What did Isaiah say to be, instead of afraid?”", "“What happens to sorrow and sighing in Isaiah’s happy message?”", "“What is something brave and strong Heavenly Father can help you do?”"], "eyebrow": "Question for the child", "heading": "Parent Prompt"}, {"type": "moment", "img": "images/book/sep-28-7.jpg", "alt": "A parent sharing a memory with the family gathered close", "eyebrow": "Testimony", "heading": "Parent Experience"}, {"type": "end"}]'::jsonb)
on conflict (id) do update set
  book = excluded.book, night = excluded.night, title = excluded.title,
  reference = excluded.reference, beats = excluded.beats, updated_at = now();

-- ---------------------------------------------------------------------
-- WHICH STORIES ARE FREE
-- The same three as meta.freeStoryIds in data/virtue-library.js. Keep the
-- two lists the same, or a story is free in one place and not the other.
-- ---------------------------------------------------------------------
update public.book_nights set is_free = (id in ('b6-w3-n1', 'b7-w1-n7', 'b6-w3-n4'));

-- ---------------------------------------------------------------------
-- DID IT WORK? Last statement, so this is what the Results panel shows.
-- ---------------------------------------------------------------------
select book, count(*) as nights,
       count(*) filter (where is_free) as "free ones"
  from public.book_nights group by book order by book;
